window.__D("text/or-torah/c005",{"p":[[400080479,"תטו\n\n<b>אם</b> אין אני לי מי לי וכו'. כי צריך בתפילה להיות כמו מופשט מהגשמיות. [וזהו שאמר אם אין אני לי, ר\"ל בזמן שאני מופשט מהגשמיות] ואיני מרגיש במציאותי בעוה\"ז. כלומר כשאני אבוא למדריגה שלא אדע וארגיש כלל אם אני בעוה\"ז או לאו, בוודאי אין לי שום פחד ממחשבה זרה, כי אז איזה מחשבה זרה יקרב אלי בהיותי מופשט מזה העולם. וזהו מי לי, ר\"ל איזה מחשבה זרה יבוא לי.\n<b>אבל</b> כשאני לעצמי, ר\"ל כשאני חושב עצמי לדבר יש במציאות זה העולם, אז אדרבא איני נחשב לכלום. וז\"ש מה אני, ר\"ל מה אני חשוב, ומה עבודתי חשובה לפניו ית', כי אז יבלבלו אותי מחשבות זרות, והריני כמו שאיני בעוה\"ז. כי עיקר בריאת האדם [בעוה\"ז היא] לעבודה [נ\"א: לעבדה ולשמרה], והרי אין אני יכול לעבוד עבודתי מחמת מחשבות זרות המבלבלים אותי.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ב, א (סי' מא). אוה\"א קה, א. צוה\"ר סי' סב.</b>\n<i>אם אין אני לי כו'</i> – אבות פ\"א מי\"ד.<i> בתפלה . . מופשט מהגשמיות</i> – ראה טושו\"ע או\"ח רסי' צח.<i> כשאני לעצמי מה אני</i> – אבות שם.<i> עיקר בריאת האדם לעבודה</i> – ראה קידושין פב, א.<i> לעבדה ולשמרה</i> – ע\"פ בראשית ב, טו. ראה שם בתיב\"ע. זח\"א כז, א.\n----- הערות וציונים -----\nלקמן סי' תלב בקיצור.\n<i>צריך בתפלה להיות כמו מופשט מהגשמיות</i> – ראה טושו\"ע או\"ח ריש סי' צח.\n<i>ואיני מרגיש במציאותי בעוה\"ז כו'</i> – ראה סוף סי' רפא וסי' תכט. וראה לקו\"י סוף סי' מט (בכש\"ט סי' קצט-א). כש\"ט סי' רלט-ב ורמ-א, ובהערות שם.\n<i>בוודאי אין לו שום פחד ממ\"ז כו'</i> – ראה סי' רצו אם האדם מחזיק א\"ע לאי\"ן מחזיק דביקות בהקב\"ה, והאי\"ן אינו מתאוה לכלום (סי' רמח סד\"ה והנה בצדיקים, וש\"נ בהערות, וסי' שפז-ג).\n<i>כשאני חושב עצמי לדבר יש כו'</i> – דאז דבוק בתאוות עוה\"ז (סי' שפז-ג).\n<i>עיקר בריאת האדם לעבודה</i> – ראה ריש סי' מח."]]],[400080480,"תטז\n\n<b>איזהו</b> גבור הכובש את יצרו [שנאמר טוב ארך אפים מגבור]. יש לדקדק איזה\"ו משמע שמדבר מב' בני אדם ושואל איזה מהם גבור, והוי ליה למימר מי נקרא גבור הכובש וכו'. ועוד יש לדקדק, שמלשון הפסוק משמע איפכא, שהכתוב אומר טוב ארך אפים מגבור, משמע מי שהוא מאריך אף, דהיינו הכובש את יצרו, חשוב יותר מגבור. ויש לומר כי יש ב' מיני צדיקים, א' שאינו מניח את יצרו לקרב אליו כלל וקודם בואו מרחיקו מעליו, ויש צדיק ב' שמניח אותו לבוא, אך כובשו שלא להסיתו לעבירה. למשל כשיצה\"ר מסיתו לחמדה, אומר ליצה\"ר אעשה כדבריך שאלך אחר חמדה, אך אחר חמדה של מצוה, והולך ולומד תורה בחשק גדול ובחמדה גדולה. וכן בכל דבר שמסיתו למדה רעה, הוא לוקח אותה מדה לעבודת השי\"ת. אך מי מהם יותר משובח, הצדיק הב' יותר משובח.\n<b>והוא</b> ע\"ד השכל, למשל אדם שישן בחנות לשמור הסחורה, ולא היה הדלת [סגור] בבריח חזק, ושמע באמצע הלילה שגנב אחד בא ועושה תחבולות לפתוח הדלת. וכאשר שמע זה היה ירא לנפשו, והתחיל לצעוק בקול גדול לבני ביתו שיבואו, כי ירא מהגנב, וברח הגנב [מחמת הצעקה]. ומעשה כזה אירע לאיש אחר, ואותו אחר כששמע שגנב בא שתק כמו שאינו שומע. וכשבא הגנב לחנות בפנים, תפס אותו ואסרו בנחושתיים. אבל לא היה רוצה לצעוק כדי שיברח הגנב, כי אמר בדעתו לכשיברח הגנב שמא יבוא [עוד] בלילה זה או בלילה אחר, ושמא אהיה נרדם בשינה ולא אשמע, ויעשה הגנב זה מה שלבו חפץ, אך אעשה לו דבר שלא יוסיף לגנוב עוד, כי בוודאי יפול עליו פחד שלא יתפסו אותו ויענש ביסורים קשים כבראשונה. והנמשל מובן מאיליו.\n<b>וזהו</b> פירוש האמור, איזהו גבור הכובש את יצרו, כלומר איזה מב' צדיקים הללו נקרא גבור, הכובש את יצרו, ולא זה שאינו מניחו לקרב אצלו כלל. שנאמר טוב ארך אפים מגבור, ר\"ל זה שמאריך אף, דהיינו היצה\"ר נקרא א\"ף, שהיצה\"ר תמיד אצלו, ועם כל זה הוא כובש אותו, זהו טוב ומשובח יותר מצדיק הא' שאינו מניחו לקרב אצלו כנזכר. ומושל ברוחו, ר\"ל מי שהוא מושל על היצה\"ר וכובש אותו, הוא יותר משובח מלוכד עיר. כי מי שהוא לוכד עיר בוודאי מגרש את האנשים תחילה ואחר כך בא לעיר, אבל זה אינו מגרש את היצר הרע רק כובשו כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ב, ב (סי' מג). אוה\"א קד, ב (והרישא שם ג\"כ בדף מא, א).</b>\n<i>איזהו גבור כו'</i> – אבות פ\"ד מ\"א.<i> טוב ארך אפים מגבור</i> – משלי טז, לב.<i> היצה\"ר נקרא א\"ף</i> – זו\"ח רות עח, ג (ע\"פ נוסח דפוס ליוורנו דף צו, א).\n----- הערות וציונים -----\nראה בהוספות לכש\"ט סי' שצו.\n<i>אומר ליצה\"ר אעשה כדבריך כו' אך אחר חמדה של מצוה כו'</i> – ראה סי' רמו ובהערות שם."]]],[400080481,"תיז\n\n<b>חותמו</b> של הקב\"ה אמ\"ת. כי אותיות אמת הם ראשון ואחרון ואמצעי של הכ\"ב אותיות, והוא סוד לרמוז שהקב\"ה מלא כל עלמין, מגו כל עלמין ומבחוץ של כל עלמין, ולית אתר פנוי מיניה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א קה, א.</b>\n<i>חותמו של הקב\"ה אמ\"ת</i> – שבת נה, א.<i> אותיות אמת הם כו'</i> – בר\"ר פא, ב וש\"נ. תקו\"ז תס\"ג צד סע\"ב.<i> מלא כל עלמין כו'</i> – זח\"ג רכה, א.<i> ולית אתר פנוי מיניה</i> – תקו\"ז תנ\"ז צא סע\"ב. שם ת\"ע קכב, ב.\n----- הערות וציונים -----\nלהעיר מסי' שכו."]]],[400080482,"תיח\n\n<b>ג'</b> ספרים נפתחין בר\"ה וכו'. צדיקים גמורים הם שכל דיבורם בדברי קדושה, בתפילה ובתורה, ליחד הדיבור בעולם המחשבה. שבכל תפילה ודברי תורה צריך להאמין שמייחד בוודאי עולם הדיבור בעולם המחשבה אם היא בכוונה. ואע\"פ שמתפלל ואין נותנים לו בקשתו מה שהוא מתפלל, עם כל זה, באתערותא דלתתא שהוא מיחד עולם הדיבור בעולם המחשבה, בזה הוא גורם למעלה ג\"כ כזה. ואלו בני אדם שכל כוונתם לייחד עולם הדיבור עם עולם המחשבה הם צדיקים גמורים.\n<b>וז\"ש</b> רז\"ל אין עומדים להתפלל אלא מתוך כובד ראש, ר\"ל שיחשוב מה שחסר לו. וכן בשלומו לא יפסיק<sup data-n=\"1\">כ</sup>, דהיינו כשמתפלל בכוונה אז הקב\"ה מתפאר בעולם הדיבור ובא ההתפארות בכל העולמות, ונופל עליו ג\"כ התפארות. ויזהר שלא (יחשוב) [יבטל] מהדביקות שיש לו, לחשוב בהתפארות שלו איך הוא מתפלל בכוונה גדולה.\n<b>בינונים</b> הם אותן בני אדם שבתפילתם מכוונים גם לזה שיעשה הקב\"ה בקשתם מה שהם צריכים צורכי עוה\"ז, הם תלוין ועומדין עד יוה\"כ, ר\"ל עולם המחשבה הנקרא יוה\"כ. ר\"ל תלוי ועומד על המחשבה, ר\"ל אחרי כוונת הלב [נ\"א: אחרי כוונתן]. אם כוונתם לשם שמים בבקשת צורכי עוה\"ז, כדי שיהיו פנוים לעבודתו יתברך, אז גם הם נכתבין לחיים, כי גם בכוונתם נתייחד עולם הדיבור עם עולם המחשבה. וג' ספרים, רצה לומר דיבורים.",[["","","----- מקורות ומראה מקומות -----\n<b>צוה\"ר סי' קכג.</b>\n<i>ג' ספרים כו' צדיקים כו' בינונים כו'</i> – ר\"ה טז, ב.<i> באתערותא דלתתא . . גורם למעלה ג\"כ כזה</i> – זח\"א קצה, ב. שם רמד, א. זח\"ב קפד רע\"ב.<i> אין עומדין כו'</i> – ברכות ל, ב.<i> בשלומו לא יפסיק</i> – ראה ברכות שם.<i> עולם המחשבה הנקרא יוה\"כ</i> – (בינה) ראה ריש תקוזו\"ח צג, ב. זח\"ב קפה, א. זח\"ג ק, ב. שם קב, א-ב.<i> ספרים ר\"ל דיבורים</i> – ראה ס\"י פ\"א מ\"א ובמפרשים שם.\n----- שולי הגליון -----\n<b>כ</b> ) <i>ע\"פ המשך לשון המשנה שם, אפילו המלך שואל בשלומו כו' לא יפסיק</i>.\n----- הערות וציונים -----\nהרישא (ד\"ה ג' ספרים) והסיפא (ד\"ה בינונים) בנו\"א במדל\"י סי' נח (עא).\n<i>ליחד הדיבור בעולם המחשבה</i> – ראה סי' צ ד\"ה וזהו איילה (ואילך), וסי' שיז. וראה מדל\"י סי' לט (מב), שם סי' נג (סו) וסי' קמה (קנג).\n<i>שבכל תפלה וד\"ת צריך להאמין כו'</i> – להעיר מסי' פד-ב, וכש\"ט סי' פ וסי' פא.\n<i>ואע\"פ שמתפלל ואין נותנים לו כו'</i> – ראה כש\"ט סי' פ וסי' קלח ובהערות שם. עיין ספר העיקרים מ\"ד פכ\"ד, וס' בית אלקים להמבי\"ט שער התפלה פי\"ז, ובהערה הסמוכה.\n<i>וז\"ש רז\"ל אין עומדין להתפלל כו'</i> – עיין ריש סי' נו וסי' תנ, ובהערות שם.\n<i>וכן בשלומו לא יפסיק כו'</i> – עיין לקו\"א מב, ב: אפילו המלך שואל בשלומו, פי' כשהדיבור בא למעלה יש להקב\"ה תענוג, והקב\"ה שורה בכל העולמות ונולד תענוג בכל העולמות, וגם באדם נולד בשביל זה התלהבות כי גם הוא חלק אלוה ממעל, אמנם לפי מה שהוא אדם אם הוא צדיק נולד בו התלהבות ואם לאו ח\"ו נולדה בו גאוה כי מעורר מדת התפארות ואם הוא רשע נולדה בו התפארות רעה. וזהו פי' המלך שואל בשלומו, שתבוא לו פניה ח\"ו שהקב\"ה שואל בשלומו, כי שלום נקרא התקשרות והקב\"ה רוצה שיקשר הדיבור שלו אליו ית', אולי יפסיק מכח זה התפלה. וכן עד\"ז בשמועה טובה נד, ב: וז\"פ אפילו המלך, מלכו של עולם, שואל בשלומו לא ישיבנו מדביקות הבורא; ואפילו נחש כו', הוא מחשבות זרות, לא יפסיק מגדולת הבורא ב\"ה וב\"ש וד\"ל שהוא בקיצור.\n<i>אם כוונתם לש\"ש בבקשת צורכי עוה\"ז כו'</i> – ראה סי' רסט. ועיין היטב בלקוטי שיחות חי\"ט ע' 292 ואילך (ראה לעיל בהערות לסוף סי' נו)."]]],[400080483,"תיט\n\n<b>העוסק</b> בתורה לשמה, פירוש לשם ה'. זוכה לדברים הרבה, פי' ממילא נתרבה אליו הדיבור בחכמת התורה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ג, ג (סי' עו). אוה\"א צו, א.</b>\n<i>העוסק בתורה לשמה זוכה כו'</i> – אבות פ\"ו מ\"א.<i> לשמה פירוש לשם ה'</i> – פע\"ח ריש שער הנהגת הלימוד. שער המצות פ' ואתחנן ד\"ה ענין מ\"ש רז\"ל.\n----- הערות וציונים -----\nלהעיר מכש\"ט סי' צו-א, ושם סי' קכז-ב, ועיי\"ע שם סי' תכו, ולקמן סי' תנג."]]],[400080484,"תכ\n\n<b>כשאדם</b> מדבר דיבור טוב, והדיבור הוא החיות של האדם, והחיות הוא ממנו יתברך, אז הדיבור סלקא לעילא ומתעורר הדיבור העליון ומשפיע עליו יותר חיות מלמעלה. אבל כשהוא מדבר דיבור רע, אזי יוצא ממנו החיות, ולעילא ג\"כ לא סלקא, אז קרוב הדבר להיות נפסק ממנו כל החיות לגמרי. וזה ג\"כ מה שאומרים בלשון אשכנז (<sup data-n=\"1\">כא</sup>ער האָט אויס-גירעט).",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ג, ג (סי' עז). אוה\"א צו, א. צוה\"ר סי' קג.</b>\n<i>והדיבור הוא החיות של האדם כו'</i> – ראה לקו\"ת, וספר הליקוטים, פ' עקב ד\"ה כל המצוה.\n----- שולי הגליון -----\n<b>כא</b> ) <i>במקבילות אין סוגריים</i>.\n----- הערות וציונים -----\n<i>כשאדם מדבר דיבור טוב . . ומשפיע עליו כו'</i> – עיין כש\"ט סי' רעג-ב ורצט-א.\n<i>והדיבור הוא החיות של האדם כו' ממנו ית'</i> – [ראה בהנסמן במ\"מ מלקו\"ת להאריז\"ל ומש\"כ על זה במדבר קדמות להחיד\"א, מערכת ד' אות כא (דיבור). ובלב דוד פכ\"ב ופכ\"ג.]\nעיין ס' ערבי נחל פ' וישלח בריש ד\"ה ואמר עוד נפשי יצאה בדברו: כי הנה כ' הבעש\"ט זלל\"ה כי ענין רוח האדם בקרבו וחיות שלו הוא כח הדיבור אשר בקרבו, וכמשה\"כ ויפח באפיו נשמת חיים ויהי האדם לנפש חיה ומתרגמינן לרוח ממללא, ולפ\"ז כשהאדם מדבר דיבורים אזי הדיבורים ההם הן הן חיותו ויוצא חיות שלו באותן הדיבורים, רק שלהיות חיות האדם דבוק תמיד בשורשו לכן הדיבורים ההמה עצמן ממשיכים עליו משרש חיות חדש ועי\"ז חי תמיד, אף שבכל דיבור יוצא חיות מקרבו רק כל דיבור עצמו מביא לו חיות חדש עכ\"ד. (ועיי\"ש בהמשך מה שהאריך בענין דיבורים טובים ודיבורים לא טובים, ושם: כאשר האדם מדבר דיבורים טובים הנה אף שנפשו יוצאת ממנו אין לו פסידא בדבר כי אדרבה נמשך לו נפש וחיות חדש ממקום הקדוש ההוא, נמצא שאותו חיות עצמו שיוציא הוא הבא לו ביתר שאת ויתר עוז, משא\"כ בדברו דיבורים רעים אז נפשו הטובה יוצאה ורעה באה תחתיה וזה הפסד גדול כו' עיי\"ש. וכן עד\"ז בס' דודאים בשדה פ' בהעלתך: נודע מהבעש\"ט שהאדם ע\"י דיבורו יוצא ממנו החיות, רק ע\"י דיבורי קדושה תורה ותפלה בא לו חיות חדש ע\"ד והחיות רצוא ושוב). ועיין לקו\"י סי' קב. ולהעיר מס' מדבר קדמות שם.\n<i>הדיבור סלקא לעילא ומתעורר כו'</i> – ראה זח\"ג לא, ב (הובא בר\"ח שער הקדושה ספ\"י עיי\"ש). וראה עוד זח\"ב מז, ב וזח\"ג קה, א."]]],[400080485,"תכא\n\n<b>כל</b> העוסק בתורת עולה כאילו הקריב עולה. מפני כי כאשר הוא מדבר באותן הדיבורים ביראה ואהבה, אז הוא נותן חיות חדש באלו הדיבורים. אע\"פ שנתקלקלו מחמת חטאים, (והם) [אף על פי כן הם] לבושין דמלכא. אבל כשהיה [בית] המקדש קיים והיה מקריב קרבן עולה, היה נותן כח אף בעולם המעשה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' לב (סוף סי' לה). אוה\"א כט, ב. שם מה, ב. כתבי קודש לא, ב. שמועה טובה נה א.</b>\n<i>כל העוסק בתורת עולה כו'</i> – תנחומא צו יד. ראה מנחות קי, א.<i> מקריב קרבן כו' כח אף בעולם המעשה</i> – ראה זח\"א נח סע\"ב. שם רמד, א. זח\"ג מא, א.\n----- הערות וציונים -----\nראה לעיל סי' תכ ובהערות שם. וראה מדל\"י סי' לא (לה)."]]],[400080486,"תכב\n\n<b>כל</b> עיר שגגותיה גבוהים מבית הכנסת לסוף נחרב. פירוש, האדם שיש לו גדלות וגבהות, והעושה כזה, כביכול שעושה את עצמו גבוה מהשכינה, כמ\"ש אין אלקים כל מזימותיו, ואומרים מי אדו\"ן לנו. והשכינה נקראת אדנ\"י, ונקראת ג\"כ בית הכנסת. וזהו גבוה מבית הכנסת, לסוף נחרב אדם זה (<sup data-n=\"1\">כב</sup>ואפשר לומר תיבת נחר\"ב רומזת נ' חר\"ב, ר\"ל מזה הנזכר הנקרא נ' ונקרא חר\"ב נוקמת נקם ברית. כי מזאת המדה [עצמה] באה לו החרב והחורבן, כמו שכתוב והארץ מתקוממת לו.)",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' כא (כד). אוה\"א מז, ב.</b>\n<i>כל עיר כו'</i> – שבת יא, א.<i> אין אלקים כל גו'</i> – תהלים י, ד.<i> מי אדון לנו</i> – תהלים יב, ה.<i> והשכינה נק' אד'</i> – זח\"ג יא, א. זח\"א יז סע\"ב.<i> ונקראת ג\"כ בית הכנסת</i> – תקוזו\"ח קטו, א. זח\"ג רפב רע\"א ושם רע\"ב.<i> הנקרא נ'</i> – ראה זח\"ג סו ב (נ' כפופה דא מטרוניתא).<i> ונקרא חר\"ב נוקמת כו'</i> – זח\"ב סו, א ובאוה\"ח שם. שערי אורה לרי\"ג ש\"א. פרדס רמונים שכ\"ג פ\"ח ערך חרב.<i> חר\"ב נוקמת גו'</i> – בחקותי כו, כה.<i> והארץ מתקוממת לו</i> – איוב כ, כז.\n----- שולי הגליון -----\n<b>כב</b> ) <i>הבא בסוגריים ליכא במדל\"י. ובאוה\"א בלי סוגריים</i>.\n----- הערות וציונים -----\nלהעיר מחדושי אגדות למהר\"ל שם."]]],[400080487,"תכג\n\n<b>איזהו</b> שוטה המאבד מה שנותנים לו. פירוש, כי עיקר האדם הוא הצל\"ם דמות אדם שבו, וכמ\"ש בזוהר כשחיה דורסת את האדם בוודאי נדמה לה כבהמה, והלך ממנו דמות אדם מחמת העבירות שעשה. ואד\"ם בגימטריא מ\"ה. וזהו פירוש איזהו שוטה המאבד מ\"ה שנותנים לו, מ\"ה ר\"ל צלם אד\"ם גי' מ\"ה, שנותנים לו מהעולמות העליונים. ונקרא<sup data-n=\"1\">כג</sup> שוטה כי אבד זה מחמת שטות, כי אין אדם עובר עבירה אלא א\"כ נכנס בו רוח שטות.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' כב (כו). אוה\"א מח, א.</b>\n<i>איזהו שוטה כו'</i> – חגיגה ד, א.<i> וכמ\"ש בזוהר כשחיה כו'</i> – זח\"א עא, א. שבת קנא, ב.<i> ואד\"ם גי' מ\"ה</i> – תקו\"ז ז, ב. זח\"ג עדר, ב. ראה תקו\"ז תמ\"ז פג, ב.<i> אין אדם עובר כו'</i> – סוטה ג, א.\n----- שולי הגליון -----\n<b>כג</b> ) ונקרא כו' <i>במדל\"י בסוגריים</i>.\n----- הערות וציונים -----\nראה לקוטי שיחות חכ\"ה ע' 455 ובהערות שם.\n<i>עיקר האדם הוא הצל\"ם דמות אדם שבו</i> – עיין ריש סי' קלד ובהערות שם.\n<i>נדמה לו כבהמה כו'</i> – ראה חדושי אגדות למהר\"ל שבת קנא, ב. תניא פכ\"ד."]]],[400080488,"תכד\n\n<b>לא</b> הכל בקימה ולא הכל בהשתחויה, מלך בקימה ושרים בהשתחויה, [שנאמר מלכים יראו וקמו שרים וישתחוו]. הנה הגם שיש ע' שרים, אך בתורה לא מצינו רק ג', והם שר המשקין והאופים והטבחים, והם קנה וושט וורידין. קנה שר המשקין, וושט שר האופים, וורידין שר הטבחים, ובוודאי בהם כלולים כל השאר ע' שרים.\n<b>והנה</b> ידוע שדיבור נקרא מדת המלכות, והטעם לפי שעבדי המלך אינם צייתים רק לדיבור המלך, שאינם יכולים להשיג מחשבתו, והדיבור הוא ציית להמחשבה. ואיתא בזוהר [על א' זעירא דויקרא], כד מלכא בקסטירא [דיליה] מלכא רבא איקרי, וכד נחית לעבדוי מלכא זוטא איקרי. ורמז בזה כי ידוע שאותיות המחשבה הם גדולים לפי שהם מולכים על אותיות הדיבור.\n<b>והנה</b> המלך מצד עצמו אינו צריך לאותיות הדיבור, אך מצד המקבלים הוא צריך לצמצם את עצמו לקול, ומקול לדיבור. הגם שהכל הוא אחדות פשוט, והכל הוא המלך לבד, אך הכלים הם מחולקים. והכל הוא מפני המקבלים שאינם יכולים להשיג מחשבת המלך, ואח\"כ גם הקול אינם יכולים להשיג, עד שצימצם גם הקול להמביטים לדיבור. והנה האותיות שבמחשבה מלך עילאה אקרי מטעם הנזכר. וזהו כד איהו בקסטירא דיליה וכו', דהיינו במחשבה, וכד נחית, דהיינו אל הדיבור שיוכלו העבדים להשיגו, מלך זוטא איקרי [כנ\"ל]. והנה אם היה למלך עבד חכם שיכול להשיג מחשבת המלך בוודאי היה צריך לציית מחשבתו. וקל וחומר הוא, שאנו רואים שהדיבור של המלך נעשה מחשבה אל העבד שמחשב תמיד לקיים אותיות ציווי המלך, מכ\"ש מחשבתו.\n<b>והנה</b> [לכאורה] יש תימא על שמצינו תפלת הצדיקים דומה לעתר שמתהפכת על ידה מחשבת הש\"י, ע\"ד מי מושל בי [אפילו] [בי] צדיק. האיך יכול להיות הדיבור של הצדיק שיוכל לעלות כל כך עד שיעשה התהוות אחר, והלוא דיבור של הקב\"ה נעשה אצלנו בחינת חכמה המחיה אותנו, כמ\"ש בדבר ה' שמים נעשו, ואם כן איך יכול דיבור הצדיק לעלות כל כך להפוך אפילו מחשבת השי\"ת.\n<b>והתירוץ</b> על דבר זה, כי ידוע שכל התהוות שבעולם הכל נעשה ע\"י חכמה, כמ\"ש כולם בחכמה עשית. ועינינו רואים שהחכמה מקשרת יחד ומתווכחת שלום אפילו בין ב' דברים הפכיים כמו היסודות, שאילו לא היה החכמה שביניהם לא היו יכולים אש ומים לדור יחד, ואעפ\"כ אנו רואים שהם מורכבים יחד. והכל מפני שהחכמה ביניהם, וכל אחד רואה אי\"ן שבחכמה, ע\"כ אינו מתגבר על חבירו, כי הוא ראה שהאי\"ן הוא חיותו.\n<b>וכתיב</b> חכמות בחוץ תרונה, תרין חכמות עילאה ותתאה. וזהו חכמו\"ת, אפילו כשהם בחוץ, דהיינו חכמה תתאה, אעפי\"כ תרונה, כי חכמה איקרי. וחכמה [הוא] המהווה כל דבר, וכל ההשתנות שבעולם אי אפשר בלי חכמה, דהיינו האי\"ן. ועינינו רואות כי מביצה אינה יכולה להיות אפרוח עד שיפסיד הביצה מכל וכל, ויכנוס ברגע אחד בשער האי\"ן. אח\"כ יכול להיות ההשתנות מביצה לאפרוח. ועל שם כך נקרא חכמ\"ה כ\"ח מ\"ה, שהוא האי\"ן, והוא ההיולי של כל העולם, והוא הפושטת צורה ולובשת. ע\"כ בה נעשה ההשתנות.\n<b>וכתיב</b> ה' בחכמה יסד ארץ, והיינו שהשי\"ת מצמצם א\"ע ושורה בחכמה. וכתיב בראשית, ותרגום יונתן בחוכמתא, כי בה ברא עלמא וכל מה שברא. ועליה נאמר בברית מנוחה, יושבת בחיק המלך והיא סוכנת למלך וכו', והוא התענוג והשעשוע שלו בה כביכול עד שצימצם א\"ע כביכול [וד\"ל]. (<sup data-n=\"1\">כד</sup>ועוד שמעתי שהיא מדברים המקטינים א\"ע שהיא י', על כן הביאה למדת צמצום).\n<b>וכל</b> הנזכר נאמר על חכמה עילאה. ואח\"כ נמשך ממדריגה למדריגה עד סוף כל המדריגות, ובסופם שוב נתגלה בה חכמה, דהיינו י' תתאה. וזו החכמה מושגת ונראית בעוה\"ז, דהיינו צורכי של כל דבר מה שצריך לעולמות ותענוגו חיותו והווייתו של אותו דבר [נ\"א: וזהו חיותו והויתו של אותו דבר] כנזכר. והמבין יבין שכן הוא בפרטות כל עולם בפ\"ע, שתחילתו הוא חכמתו, ואח\"כ בסופה נתגלה גם כן חכמה, וזהו חכמה של עולם התחתון. וזהו השעשועים והתענוג של עולם [העליון] להיות שורה בתחתון עד סוף כל המדריגות. (<sup data-n=\"2\">כה</sup>וזהו למעלה רי\"ש, חכמה עילאה, ולמטה שיר חכמה תתאה).\n<b>וזהו</b> [נ\"א: וידוע] מ\"ש בראשית, בשביל ישראל שנקראו ראשית. דהיינו שעלה לפניו יתברך התענוג מה שיש לו מן הצדיקים העתידים להיות, ובשבילם נברא העולם. וזהו מ\"ש רז\"ל נמלך הקב\"ה בנשמותיהם של צדיקים וברא את העולם, ועצם [נ\"א: ר\"ל עצם] התענוג מה שיש לו מן הצדיקים מה שהם עושים מעשים טובים, ובזה ממשיכין תענוג ושפע וחיות בכל העולמות. וזהו עצם התענוג שלו כנזכר במקום אחר, שהתענוג הוא החיות של כל העולמות והויתן, כמ\"ש כולם בחכמה עשית וד\"ל.\n<b>נמצא</b> כי העולמות הם התענוג<sup data-n=\"3\">כו</sup>, ובמה שעושים תענוג שלו יתברך בזה מקיימין כל העולמות ע\"י מעשים טובים שלהם כי הכל הוא אחדות פשוט. וזהו ישראל מפרנסים וכו', שהם ממשיכין לו תענוג. נמצא כי הצדיק ממשיך ב' תענוגים, א' להשי\"ת, וזה מה שממשיכין לו תענוג הוא נקרא תענוג עליון דהיינו חכמה עילאה, ומה שממשיכין תענוג לעולם זהו חכמה תתאה. וז\"ש בין תרין צדיקים עלמא יתיב, דהיינו ב' ההמשכות [הנ\"ל], המשכה אחת לתענוג עליון כנזכר, והב' לתענוג הב' כנזכר, חכמה תתאה. נמצא מ\"ש בשביל ישראל, ומה שתרגום יונתן בחוכמתא, הכל [עולה בקנה] אחד. כי חכמה הוא התענוג, וישראל הם העושים התענוג, קודש ישראל ראשית.\n<b>ותרין</b> צדיקים הנזכרים הם תמונת ב' אתוון, צ' כפופה ופשוטה. הכפופה היא נוקבא שנכפפה לקבל מעלמא דדכורא, והיו\"ד [של הצ'] היינו חכמה. כי כשהצדיק רוצה להתפלל ולהמשיך שפע, מתחילה משתחוה, דהיינו שנכפף קדם עלמא עילאה כתמונת נ' כפופה. אך כל עצמו מתלבש ביראה, דהיינו חכמה, ראשית חכמה יראת ה', דהיינו שמעלה על לבו וזוכר לפני מי הוא עומד לפני מלך מלכי המלכים הקב\"ה, ונופל עליו יראה גדולה אימה ובושה. וזהו השראת השכינה, דהיינו יראה פנימיות חכמה, בגין דאיהו רב ושליט, ונופל עליו כ\"כ יראה עד שיהיה בטל ממציאות נגד המלך, ונכנס לשער אי\"ן שהוא חכמה יו\"ד. ובזה מקשר היו\"ד עם הנו\"ן [כפופה] ונעשה צדיק כפופה. אך עדיין הוא בחכמה תתאה [נ\"א: עדיין הוא בחינת יו\"ד תתאה], דהיינו יראה, ועי\"ז מוסיף תענוג להשי\"ת. וזהו עצם השעשועים שבשבילם נברא העולם, כמו האב שיש לו תענוג כשהבן מבקש ממנו דבר והוא נותן לו. וזהו בראשי\"ת, יר\"א בוש\"ת, והכל אחד, התרגום יונתן והמדרש הנזכר. והצדיק כיון שנכנס אל אי\"ן כנזכר, אזי מקשר את עצמו לחכמה עילאה בזה, כי כיון שהוא עצמו אי\"ן, והאי\"ן אינו מתאוה לשום דבר.\n<b>וז\"ש</b> ויקח מאבני המקום וגו'. כי ידוע שהאבנים הם האותיות. והנה כשהצדיק מתפלל באותיות ומקשר את עצמו עד חכמה עילאה כנזכר, דהיינו כשהוא כבר נכנס לשער אי\"ן, ומעלה על לבו שאלמלא כח השי\"ת שבו אז היה אפס מוחלט, אם כן הלא הוא [נ\"א: אם כן הכל] כח השי\"ת. והדיבור הוא עולם הדיבור של השי\"ת שבו נברא העולם, ועולם הדיבור נמשך מחכמה שהוא התענוג והשעשועים של השי\"ת מה שיש לו מן העולמות. וגם עתה הוא מדבר רק בשביל שעשוע השי\"ת, ובזה הוא מחזיר האותיות לשורשם, דהיינו חכמה, שממנו נמשכין. וזהו ויקח מאבני המקום, דהיינו האותיות, וישם מראשותיו, דהיינו לשורשם, רק בשביל תענוג המלך, דהיינו שהדיבור שלו יש לו עלייה. וזהו עצם התענוג של השי\"ת, כדמיון מי שלא ראה את בנו זמן רב ואחר זה רואה אותו יש לו תענוג גדול, כן יש לו יתברך תענוג מן האותיות של הדיבור וד\"ל.\n<b>ובזה</b> נתקשר הצדיק לחכמה עילאה כנזכר (ומלביש) [ומתלבש] בדיבור שלו, ומכוונה הנזכר ורצונות שלו בזה ממשיך שפע מרצון העליון לחכמה, וממנו ולמטה עד סוף כל המדריגות. וכשנמשך נקרא צדיק פשוטה, דהיינו נ' פשוטה שנמשכת כנודע, ויו\"ד שהוא חכמה שמתקשר בה. וכל הנזכר נקרא מל\"ך, ך' פשוטה הוא רצון העליון שנמשך (על) [אל] הלמ\"ד, שהיא ג' קוים, שלמעלה שביחידות נקרא ג\"ימל, היינו וא\"ו שהיא המשכה, ובסופה יו\"ד, שהוא נותן לדל\"ת, כמ\"ש רז\"ל ג\"ד שגומ\"ל דלי\"ם. אבל בעשיריות נקרא למ\"ד, דהיינו המשכה שבאה מלמעלה לתמונת נו\"ן וזהו [נ\"א: שזהו ג\"כ] תמונת למ\"ד, ואח\"כ מהלמ\"ד למ\"ם, מלכות, וזהו הצירוף מל\"ך. וזהו הדיבור שיש לו עליה עד למעלה בשביל השעשועים לעילא כנזכר, ועל ידי כך נמשך גם לתתא. וידוע כי הצדיק נקרא כ\"ל. וזהו לא הכ\"ל בקימה ולא הכ\"ל וכו', דהיינו תרין צדיקים [הנ\"ל] לא שניהם בשוה, כי אם מלך בקימה, דהיינו שיש לו עליה לעיל כנזכר, ושרים בהשתחויה, דהיינו המשכה לתתא. כי השתחויה הוא המשכה, ועל כן תקנו השתחויה לפני השי\"ת.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' צ-צא (ק). אוה\"א לד, א.</b>\n<i>לא הכל בקימה כו'</i> – תענית יד סע\"ב.<i> מלכים יראו גו'</i> – ישעיה מט, ז.<i> ג' והם שר כו'</i> – וישב מ, א-ב.<i> והם קנה וושט וורידין</i> – לקו\"ת להאריז\"ל פ' לך לך ד\"ה ויהי כבוא. שער הפסוקים פ' וישב ד\"ה ויוסף הורד מצרימה.<i> שדיבור נק' מדת המלכות</i> – זח\"א קמה סע\"א. זח\"ג רכח, א.<i> שעבדי המלך אינם צייתים כו'</i> – ראה ע\"ח שמ\"ז ספ\"ב.<i> ואיתא בזוהר כד מלכא כו'</i> – זח\"א רלט, א.<i> שאותיות המחשבה הם גדולים</i> – ראה זח\"ב קלב, א.<i> האותיות שבמחשבה מלך עלאה אקרי</i> – ראה זח\"ב סז רע\"ב.<i> תפלת הצדיקים דומה לעתר כו'</i> – סוכה יד, א.<i> מי מושל בי צדיק</i> – מו\"ק טז, ב.<i> בדבר ה' גו'</i> – תהלים לג, ו.<i> כולם בחכמה עשית</i> – תהלים קד, כד.<i> חכמות בחוץ תרונה</i> – משלי א, כ.<i> תרין חכמות כו'</i> – זח\"א קמא, ב.<i> חכמה דהיינו האי\"ן</i> – תקו\"ז תמ\"ב פא, ב. שם ת\"ע קכז סע\"א וקלג רע\"ב.<i> חכמ\"ה כ\"ח מ\"ה</i> – זח\"ג כח, א. שם לד, א.<i> ה' בחכמה גו'</i> – משלי ג, יט.<i> בראשית</i> – בראשית א, א.<i> ות\"י בחוכמתא</i> – שם. ראה זח\"א לא רע\"ב.<i> בברית מנוחה</i> – ס' ברית מנוחה שלהי הדרך הראשונה (ושם: היא שוכנת בחיק המלך וסוכנת למלך).<i> יושבת כו' והיא סוכנת למלך</i> – ע\"פ מ\"א א, ב' וד'.<i> רי\"ש חכמה עילאה</i> – ראה תקו\"ז תס\"ט קיא, ב. שם קטז, א. ראה פרדס רמונים שכ\"ז פכ\"ג.<i> שיר חכמה תתאה</i> – (מלכות) ראה זח\"ב קמד, א.<i> בראשית בשביל ישראל כו'</i> – אותיות דר\"ע ב. ויק\"ר לו, ד.<i> נמלך הקב\"ה כו'</i> – בר\"ר ח, ז. רות רבה ב, ג תיקזו\"ח קכא, ג.<i> כנזכר במקום אחר</i> – סי' א, סט, קפג, דש.<i> ישראל מפרנסים וכו'</i> – זח\"ג ז, ב.<i> בין תרין צדיקים כו'</i> – זח\"א קנג, ב.<i> קודש ישראל ראשית</i> – ירמיה ב, ג.<i> והיו\"ד היינו חכמה</i> – זח\"ב קכא, א. זח\"ג י, ב.<i> ראשית חכמה גו'</i> – תהלים קיא, י.<i> בגין דאיהו רב ושליט</i> – זח\"א יא, ב. ראה ר\"ח שער היראה פ\"א.<i> היו\"ד עם הנו\"ן ונעשה צדיק</i> – זח\"א ב, ב.<i> בראשי\"ת יר\"א בש\"ת</i> – זח\"ג רנז, א. תקו\"ז ה, ב. שם ת\"ז כד, א.<i> ויקח מאבני המקום וישם מראשותיו</i> – ויצא כח, יא.<i> שהאבנים הם האותיות</i> – ס\"י פ\"ד מי\"ב.<i> הלמ\"ד כו' וא\"ו . . יו\"ד . . לדל\"ת</i> – ראה פרדס רמונים שכ\"ז פט\"ו.<i> ג\"ד שגומ\"ל דלי\"ם</i> – שבת קד, א.<i> הצדיק נקרא כ\"ל</i> – זח\"א לא סע\"א. זח\"ג רנז, א.\n----- שולי הגליון -----\n<b>כד</b> ) <i>הסוגריים גם במדל\"י</i>.\n<b>כה</b> ) <i>הסוגריים גם במדל\"י</i>.\n<b>כו</b> ) <i>ע\"פ מש\"כ בקטע לפני זה, אולי צ\"ל</i> כי החיות של העולמות הוא התענוג.\n----- הערות וציונים -----\n<i>שדיבור נקרא מלכות והטעם כו'</i> – ראה סי' קעט-ב סד\"ה ונחזור אל הענין. וראה סי' שסא.\n<i>שאינם יכולים להשיג מחשבתו כו'</i> – ראה ריש סי' יג ד\"ה הנה. סי' קנג וסי' תלג.\n<i>אותיות המחשבה הם גדולים</i> – ראה סי' סא.\n<i>יש תימה על שמצינו כו'</i> – עיין סי' קסד וסי' קצא. (ועיין במפתח ענינים ערך השתנות; וערך צדיק ד\"ה יכול לעשות, מהפך, מושל.)\n<i>שכל התהוות שבעולם הכל נעשה ע\"י חכמה</i> – ראה סי' צה ד\"ה ויובן, וסי' רא.\n<i>שהחכמה מקשרת יחד ומתווכחת כו'</i> – ראה סי' ר ד\"ה ונחזור, ובהערות שם.\n<i>שהאי\"ן הוא חיותו</i> – להעיר מסי' סג ד\"ה בן פורת, וסי' פו סד\"ה והנה זהו.\n<i>חכמות בחוץ תרונה תרין כו'</i> – ראה ריש סי' קסה וסי' תלה.\n<i>וכל השתנות שבעולם א\"א בלי חכמה כו'</i> – עיין סי' קיח וסי' קנא-ב, ובהערות שם.\n<i>כי מביצה אינה יכולה להיות כו'</i> – עיין מדל\"י סי' מח (נד). שם סי' רלג (רמז). וראה משל הגרעין המובא לעיל סי' קמג ד\"ה והנה כל הנזכר. ומדל\"י סי' קי (קכב).\n<i>והוא ההיולי</i> – ראה סי' קמג ד\"ה כתיב, וסי' תלד.\n<i>ה' בחכמה כו' ושורה בחכמה</i> – ראה סי' סג ד\"ה והנה, וסי' תלד.\n<i>הפושטת צורה ולובשת</i> – ראה סי' תלד.\n<i>מדברים שמקטינים א\"ע שהיא י' על כן כו'</i> – ראה סי' רמח ד\"ה וזהו (ואילך) ושם רד\"ה ולפי, ובהערות שם.\n<i>וזהו למעלה רי\"ש ח\"ע ולמטה שי\"ר ח\"ת</i> – ראה סי' תלה ד\"ה והנה חכמה. וראה אוה\"א כז, א ובכתבי קודש יח, ג: שיר הוא יחוד והוא אותיות ריש, כי רי\"ש הוא משפיע לשי\"ן דרך היו\"ד שמורה על הצמצום.\n<i>וזהו מ\"ש בראשית בשביל כו'</i> – ראה סי' א ובהערות שם.\n<i>כנזכר במקום אחר</i> – ראה הנסמן במ\"מ, ועייג\"כ מדל\"י סי' קלד (קמב).\n<i>צ' כפופה ופשוטה</i> – ראה סי' רכג, וסי' רמח ד\"ה והנה מדת.\n<i>והאי\"ן אינו מתאוה לשום דבר</i> – ראה סי' רמח ד\"ה והנה בצדיקים. וראה סי' שע וסי' שפז-ג.\n<i>מחזיר האותיות לשורשם כו</i>' – ראה סי' קה ד\"ה בפסוק, וסי' רעז-ב. ועיין כש\"ט סי' צו-ב.\n<i>כדמיון מי כו'</i> – להעיר מסי' תד.\n<i>וכל הנזכר נקרא מל\"ך כו'</i> – הובא באוה\"ת – נ\"ך לאדמו\"ר הצ\"צ ע' רנו בתוס' הגהות."]]],[400080489,"תכה\n\n<b>בגמרא</b> פעם אחת חל י\"ד להיות בשבת ושכחו אם פסח דוחה שבת וכו'. פי' [דהנה ידוע] כי יש כ\"ח עתים, י\"ד דקדושה וי\"ד דקליפה, [והם בכלל כ\"ח עתים המבוארים בקהלת]. נמצא כי ביום שבת שהוא יום קדושה, צריך שמחה גדולה. ובמה משמחו, במה שמחשב בעולמות עליונים<sup data-n=\"1\">כז</sup> בכל המדות בעולם התענוג, שהם י\"ד עתים דקדושה. ולפעמים (אז) [אין האדם יכול לשמוח בשבת, ו]אינו יכול לדבק עצמו בי\"ד עתים דקדושה (שמחזיק) [והוא מחזק] את עצמו בכל כחו ואינו יכול, נמצא שאין לו שמחה. ואיתא בשלחן ערוך, אדם שיש לו תענוג מסיפורים מותר לו לספרם בשבת מפני שהם שמחה ותענוג לו. (אלא) [אע\"פ] שהם מצד הקליפה, והם י\"ד עתים דקליפה, עכ\"ז מותר [לספר בהם כדי שלא יהיה עצב בשבת].\n<b>וזו</b> שאלה נשאלה בגמרא, [פעם אחת] חל, [פי' לשון חלה וחולין], י\"ד, פירוש י\"ד עתים הרעים, להיות בשבת, פירוש אדם אחד היה צריך לשמוח להתענג בי\"ד עתים האלו, שלא היה יכול לשמוח את עצמו בי\"ד דקדושה, ושכחו [ולא ידעו אם פסח דוחה שבת, פי פ\"ה ס\"ח, היינו] אם מותר לדבר בי\"ד אלו [נ\"א: אם מותר לדבר ולספר בספור מעשיות בשבת אע\"פ שהוא דחיות שבת]. והיה שם הלל הבב\"לי, פי' שהיה בלול מב' מדות, ואמר להם פסח דוחה שבת, ר\"ל פ\"ה ס\"ח [נ\"א: ודרש להם במועדו, לשון עָדַיִם ותענוג, פי' שמותר לשמוח בתענוגו שיש לו כפי השעה כנ\"ל]<sup data-n=\"2\">כח</sup>.\n<b>ומפני</b> מה התירו באמת לספר סיפורים בשבת. ואפשר לומר משל נפלא על זה. משל למלך שהיו לו מדינות הרבה ועבדים לאין מספר, וציוה המלך לעשות יום מוגבל משתה ושמחה לכל שריו ועבדיו. ולכל מי שירצה לבוא אל המשתה להתענג בתענוגי ומעדני המלך, יותן לכל [איש ואיש] רצונו ושאלתו, כל אשר תשאלה ויתאוה נפשו, כדי שלא יחסר לשום אדם שום תענוג ועידון בעולם. ככל אשר הוא חפץ ושואל, תיכף ינתן לו כאוות נפשו. והנה היו [השואלים] הרבה. מה ששאל זה לא שאל זה. איזה מהם ביקשו שיתנו לו כלים נאים וחשובים שהמלך משתמש בהם. ואיזה מהם ביקש שיתנו לו כל מעדני מלך מכל מיני מאכל או כיוצא. ואחד הוסיף לשאול שיתנו לו פרס מגנזי המלך, זהב ואדרכמונים. ואיזה מהם ביקש שיתנו לו שילטנות ושררות על קצת ערי המלך. והכל ניתן לכל אחד ואחד חפצו ובקשתו.\n<b>והיה</b> שם איש סכל וחסר לב, והוא היה איש צרוע מוטל באשפה מחמת (צערתו) [צרעתו]. ובהגיע אליו השאלה לשאול ולבקש תאוותו וחפצו וצרכיו מבית המלך, ביקש שיצוה המלך שיותן לו ב' משפלות של זבל לח וקר, בכדי שיתכסה מהם ויתקרר מצרעתו. וגערו בו עבדי המלך ואמרו לו, שוטה וחסר לב, מה זאת אשר שאלת ובחרת מכל תענוגים. והלוא אם היית שואל ביום הזה חפצים טובים או מיני תענוגים שבעולם, וכל [תענוגים] מחמדי לב מהמלך, היו נותנים לך, כי כן דת המלך ונימוסו להיות עושים רצון [כל] איש ואיש. ואם תאמר מחמת כאב צרעתך שאלת דבר זה, שוטה שבעולם, היה לך לבקש מאת המלך שיצוה להרופאים לרפאות אותך מצרעתך. כלום חסרים מבית המלך רופאים מומחים וכל מיני סממני רפואות עד אין קץ. והנה הגיע הדבר הזה בפני המלך שכך ביקש האיש הסכל. והמלך, שחכמתו גדולה עד מאוד, אמר לעבדיו, מאחר שאיש זה הוא כסיל, בשבילו ישתנה נימוסי המלך ודתו, זה אי אפשר. רק ינתן לו [בקשתו] כמו אשר בחר [לו]. כי הסכל הלזה בחר בדבר מאוס, אם כן בוודאי זה עיקר תענוגו ועידונו, ע\"כ לא יותן לו יותר משאלתו ובקשתו. והנמשל מובן.",[["","","----- מקורות ומראה מקומות -----\n<i>בגמרא . . פ\"ה ס\"ח: </i><b>אוה\"א מד, א. </b><i>ומפני מה התירו כו': </i><b>לקו\"י ו, ד (סי' קכא).</b>\n<i>בגמרא פעם אחת חל כו'</i> – פסחים סו, א.<i> כי יש כ\"ח עתים כו'</i> – קהלת ג, ב-ח. תקו\"ז תס\"ט קא, ב.<i> ביום שבת כו' צריך שמחה גדולה</i> – ראה ירושלמי מגילה פ\"א ריש ה\"ד. ספרי בהעלותך פי' עז.<i> ואיתא בשו\"ע כו'</i> – או\"ח סי' שז סעיף א.<i> הבב\"לי . . בלול</i> – ראה נח, יא, ט.<i> פ\"ה ס\"ח</i> – ע\"פ פע\"ח שער חג המצות פ\"ז.\n----- שולי הגליון -----\n<b>כז</b> ) <i>נ\"א באוה\"א:</i> נמצא כי ביום השבת, שהוא עת דקדושה, צריך האדם לשמוח, שבזה משמח העולמות העליונים בכל <i>(כבפנים)</i>.\n<b>כח</b> ) <i>המילואים ונ\"א ע\"פ הגירסא באוה\"א, ושם מסתיים הדרוש כאן. ובלקו\"י גירסא אחרת:</i> פסח דוחה שבת. נראה לפרש בדרך הלצה. הנה מבואר בשולחן ערוך, אותם המתענגים בדיבורים וסיפורים מותר לדבר ולספר סיפורים בשבת. וזהו פסח דוחה שבת, פי' פ\"ה ס\"ח, וזהו שבחו. ולא ידעו מאיזה טעם ידחה פסח, ר\"ל פ\"ה ס\"ח, את השבת, ומפני מה התירו לספר סיפורים בשבת. ואפשר לומר הלל וכו'. משל נפלא על זה <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>ביום שבת כו' צריך שמחה גדולה</i> – עיין מה שהאריך בזה כ\"ק אדמו\"ר זי\"ע בלקוטי שיחות חל\"ג ע' 62 ואילך. ועיין שפת אמת לסוכות (תר\"ס) ד\"ה הד' מינים ומש\"כ שם בשם זקנו בעל חידושי הרי\"מ.\n<i>ולספר בספור מעשיות בשבת אע\"פ שהוא דחיות השבת</i> – ראה שבת קיג, ב. שו\"ע או\"ח ריש סי' שז.\n<i>משל נפלא על זה כו'</i> – המשל הובא בקיצור נמרץ בס' צפנת פענח פ' בא (לו, ג) בשם הבעש\"ט."]]],[400080490,"תכו\n\n<b>כל</b> הלן ז' לילות בלא חלום נקרא ר\"ע, שנאמר שבע ילין בל יפקד וגו'. נראה לפרש על פי רמז. לילות נקרא כאשר האדם ח\"ו מתרשל ומתעצל בעבודת השי\"ת, כמו כסיל בחוש\"ך הולך. ושבע הם הז' מדות שהאדם צריך להתגבר בהם, כמו האהבה והיראה וכו', בעבודות השי\"ת. חלו\"ם הוא לשון התגברות ובריאות, כמו ותחלימני והחייני. וזהו שבע ילין, כלומר שהוא לן בהמדות כמו באישון לילה חושך ואפילה, ואינו מתגבר בהם, וזהו בלא חלום. בל יפקד נקרא רע, וב\"ל יפקד לשון חיבור, שאינו מחבר את עצמו למדות טובות, רק מתרשל, נקרא רע.",[["","","----- מקורות ומראה מקומות -----\n<i>כל הלן ז' לילות כו'</i> – ברכות יד, א.<i> שבע ילין גו'</i> – משלי יט, כג.<i> כסיל בחוש\"ך הולך</i> – קהלת ב, יד.<i> ותחלימני והחייני</i> – ישעיה לח, טז.<i> יפקד לשון חיבור</i> – ע\"פ יבמות סב, ב.\n----- הערות וציונים -----\n<i>לילות נקרא כאשר כו'</i> – ראה סוף סי' פד-ב. ריש סי' רח. וסי' רעט.\n<i>חלו\"ם הוא לשון התגברות כו'</i> – להעיר מסי' רו ד\"ה ואם."]]],[400080491,"תכז\n\n<b>אל</b> יפטר אדם מחבירו אלא מתוך דבר הלכה, שמתוך כך וכו'. הנה האדם כאשר הוא מורגל בתענוגים בתמידיות אינו מרגיש כל כך התענוג, כי הוא תמיד באותו התענוג. אבל כשפורש את עצמו מן התענוג, ואח\"כ בא לידו איזה תענוג, הוא מתענג יותר ממה שהיה לו מקודם בתמידות, כי כל מה שהוא מרוחק מן התענוג הוא יותר מקורב אצלו.\n<b>למשל</b> אדם שהוא רואה אבן טוב והוא למעלה גבוה מאוד, ורוצה ליקח אותה ואינו יכול כי אם שיעלה במדריגות. והנה יש מדריגה שקורין אותה (שווינדל טרעפּ). הנה כאשר הוא במדריגה תחתונה הוא רואה אותה, ובאם עולה יותר כמדומה לו שנתרחק ממנה, כיון שאינו רואה. והמדריגה הנזכרת אינה הולכת בשוה, רק מדרום למערב וממערב לצפון, עד כמה מדריגות עולה עד שבא אצל האבן טוב. ואם היה נחסר אפילו מדריגה אחת לא היה יכול לעלות, כי אי אפשר לו לקפוץ, כי אם לעלות מעט מעט ממדריגה למדריגה עד שיעלה לשם. אבל מי שהוא כסיל מיד כשאינו רואה אותה פורש ממנה. והנמשל, אדם צדיק להיותו תמיד בדביקות, ולפעמים בטל ממנו הדביקות, אל יפחד שנתרחק ממנו. כי אפשר מחמת זה יבוא למדריגה גבוה ומעולה ממנה, כי הירידה הוא צורך העלייה, והתרחקות היא צורך התקרבות, ומכח השכחה יבוא לידי זכרון, כמשל הנזכר.\n<b>וזהו</b> אל יפטר אדם מחבירו, כלומר מחבירו ודביקותו, ואל יתיאש לומר שנתרחק מהדביקות. אלא יאחז צדיק דרכו ויוסיף אומץ לעלות במדריגה, כי אין לו לעלות למעלה אם לא ע\"י הנהגת הליכה מעולם לעולם, כי דב\"ר לשון הנהגה. אע\"פ שדומה לו שכבר נתרחק מהאבן טוב ואינו רואהו ושכחו, כי אדרבא אפשר שמתוך כך, רצה לומר מתוך השכחה וההתרחקות, יעלה למדריגה יותר עליונה, ומתוך השכחה יבוא לזכרון כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<i>אל יפטר אדם מחבירו כו'</i> – ברכות לא, א.<i> שווינדל טרעפּ</i> – ראה פרש\"י מ\"א ו, ח.<i> יאחז צדיק דרכו ויוסיף אומץ</i> – ע\"פ איוב יז, ט.<i> דב\"ר לשון הנהגה</i> – ע\"פ מ\"א ה, כג. ישעיה ה, יז. תהלים מז, ד. וראה זח\"ב כה סע\"ב.\n----- הערות וציונים -----\n<i>כאשר הוא מורגל בתענוגים בתמידיות כו'</i> – ראה סי' לה ובהערות שם.\n<i>יש מדריגה שקורין אותה שווינדל טרעפ כו'</i> – ראה סי' קנט ד\"ה וז\"ש ענן ובהערות שם.\n<i>והתרחקות היא צורך התקרבות</i> – ראה סי' קפח ובהערות שם."]]],[400080492,"תכח\n\n<b>אין</b> בן דוד בא אלא בדור שכולו זכאי או כולו חייב. פירוש, כי ידוע כי איהו סובב כל עלמין. (וכשיהיו) [נמצא כאשר] כולם חייבים ויבואו למדריגה היותר פחותה ותחתונה, שם קרוב יותר אל השי\"ת ויעמיד עליהם מלך כהמן [<sup data-n=\"1\">כט</sup>וישראל עושין תשובה ומחזירן למוטב].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ב, ג (סי' מז). אוה\"א נד, ב.</b>\n<i>אין בן דוד כו'</i> – סנהדרין צח, א.<i> איהו סובב כל עלמין</i> – זח\"ג רכה, א.<i> ויעמיד עליהם מלך כו'</i> – סנהדרין צז, ב.\n----- שולי הגליון -----\n<b>כט</b> ) <i>הבא בסוגריים אינו במקבילות, והוא סיום המאמר בגמרא שהוספתי לסיים בטוב</i>.\n----- הערות וציונים -----\n<i>למדריגה היותר פחותה ותחתונה שם קרוב יותר כו'</i> – י\"ל ע\"ד מאמר ס\"י נעוץ סופן בתחילתן ותחילתן בסופן. ולהעיר מס' נצח ישראל למהר\"ל פל\"ט."]]],[400080493,"תכט\n\n<b>אשרי</b> המלך שמקלסין אותו בביתו [כך]. פי', צריך לשום חיות באותיות עד שיופשט מהגשמיות, וישכח עצמו מכל וכל, רק כל מחשבותיו יהיו להשם ית', ולא יזכור כלל כמה הוא מתפלל בכוונה. וכולם ברגע אחד, כי הוא למעלה מזמניות, והוא רק כמו ברק בעלמא. וזהו בביתו כך, ר\"ל בביתו של הקב\"ה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א נד, ב. כתבי קודש ו, ג.</b>\n<i>אשרי המלך כו'</i> – ברכות ג, א.<i> עד שיופשט מהגשמיות</i> – ראה טושו\"ע או\"ח ריש סי' צח.\n----- הערות וציונים -----\nכבר הובא לעיל סוף סי' רפא."]]],[400080494,"תל\n\n<b>ואוי</b> לבנים שגלו מעל שולחן אביהם. כי יכולים לעבוד להקב\"ה בכל דבר. אפילו באכילה שהוא אוכל ויש לו תענוג, יביא התענוג להשי\"ת, למי שהוא תענוג [נ\"א: שהוא תענוג לכל התענוגים]. וגם בשינה נסתלקו המוחין ובאים למעלה, ואחר כך מתגבר מזה. ואפילו כשעושה צרכיו יהיה לשם שמים להפריד רע מטוב. והכל נקרא אכילה, כמו<sup data-n=\"1\">ל</sup> אכלה ומחתה פיה. וזהו אוי לבנים שגלו מעל שולחן אביהם<sup data-n=\"2\">לא</sup> וגם כששומע דברים בטלים, יבחין מאיזה מדה הם, אם מאהבה או מיראה וכן כיוצא בזה. אמנם לא יתן אל לבו שהוא עובד הרבה. וזהו ממכניסי שב\"ת, [ר\"ל] שמו של הקב\"ה, בטבריא, אפילו בדברים בטלים ושפלים הנקראים טיבורא, עושים לשם שמים. וממוציאי שבת, אפילו בדברים גבוהים כמו ציפור\"י, אין מחזיקין את עצמן שעובדים את השם יתברך<sup data-n=\"3\">לב</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א נד, ב. כתבי קודש ו, ג.</b>\n<i>ואוי לבנים שגלו כו'</i> – ברכות ג, א.<i> יכולים לעבוד כו'</i> – ראה רמב\"ם הלכות דעות פ\"ג ופ\"ד. שמונה פרקים פ\"ה. טושו\"ע או\"ח סי' רלא.<i> אפילו באכילה כו'</i> – רמב\"ם שם. ר\"ח שער הקדושה פט\"ו. של\"ה, שער האותיות אות ק'.<i> וגם בשינה נסתלקו כו'</i> – פע\"ח שער תיקון חצות פ\"א.<i> ואפילו כשעושה צרכיו כו'</i> – ראה ר\"ח שער הקדושה שלהי פט\"ו ד\"ה עוד ראוי לכוון באכילה. של\"ה מס' חולין, בסוף פ' תוכחת מוסר ד\"ה והיודע סוד מנעל.<i> אכלה ומחתה פיה</i> – משלי ל, כ.<i> ממכניסי שב\"ת בטבריא כו'</i> – שבת קיח, ב.<i> שב\"ת שמו של הקב\"ה</i> – זח\"ב פח, ב.<i> בטבריא . . טיבורא</i> – ראה מגילה ו, א.<i> בדברים גבוהים כמו ציפור\"י</i> – ראה מגילה ו, א.\n----- שולי הגליון -----\n<b>ל</b> ) <i>בכתבי קודש:</i> מה שחסר ממנו וממלא חסרונו נקרא אכילה כמו <i>(כבפנים)</i>.\n<b>לא</b> ) <i>בכתבי קודש מוסיף כאן:</i> דהיינו שגלו את אביהם מעל השולחן.\n<b>לב</b> ) <i>בכתבי קודש:</i> וממוציאי שבת, יש שמוציאין את השבת, שאין מחזיקין א\"ע שהם עובדים השי\"ת, בציפור\"י, אפילו בדברים גדולים אפילו כשהם במדריגה גבוהה.\n----- הערות וציונים -----\nראה סי' תיא. ועיין בהערות לסי' תנו.\n<i>וגם בשינה כו' ואפילו כשעושה צרכיו כו'</i> – ראה צוה\"ר סי' כב."]]],[400080495,"תלא\n\n<b>אם</b> אני כאן הכל כאן. קשה, וכי זה הוא ענוותנותו של הלל. אך הענין הוא, למשל פרוטה, אף על פי שדינר חשוב ממנה, אף על פי כן יש לה ערך כנגדה. ודינר יש לה ערך כנגד דינר זהב, אבל פרוטה אין לה ערך כנגד דינר זהב, אך כולם אין להם ערך כנגד מרגניתא דלית בה טימא. וידוע כי בשמחת בית השואבה שואבין את רוח הקודש, ועל שם כך נקרא שמחת בית השואב\"ה. וזהו אם אני השפל בא כאן לשאוב רוח הקודש, הכל ראויים להיות כאן, כי כולם חשובין ממני. אם אין אני כאן, שאיני ראוי לזה, מי כאן, כי כולם כאין נגדו יתברך, כמשל הנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מא, ב.</b>\n<i>אם אני כאן כו'</i> – סוכה נג, א.<i> אין להם ערך כנגד מרגניתא כו'</i> – ע\"פ מדרש תהלים יט, ב.<i> בשמחת בית השואבה שואבין כו'</i> – ירושלמי סוכה פ\"ה ה\"א.\n----- הערות וציונים -----\nעד\"ז בנועם אלימלך, שלהי לקוטי שושנים בד\"ה כי נר מצוה (ושם בסתמא, בלי הזכרת שם הרה\"מ)."]]],[400080496,"תלב\n\n<b>אם</b> אין אני לי מי לי. [כי צריך להיות בתפלה מופשט מגשמיות. וזהו] ר\"ל אם אין אני לי, רצה לומר שהוא מופשט מהגשמיות, מי לי, אין מחשבה זרה באה לי. ואם אני לעצמי מה אני, [דהיינו כשאני יודע ממני], אזי יש מחשבות זרות רבים.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מא, ב. צוה\"ר סי' צז.</b>\n<i>אם אין אני לי כו'</i> – אבות פ\"א מי\"ד.\n----- הערות וציונים -----\nלעיל סי' תטו באורך."]]],[400080497,"תלג\n\n<b>היתר</b> נדרים פורחין באויר ואין להם על מה שיסמוכו, רבי אליעזר אומר יש להם על מה שיסמוכו שנאמר כי יפליא ב' פעמים אחד לאיסור ואחד להיתר. קב\"ה סתים וגליא, ואורייתא וקב\"ה כולא חד, וגם היא סתים וגליא. הנסתרות לה' וגו' והנגלות לנו וגו', ופירש בזוהר והנגלות [פי'] קול ודיבור, נגלות לכל. וקשה למה לא נאמר בהנסתרות י\"ה כמו בוה\"נגלות ו\"ה. אך באמת מחשבה, שהיא ה' עילאה, מושגת היא לאדם עצמו ולאחרים אינה מושגת, אבל קדמות השכל אינה מושג [גם] לאדם. ע\"כ לא כתיב גבי נסתרות רק ה', שהוא לה' אלקינו. ובאמת נקודת פת\"ח שתחת הה' של ה\"נסתרות היא נקודת החכמה. כי קמ\"ץ מורה לשון סתימה, ע\"ד וקמץ הכהן. קמ\"ץ [הוא] מדריגה ידוע, הכהן הוא הכהן הגדול מאחיו, והוא חילוף הבכור. שהיתה עבודה בבכורות, על דרך קדש לי כל בכור, שמרמז לחכמה, ראשית חכמה, ראשית כל בכורי. וחכמה אינה מגולה רק מהנקודה ולמטה, מפתח\"א דכליל שית, הוא פת\"ח, כי הוא ו'. ונדר הוא בלב, כי בלא כוונה אין הנדר חל, כי [צריך] האדם בשבועה. ונד\"ר הוא נ' ד\"ר, כי נ' מתפשט בדיורין, הם אותיות. ובמקום אחר הצירוף הוא נר\"ד, כי שיבולת הוא שיבולת הזקן זה שקנה חכמה. ועל כן החכם מתיר הנדר, משום דאישה יקימנו ואישה יפירנו. וזהו היתר נדרים פורחין באויר, דהיינו שאין להם התגלות בתורה. ורבי אליעזר אומר יש להם התגלות בתורה, (ואמר) [שנאמר] כי יפליא ב' פעמים, על דרך ואא\"לפך חכמה. פל\"א הראשון הוא נקודת קמ\"ץ והוא לאסור, ופל\"א הב' הוא נקודת פת\"ח והיא היתר, ומזה ראיה שהחכם מתיר את הנדר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קכט (קלח). אוה\"א נה, ב.</b>\n<i>היתר נדרים כו'</i> – חגיגה י, א.<i> כי יפליא שתי פעמים</i> – בחקותי כז, ב. נשא ו, ב.<i> קב\"ה סתים וגליא</i> – זח\"ג עג, א.<i> ואורייתא וקב\"ה כולא חד</i> – זח\"א כד, א. זח\"ב ס סע\"א. שם צ, ב.<i> וגם היא סתים וגליא</i> – זח\"ג עג, א.<i> הנסתרות לה' גו' והנגלות גו'</i> – נצבים כט, כח.<i> ופירש בזוהר והנגלות כו'</i> – זח\"ג קכג, ב. תקו\"ז ת\"ע קכט, א.<i> מחשבה שהיא ה' עילאה</i> – (בינה) זח\"ג רכט סע\"ב.<i> פת\"ח . . נקודת החכמה</i> – תקו\"ז ת\"ע קכט, ב.<i> קמץ כו' ע\"ד וקמץ הכהן</i> – תקו\"ז ת\"ה יט, ב.<i> וקמץ הכהן</i> – ויקרא ה, יב.<i> קמ\"ץ מדריגה ידוע</i> – (כתר) תקו\"ז ת\"ע קכט רע\"ב. שם ז, ב.<i> הכהן הגדול מאחיו</i> – ע\"פ אמר כא, י.<i> חילוף הבכור שהיתה כו'</i> – במ\"ר ד, ח. שם ו, ב.<i> קדש לי גו'</i> – בא יג, ב.<i> שמרמז לחכמה</i> – זח\"ב מג, רע\"ב. זח\"א יג, ב.<i> ראשית חכמה</i> – תהלים קיא, י.<i> ראשית כל בכורי</i> – יחזקאל מד, ל.<i> מפתח\"א דכליל שית</i> – ח\"ב קעז, ב. ראה זח\"א ג, ב.<i> פת\"ח כי הוא ו'</i> – תקו\"ז ת\"ה יט, ב. שם טו, ב.<i> האדם בשבועה</i> – ויקרא ה, ד. שבועות כו, א ופרש\"י שם.<i> ונד\"ר הוא נ' ד\"ר</i> – של\"ה עשרה מאמרות, בית ישראל. שם תושב\"כ פ' מטות.<i> שיבולת הזקן</i> – ע\"פ מכות כ, ב.<i> הזקן זה שקנה חכמה</i> – קידושין לב, ב.<i> החכם מתיר הנדר</i> – נדרים עז, ב.<i> דאישה יקימנו גו'</i> – מטות ל, יד.<i> ואא\"לפך חכמה</i> – איוב לג, לג (ב' אלפין).<i> פל\"א</i> – (ע\"פ דאל\"ף איהו פל\"א) תקו\"ז ת\"ע קלה, ב. זח\"ג קצג, ב.\n----- הערות וציונים -----\n<i>מחשבה . . מושגת היא לאדם עצמו כו'</i> – ראה ריש סי' יג ובהערות שם."]]],[400080498,"תלד\n\n<b>בית</b> שמאי אומרים שברא מאור האש, ובית הלל אומרים בורא מאורי האש דכמה נהורין וכו'. כל דבר יכול לידע מאיזה שורש הוא על ידי החוש שהוא מרגיש אותו. על דרך משל האור מרגיש אותו ע\"י חוש הראות, והראי\"ה אותיות ירא\"ה, ראשית חכמה יראת ה'. חכמים נקראים עיני העדה, והחכמה נקרא חומר הראשון, לובש צורה ומפשיט, דהיינו ע\"ד שבע יפול צדיק וקם. כשיפול לצדיק אחת מז' מחשבות מקדמות השכל, הוא מדבק את עצמו, ויפשוט אותה מחשבה. וזהו ה' צדיק יבחן. [כי ביד ישראל יש כח להביא הכל לחכמה אשר הוא שורש ישראל, על דרך] אשה מזרעת תחילה יולדת זכר, הטעם בזהר שהזכרות שבסוף גובר. וישראל נקראים בנים, ע\"ד קודש ישראל לה' ראשית, קדש לי כל בכור, ישראל יש להם עלייה במחשבה. ואומות העולם נקראים בנו\"ת, על דרך בנו\"ת ירושלים, והבנות יזונו, שאין להם עיקר ירושה רק מזון. וזהו אור זרוע לצדיק, שהוא אינו יכול לעשות [נ\"א: שהוא אינו עושה] (פעולה הבחורה) [פעולת הברירה] כי אם ע\"י חכמה, ואין לך דבר שאין בו חכמה, בחכמה אתברירו. [כי] ה' בחכמה יסד ארץ, פי' הקב\"ה בחכמה, ועי\"כ שורה בארציות. ובחכמה עצמה אין בה גוון, רק כשהיא מלובשת בכלים אז נראה הגוונין על הכלים. על כן דעת בית שמאי דחדא נהורא [הוא], ובית הלל סברי כיון שהוא בכלי ובו יש (כבר) [כמה] גוונין, והבן זה מאוד.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קל (קלט). אוה\"א נה, ב.</b>\n<i>בית שמאי אומרים שברא כו'</i> – ברכות נא, ב.<i> ראשית חכמה גו'</i> – תהלים קיא, י.<i> חכמים נק' עיני העדה</i> – שהש\"ר א, טו.<i> שבע יפול צדיק וקם</i> – משלי כד, טז.<i> ה' צדיק יבחן</i> – תהלים יא, ה.<i> אשה מזרעת כו'</i> – ברכות ס, א.<i> בזוהר שהזכרות שבסוף כו'</i> – תקו\"ז תנ\"ו פט, ב.<i> קודש ישראל גו'</i> – ירמיה ב, ג.<i> קדש לי גו'</i> – בא יג, ב.<i> ישראל יש להם עליה במחשבה</i> – בר\"ר א, ד. זח\"א כד, א.<i> בנו\"ת ירושלים</i> – שה\"ש ב, ז.<i> והבנות יזונו כו'</i> – ב\"ב קלט, ב.<i> אור זרוע לצדיק</i> – תהלים צז, יא.<i> בחכמה אתברירו</i> – זח\"ב רנד סע\"ב. ע\"ח שי\"ח פ\"ה. שם שי\"ט פט ושל\"ט פ\"א. שעה\"מ פ' עקב.<i> ה' בחכמה גו'</i> – משלי ג, יט.<i> ובחכמה עצמה אין בה גוון</i> – ראה תקו\"ז י, א. פרדס רמונים ש\"י פ\"ה.\n----- הערות וציונים -----\n<i>והחכמה נקרא חומר הראשון לובש כו'</i> – ראה סי' תכד ד\"ה וכתיב חכמות, ובהערות שם.\n<i>וזהו ה' צדיק יבחן</i> – ראה סי' קעה.\n<i>לחכמה אשר הוא שורש ישראל</i> – ישראל נקרא ראשית (כדלקמן קודש ישראל לה' ראשית) שהוא חכמה (זח\"א ג, ב, שם לא רע\"ב, ועוד).\n<i>קדש לי כל בכור</i> – בכור הוא חכמה כדלעיל סי' נג וסי' תלג.\n<i>בחכמה אתברירו</i> – ראה סוף סי' סג ובהערות שם.\n<i>הקב\"ה בחכמה</i> – ראה סי' תכד ד\"ה וכתיב ה' בחכמה, ובהערות שם.\n<i>ועי\"כ שורה בארציות</i> – ראה סי' רלט וסי' שמב.\n<i>כשהיא מלובשת בכלים אז נראה הגוונים כו'</i> – ראה חובה\"ל שער הבחינה פ\"א. פרדס רמונים ש\"ד פ\"ד."]]],[400080499,"תלה\n\n<b>כשעלה</b> משה למרום שמע שהמלאכים מקלסין ברוך שם כבוד מלכותו לעולם ועד והורידו לישראל. ואמרו רז\"ל משל לבת מלך [שהריחה ציקי קדרה] וכו' התחילו (וכו') [עבדיה] הביאו לה בחשאי. הנה יש ב' מיני מים, עליונים ותחתונים. וכן איתא [נ\"א: וז\"ש] אמר רבי עקיבא וכו' אל תאמרו מים מים וכו', ומים התחתונים בוכים וכו'. הנה<sup data-n=\"1\">לג</sup> יש ב' מיני חיבורים עובדות ומחשבות. א' מה שנוגע לעבודת הבורא יתברך וקיום מצוותיו ולימודי תורתו. והב' בדברים בעלמא, [כמו ש]אמרו רז\"ל על חנוך בן ירד תופר מנעלים הוי ועל כל תפירה ותפירה היה מייחד קב\"ה ושכינתיה. וכתיב חכמות בחוץ תרונה. חכמות, ב' [חכמות], חכמה עילאה ותתאה. ואיתא בזוהר וע\"ד הוא אח\"ד בחילופי אתוון. פי' על דרך מ\"ש התוספות במסכת סוכה על אנ\"י וה\"ו כמו אני והו\"א. כי הוא\"ו במקום אל\"ף, כי וא\"ו בגימטריא י\"ג כמו אח\"ד וכו', וז\"ש בספר יצירה אם רץ לבך – מדביקות הבורא – שוב לאחד, פי' לאח\"ד הנזכר, לאלופו של עולם. והנה ח' הוא ו' וז' ותג המחברם. וזה נרמז בוע\"ד: ו' במקום א' כנזכר ע' הוא ג\"כ ו' ונ' כפופה המקבל במקום ז' הנזכר, (והכל) [ולכן הוא ב]גימטריא שבעים, פירוש נגד ז' ימי הבנין כל אחד כלול מי' הנרמזים בח' כנודע. ונודע כי איהו ממלא כל עלמין, וזה נקרא כח הפועל בנפעל, וכל מה שיורד כח הפועל יותר למטה בעולמות התחתונים הוא יותר מצומצם. ואף על פי כן כל מה שיש בים יש ביבשה, אלא שהוא יותר בצמצום. ולכן גם במילת וע\"ד נרמז אחדותו ית', אלא שהוא בהעלם, שהוא כח הפועל [בנפעל] הנזכר.\n<b>(</b><sup data-n=\"2\">לד</sup><b>(והוא)</b> [והנה] בחוש נראה שגם במדריגה היותר שפילה יש בה כל המדריגות. כי הנה איתא בגמרא דא\"ל דלא אכלית בשרא דתורא, נמצא שיש בו אחר אכילה הוספת השכל. וכשבן חכם ישמח האב, גורם שמחה לאביו שבשמים, וזו השמחה באה מחמת תענוג [הבן]. והנה קודם שאכל הבשר נמצא היה השכל בבשר, רק שהיה בהעלם גדול. וא\"כ בתחילה היה בדומם וצומח, והיה שם גם השכל האנושי והשמחה והתענוג בהעלם, ואח\"כ נתגלה מדומם לצומח, ואח\"כ לחי וכו'. והנה אם היה כל זה באנשים מחולפים, עד\"מ ראובן שמעון וכו', היה לכל אחד שם בפני עצמו, כגון בתחילה בצירוף דומם, ואח\"כ צומח וכו'. אע\"פ שהכל מציאות א', מכל מקום כל מה שנתקרב יותר אל השורש שלו יש לו צירוף אחר.) <i>(חסר)</i>.\n<b>והנה</b> חכמה עילאה נקרא ריש דרגין. וחכמה תתאה היא כחותם המתהפך ונעשה שי\"ר, [זהו פרק שירה], (וזהו חכמות שמשורש) [ר\"ל החכמה שבו שמשורר] שהולך לשלימותו. ועד\"ז היו הלוים משוררים, כי הכהנים עובדים במחשבתם, והלוים מגביהים הדבר המוקרב עד עולם המחשבה ע\"י קולם הנקרא גם כן שירים. והנה כח הפועל במדריגות תחתונים נקרא רגל\"י [נ\"א: רגלין], כמ\"ש והארץ הדום רגלי. וז\"ש תופר מנעלים היה, ר\"ל שהיה (כח הפועל שבתחתונים) [תופר ומחבר] ומעלה כח הפועל בדברים התחתונים [נ\"א: שבמדריגת התחתונים] לשרשו, ואמר לשם יחוד קב\"ה ושכינתיה, כי כח הפועל שבתחתונים נקרא מלכות (<sup data-n=\"3\">לה</sup>כי מחשבת אין מלך בלא עם גרמה להויות העולמות, ועוד, כי כח הנזכר היא מדריגה התחתונה מהפועל, והיא כנוקבא לגביה, שמקבלת ממנו).\n<b>והנה</b> משה עלה למרום, פי' שהעלה כל כך עד למרום, פירוש בינה, כי משה זכה לבינה, לכך אמרו המלאכים ברוך שם כבוד מלכותו לעולם ועד. כי מה שבתחתונים נקרא מלכות כנזכר [נ\"א: כי נעשה יחוד על ידי זה כנ\"ל]. והורידו לישראל, שגם הם יהיו מעלים דברים תחתונים כמותו. ומ\"ש<sup data-n=\"4\">לו</sup> בחשאי, פי' שכל אלוהו\"ת, כי כשכוונתו כך לשם שמים זה נקרא חכמה תתאה, שצריך להעלותה ולהכניס (בהם) [בה] אלהו\"ת, וכן נקראים מים תחתונים שבוכים. (<sup data-n=\"5\">לז</sup>אבל מעשה התורה והמצות, שהם בעצמם אלהו\"ת כביכול, זה נקרא חכמה עילאה.) <i>כך נ\"ל ששמעתי פעם אחת.</i>",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קלא-קלב (קמ). אוה\"א נו, ב.</b>\n<i>כשעלה משה למרום כו'</i> – דב\"ר ב, לו.<i> משל לבת מלך כו'</i> – פסחים נו, א.<i> ב' מיני מים עליונים ותחתונים</i> – זח\"א יז, ב.<i> אמר ר\"ע וכו' אל תאמרו כו'</i> – חגיגה יד, ב.<i> ומים התחתונים בוכים כו'</i> – תקו\"ז ת\"ה יט, ב.<i> שאמרו רז\"ל על חנוך כו'</i> – עמק המלך שער קרית ארבע פצ\"ד (קיג, שלהי ע\"ד). עשרה מאמרות, מאמר אכ\"ח ח\"ג סי' כב. מגיד מישרים להב\"י פ' מקץ בסוף מהד\"ב.<i> חכמות בחוץ תרונה</i> – משלי א, כ.<i> חכמה עילאה ו[חכמה] תתאה</i> – זח\"א קמא, ב.<i> וע\"ד הוא אח\"ד כו'</i> – זח\"ב קלד, א. ובהג' החיד\"א שם.<i> התוספות במס' סוכה</i> – דף מה, א.<i> הוא\"ו במקום אל\"ף</i> – ראה זח\"ג קסג רע\"ב. זו\"ח בראשית ה סע\"ג.<i> וא\"ו בגימ' י\"ג</i> – זח\"ג רכז, א. שם סו, ב.<i> בספר יצירה אם רץ כו'</i> – ס\"י פ\"א מ\"ח.<i> איהו ממלא כל עלמין</i> – זח\"ג רכה, א.<i> כל מה שיש בים כו'</i> – חולין קכז, א.<i> דלא אכלית כו'</i> – ב\"ק עב, א.<i> וכשבן חכם ישמח האב</i> – ע\"פ משלי טו, כ.<i> חכמה עילאה נקרא ריש דרגין</i> – ראה זח\"א ב סע\"א וביאורו בשער מאמרי רשב\"י (לו, ב).<i> כי הכהנים כו' והלוים כו'</i> – ראה זח\"ג לט, א.<i> והארץ הדום רגלי</i> – ישעיה סו, א.<i> כי מחשבת אין מלך כו' גרמה כו'</i> – ראה פרדר\"א פ\"ג.<i> אין מלך בלא עם</i> – רבנו בחיי וישב לח, ל. ראה פדר\"א פ\"ג. זח\"ג רעא, ב. תקו\"ז תכ\"א ס רע\"ב.<i> כנוקבא . . המקבלת</i> – תקו\"ז תנ\"ה פט, א.<i> משה זכה לבינה</i> – זח\"ב קטו, א. זח\"ג רכג, א. ראה ר\"ה כא, ב.\n----- שולי הגליון -----\n<b>לג</b> ) <i>נ\"א במדל\"י: </i>כי הנה יש ב' מיני מעשים, א' הוא לימוד התורה וקיום המצות, והב' הוא עניני עוה\"ז אשר בהם ג\"כ צריך לקיים בכל דרכיך דעהו, כמו שאמרו <i>(כבפנים)</i>.\n<b>לד</b> ) <i>הסוגריים גם במדל\"י.</i>\n<b>לה</b> ) <i>הסוגריים גם במדל\"י</i>.\n<b>לו</b> ) <i>נ\"א במדל\"י:</i> וזה הביאו לה בחשאי, שצריך להמשיך לה שכל מחכמת אלהות, וזה נקרא חכמה תתאה שצריך להעלותה ולהכניס בה חכמת אלהות. וכן נקראים מים תחתונים בוכים. אבל <i>(כבפנים)</i>.\n<b>לז</b> ) <i>במדל\"י ליכא סוגריים.</i>\n----- הערות וציונים -----\n<i>כמו שאמרו רז\"ל על חנוך כו'</i> – ראה כש\"ט סי' מב-א, ושם סי' צא.\n<i>וכתיב חכמות . . חכמה עילאה ותתאה</i> – ראה סי' תכד ד\"ה וכתיב חכמות.\n<i>ח' הוא ו' וז' ותג המחברם</i> – ראה סוף סי' סא, וסוף סי' רסב.\n<i>איהו ממלא כל עלמין וזה נקרא כח הפועל בנפעל</i> – ראה סי' קמה.\n<i>חכמה עילאה נקרא ריש דרגין וח\"ת . . שי\"ר</i> – ראה סי' תכד סד\"ה וכל הנזכר.\n<i>כי מחשבת אין מלך בלא עם גרמה כו'</i> – ראה סי' שצ ובהערות שם."]]],[400080500,"תלו\n\n<b>הנה</b> אמרו רז\"ל בעשרה מאמרות נברא העולם, בראשית נמי מאמר הוא. והנה בבראשית כתיב א\"ת השמים וא\"ת הארץ, את לרבות תולדותיהם. והנה אמרו רז\"ל (כי) [כל] מעשה בראשית נרמז במאמר ראשון, ואח\"כ נאמר כל אחד בפרוטרוט. והענין, כי נודע כי קודם שנתהוו העולמות תחילה עלה ברצון הקדום לברוא כל העולמות. והנה זה לא נקרא אפילו בשם אמירה, שהיא בלב, וזהו מדריגה עליונה מאוד, ובו (<sup data-n=\"1\">לח</sup>ר\"ל ברצון הקדמון) היו כלולים כל העולמות וכל המדריגות דרך כללות, ואח\"כ נמשכו דרך פרטות.\n<b>והנה</b> בראשית ג\"כ לשון אמירה, כמו ארש\"ת שפתיו, אך הוא בלשון תרגום. והענין כי [הוא] על רצון הקדמון שממנו נמשך הכל, ולכן כתיב בלשון תרגום, כי מדריגה עליונה כזו אין בה התגלות אלא בחינת תרגום שבה (<sup data-n=\"2\">לט</sup>והיא חכמה שהיא בחינת אחוריים ומלכות עולם שלמעלה ממנה, כי כן הוא בכל המדריגות, <i>וצ\"ע</i>), לכן כתיב בתרגום יונתן בחוכמתא ודו\"ק.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י שלהי סי' קלד (קמב). אוה\"א נח, ב.</b>\n<i>בעשרה מאמרות כו'</i> – אבות פ\"ה מ\"א.<i> בראשית</i> – בראשית א, א.<i> בראשית נמי מאמר הוא</i> – ר\"ה לב, א.<i> א\"ת השמים וא\"ת הארץ</i> – בראשית א, א.<i> את לרבות תולדותיהם</i> – פרש\"י בראשית א, יד. ע\"פ בר\"ר א, יד.<i> מעשה בראשית נרמז כו'</i> – זח\"א טז רע\"ב. שם רנו, ב. זו\"ח (מדה\"נ) בראשית ב, ד.<i> אמירה שהיא בלב</i> – זח\"א רלד, ב. זח\"ב יז, א. זח\"ג קסא, א.<i> ארש\"ת שפתיו</i> – תהלים כא, ג.<i> בחי' תרגום שבה . . שהיא בחי' אחוריים</i> – ראה ע\"ח של\"ד פ\"ב כלל ח. לקו\"ת וטעה\"מ, ושעה\"מ, פ' ואתחנן (ענין כונת התרגום).<i> בת\"י בחוכמתא</i> – בראשית א, א. זח\"א לא רע\"ב.\n----- שולי הגליון -----\n<b>לח</b> ) <i>הסוגריים גם במדל\"י</i>.\n<b>לט</b> ) <i>במדל\"י אין סוגריים, ואין שם המילים \"והיא חכמה\" אלא </i>ר\"ל שהיא <i>(כבפנים), וגם \"וצ\"ע\" ליכא שם</i>.\n----- הערות וציונים -----\nראה סי' קב. ובאוה\"א לד, א בקיצור: קשה למה לא נכתב בתורה במאמר הראשון לשון ויאמר כמו בשאר מאמרות, ותירוץ כי בהירות של מאמר הראשון א\"א לקבל ולכך כתיב בלשון בראשית. וראה ג\"כ לעיל סי' ג ושם באו\"א."]]],[400080501,"תלז\n\n<b>תפילין</b> דמארי עלמא מה כתיב בהו. ישראל אשר בך אתפאר<sup data-n=\"1\">מ</sup>, ר\"ל שהקב\"ה מתפאר בישראל, וזהו נקרא תפילין.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קלה (קמג). אוה\"א נט, א.</b>\n<i>תפילין דמארי עלמא כו'</i> – ברכות ו, א.<i> ישראל אשר בך אתפאר</i> – ישעיה מט, ג.<i> וזהו נקרא תפילין</i> – ראה זח\"ב סב סע\"א ואילך.\n----- שולי הגליון -----\n<b>מ</b> ) <i>במדל\"י לא הביא פסוק זה אלא</i> שהתפילין נקרא פאר (ברכות יא, א), ר\"ל <i>(כבפנים)</i>.\n----- הערות וציונים -----\nהשוה לעיל סי' שצג.\n<i>ישראל אשר בך אתפאר</i> – להעיר ממש\"כ שם בגמרא ומי משתבח קוב\"ה בשבחייהו דישראל אין דכתיב את ה' האמרת היום וה' האמירך היום. ובפרש\"י כי תבוא כו, יז והוא לשון תפארת כו'.\n<i>וזהו נקרא תפילין</i> – ראה ברכות יא, א התפילין שהרי נאמר בהם פאר."]]],[400080502,"תלח\n\n<b>כי</b> מי גוי גדול בחד ביתא. הנה יש לדקדק שינוי לשון בפסוק, שמתחילה אמר אשר לו אלהים קרובים אליו, ואח\"כ הזכיר שם המיוחד כה' אלהי\"נו וגו'. אך הענין הוא כי אלהי\"ם הוא שם משותף. אפילו דיין נקרא אלהי\"ם, וכן כל שרי מעלה נקראים כן. והנה שכל האנושי מחייב שיותר יוכל האדם להתקרב ולבקש בקשתו משרי מעלה שהם קרובים במעלה אלינו, יותר מהשם יתברך שהוא גבוה מאוד [כמ\"ש] כי גבוה מעל גבוה שומר. וזה היה טעות דור הפלגה. אבל האמת אינו כן. כי הש\"י הוא ממלא כל עלמין וסובב כל עלמין ואיהו בתוך עלמין וכו', וא\"כ הוא יתברך קרוב אלינו יותר מכל השרים, שהם רק במקומם ותו לא. וז\"ש כי מי גוי גדול אשר לו אלהי\"ם קרובים, פירוש שרי מעלה, שקרובים לתחתונים כנזכר, כה' אלהי\"נו, שהוא גבוה מאוד מהתחתונים ואעפ\"כ הוא קרוב אלינו יותר.\n<b>ואיתא</b> בת היה לאברהם ובכל שמה. והענין כי אמרו רז\"ל בהברא\"ם באברה\"ם, שכל העולמות נבראו באהבה, מדת אברהם. והנה הצדיק נקרא כ\"ל, והמקבל ממנו נקרא בכ\"ל, בי\"ת כ\"ל. וכל העולמות הם כגוף נגדו יתברך, לפי שכולם מקבלים ממנו יתברך. וז\"ש בת היה לאברהם אבינו וד\"ל. וכתיב בזאת יבוא אהרן אל הקודש. פירוש זא\"ת היא השכינה, ור\"ל כי תחילה צריך להתלבש ביראה, כי זה השער לה' כמ\"ש בספר הזוהר. וז\"ש בכ\"ל קראינו אליו, ר\"ל אנו [נ\"א: אם] קוראים אליו בכ\"ל, שהיא השכינה, אז הוא קרוב אלינו. והנה זה שהש\"י קרוב אלינו זהו מדת הענוה, מפני כי ה' בחכמה יסד ארץ, כולם בחכמה עשית, והחכמה היא מדת הקטָנה כמ\"ש והחכמה מאי\"ן תמצא. לכן השי\"ת ג\"כ ממלא כל עלמין. והנה פרשה ראשונה קדש לי כל בכור, היא נקראת ראשי\"ת, וקדש, בלא וא\"ו שמורה על ההמשכה. לכן כנגדה כתיב כי מי גוי גדול, ששם ג\"כ מרומז חכמה, מדת הענוה והקטָנה כנזכר. והבן היטב.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קלה (קמד). אוה\"א נט, א.</b>\n<i>כי מי גו'</i> – ואתחנן ד, ז.<i> כי מי גוי גדול בחד ביתא</i> – ברכות ו סע\"א.<i> אשר לו גו' כה' אלהי\"נו גו'</i> – ואתחנן ד, ז.<i> אלהי\"ם הוא שם משותף כו'</i> – זח\"ג קיג, א. זו\"ח (מדה\"נ) בראשית ד, א. מו\"נ ח\"א פ\"ב.<i> אפילו דיין כו'</i> – מכילתא פ' משפטים מס' דנזיקין פ\"ב. סנהדרין ג, ב.<i> וכן כל שרי מעלה כו'</i> – רמב\"ם הלכות יסוה\"ת פ\"ב ה\"ז. מו\"נ ח\"ב פ\"ו.<i> שכל האנושי מחייב שיותר כו'</i> – ראה דרשות הר\"ן דרוש ד' ודרוש ט'.<i> גבוה מעל גבוה שומר</i> – קהלת ה, ז.<i> וזה היה טעות כו'</i> – ראה רמב\"ם הלכות ע\"ז פ\"א.<i> ממלא כל עלמין כו'</i> – זח\"ג רכה, א.<i> וז\"ש כי מי כו'</i> – ראה ירושלמי ברכות פ\"ט ה\"א עה\"פ.<i> בת הי' לאברהם כו'</i> – ב\"ב טז, ב.<i> בהברא\"ם</i> – בראשית ב, ד.<i> באברה\"ם</i> – בר\"ר יב, ט.<i> הצדיק נקרא כ\"ל</i> – (יסוד) זח\"א לא סע\"א. זח\"ג רנז, א.<i> המקבל ממנו נקרא בכ\"ל</i> – (מלכות) זח\"ב לו סע\"א. שם לז, א ופה, ב.<i> בזאת יבא גו'</i> – אחרי טז, ג.<i> זא\"ת היא השכינה</i> – זח\"ג רצז סע\"ב. תקו\"ז תכ\"א נו, א.<i> תחילה צריך כו'</i> – זח\"ג נו, ב שם קח, א.<i> זה השער לה'</i> – תהלים קיח, כ.<i> כמ\"ש בספר הזוהר</i> – זח\"א ז, ב. זח\"ג רנו, ב.<i> בכ\"ל קראנו אליו</i> ואתחנן שם (ד, ז).<i> ה' בחכמה גו'</i> – משלי ג, יט.<i> כולם בחכמה עשית</i> – תהלים קד, כד.<i> והחכמה מאי\"ן תמצא</i> – איוב כח, יב.<i> פרשה ראשונה כו'</i> – מנחות לד סע\"ב. זח\"ב מג סע\"א.<i> קדש לי כל בכור</i> – בא יג, ב ואילך.<i> היא נקראת ראשי\"ת</i> – (חכמה) תקו\"ז תי\"ד ל, א.<i> וקדש בלא וא\"ו</i> – זח\"ב קכא סע\"א.<i> וא\"ו שמורה על ההמשכה</i> – ראה זו\"ח (סת\"א) בראשית ה, ג. תקו\"ז תנ\"ב פז, א.\n----- הערות וציונים -----\nראה סי' קנח-א.\n<i>ואיתא בת היה לאברהם כו'</i> – ראה סי' כט.\n<i>בכ\"ל בי\"ת כ\"ל</i> – ראה סי' טז ד\"ה ואפשר, וסי' כט. וראה סוף סי' קנז (בכ\"ל לשון כללות). וסי' שסה סד\"ה ומה.\n<i>בזאת יבוא אהרן כו'</i> – ראה סי' צט סד\"ה כי. סי' קעב ד\"ה ומ\"ש (סי' רנט). וסי' קפד ד\"ה והנה תחילת.\n<i>תחילה צריך להתלבש ביראה</i> – השכינה ספי' מלכות, ראה סי' נט ד\"ה ויש. סי' סז. סי' קנא-ד. וסי' תקג.\n<i>כי זה השער לה' כו'</i> – ראה סי' נט ד\"ה ויש. סי' קעב ד\"ה ומ\"ש. וסי' קפד ד\"ה והנה תחילת.\n<i>והחכמה היא מדת הקטנה</i> – ראה סי' לח ד\"ה הנה, סי' רמח ד\"ה וזהו (ואילך), ושם רד\"ה ולפי, ובהערות שם. וראה סי' תכד סד\"ה וכתיב ה' בחכמה.\n<i>וקדש בלא וא\"ו</i> – ראה סי' שסג סד\"ה ויש לתרץ."]]],[400080503,"תלט\n\n<b>לעולם</b> ישנה אדם לתלמידו דרך קצרה. גם מעשה דרבי יוסי שהתפלל בחורבה, וא\"ל אליהו היה לך להתפלל תפלה קצרה. דהיינו כשהרב רוצה להבין לתלמידו שכלו הרחב, ואין התלמיד יכול לקבלו, אז הרב מצמצם שכלו בדיבורים ואותיות. עד\"מ כשאדם רוצה להריק מכלי אל כלי ומתיירא שמא ישפוך לחוץ, אזי נותן כלי הנקרא משפך, ובזה המשקה ההיא מצומצמת, ועל ידה מקבלת הכלי ההוא ולא יושפך דבר החוצה. וכן הוא הדבר הזה, ששכל הרב מצומצם בדיבורים ואותיות אלו שאומר לתלמיד, ועי\"ז יוכל התלמיד לקבל שכל הרב הרחב. והנה עולם כזה נקרא עולם העקודים, שהשכל עקוד ומצומצם בו. והנה השערות נקראים כמו כן מותרי מוחין ע\"ד הנזכר, כמ\"ש במקום אחר. וזהו נודע בשערי\"ם בעלה, וזרח משעי\"ר למו, שהוא לשון שערות. ואיתא בזוהר אית שערין קשישין ואית שערין רכיכין, דהיינו שערות הראש והזקן. והממוצע שביניהם והמחברם הם [שערות] הפאה שנמשכין כנגד הראש ועד הזקן. והנה י\"ג מדות שהתורה נדרשת בהם הם ג\"כ על דרך זה. כי משה עצמו לא היה צריך להם, אך התורה שבע\"פ, שהיא הנוקבא, שבה הדרשה אינה יכולה לקבל בהירות התורה שבכתב כי אם ע\"י י\"ג מדות, [והיינו] קל וחומר וגזירה שוה וכו'.\n<b>ועוד</b><sup data-n=\"1\">מא</sup> <i>שמעתי</i> דהיינו שאומר לתלמידיו שכלו הרחב באותיות נמוכים, ומשפיל שכלו מעט מעט באותיות ההם, וכל מה שמרחיב האותיות ההם משפיל שכלו יותר נמוך, שיוכל התלמיד יותר לתפוס שכל הרב באותיות ההם. ואח\"כ, כשנתפס שכל הרב, מתגדל הבן או התלמיד בשכל ההוא, ויוכל אח\"כ להבין שכל הרב בלי ממוצע כל כך, והבן היטב. והנה בוודאי לא יתן הרב שכלו הרחב כי אם למי שמוכן לזה, דהיינו לתלמידו וכדומה, והוא נוקבא לזה.\n<b>ומצורע</b> נקרא סגירו נהורא עילאה. דהיינו שהחכמה, פירוש שכל העליון, מוסגר ממנו, והוא צריך לו. וע\"כ מרים כשהיתה מצורעת כשלג, והיתה צריכה להמשכת החכמה, התחיל משה בתפילתו א\"ל, שהוא מדה ראשונה מי\"ג מדות. כי ב' הויו\"ת הראשונים אינם נכללים בין הי\"ג מדות כנודע. ובהירות הוי\"ה גדול, ואין עולם התחתון יכול לקבלו כי אם ע\"י אמצעות. וע\"כ המדה הא' הוא א\"ל. <i>ופעם אחרת שמעתי</i> כי ב' הויו\"ת הנזכרים, הא' הוא הוי\"ה עליונה, והב' הוא הוי\"ה שכח הפועל בנפעל, דהיינו מה שבעולמות התחתונים, ודו\"ק.\n<b>וע\"כ</b> המדה הראשונה היא א\"ל, שהוא אל\"ף והיינו פל\"א, שהעולם העליון מופלא מהתחתון. ואח\"כ נמשך ממנו לרצון עולם התחתון, והמשכת ו' אל אות (ב') [כ] נעשה ל', והיא תמונת ט' (להיפך) [הפוכה]. לפי שיש י\"ג מדות, ויש ט' מדות כמ\"ש בפרשת שלח. והיינו שבעולמות עליונים (ששם) [יש] הרבה בהירות, ע\"כ הם י\"ג. ובעולמות תחתונים מהם, שאין בהם כ\"כ בהירות, הם רק ט' מדות, כמשל הרב עם התלמיד, ר\"ל אם אין בתלמיד כח לקבל שכל הרב הרחב אזי מצמצם הרב יותר, ובתלמיד כזה שכל הרב יותר מצומצם וד\"ל.\n<b>והנה</b> משה בתפילתו נעשה המשכה, השיבה<sup data-n=\"2\">מב</sup> כמדתו קל וחומר (<sup data-n=\"3\">מג</sup>כמ\"ש רז\"ל ואביה ירוק [כו'] ק\"ו לשכינה [כו']), שהיא מדה הראשונה מי\"ג מדות הנקראת א\"ל. וזהו קל וחומר, שעולם עליון נקרא ק\"ל ועולם התחתון נקרא חומ\"ר, ע\"ד חומר וצורה, שהנוקבא נקראת חומ\"ר והדכר נקרא צור\"ה, וכן כאן עולם התחתון המקבל נקרא חומ\"ר.\n<b>ונחזור</b> לענין עולם העקודים שהשכל עקוד בתוכו, והוא בכלי אחד ובו עשר שכליים. אך מה שהוא עשר שכליים הוא ע\"ד צהבו פניו של רבי, שע\"י מדת אהבה, דהיינו כשהאב רואה את בנו אז נתגלה בפני אב אהבה [וד\"ל]. <i>עד כאן לשון הרב זלה\"ה</i>. ואח\"כ <i>שמענו </i>שהקל וחומר הוא שנוטלין מעולם העליון ונותנין לעולם התחתון, ואעפי\"כ נשאר בעולם העליון הדבר ההוא ואין נגרע ממנו. הוא מה שמבואר בע\"ח בשער אח\"פ, שכל דבר שבקדושה אעפ\"י שהלך האור ממקום למקום לא נגרע האור ממקום הראשון. והבן זה היטב מאוד.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קלט (קמז). אוה\"א נט, ב.</b>\n<i>לעולם ישנה כו'</i> – פסחים ג, ב.<i> מעשה דרבי יוסי שהתפלל כו'</i> – ברכות ג, א.<i> עולם כזה נקרא עולם העקודים</i> – ראה ע\"ח ש\"ו פ\"ג. שם ש\"ז רפ\"א.<i> השערות נקראים כמו\"כ מותרי מוחין</i> – זח\"ג קלד, א. מבו\"ש ש\"ה ח\"א ספי\"ג.<i> כמ\"ש במ\"א</i> – לעיל סי' קיח.<i> והממוצע ביניהם כו'</i> – ראה ע\"ח שי\"ג פי\"א.<i> נודע בשערי\"ם בעלה</i> – משלי לא, כג.<i> וזרח משעי\"ר למו</i> – ברכה לג, ב.<i> ואיתא בזוהר אית כו'</i> – זח\"ג קלא, ב.<i> י\"ג מדות כו'</i> – ריש תו\"כ.<i> התושבע\"פ שהיא הנוקבא</i> – תקו\"ז ו, א. שם יז, א.<i> סגירו נהורא עילאה</i> – זח\"ג מט, ב.<i> מצורעת כשלג</i> – בהעלותך יב, י.<i> התחיל משה בתפלתו א\"ל</i> – בהעלותך יב, יג.<i> שהוא מדה ראשונה מי\"ג מדות</i> – זח\"ג קלא, ב. ע\"ח שי\"ג פי\"א.<i> ב' הויו\"ת הראשונים כו'</i> – ראה ע\"ח שם.<i> אל\"ף והיינו פל\"א</i> – זח\"ג קצג, ב. תקו\"ז ת\"ע קלה, א.<i> שיש י\"ג מדות</i> – כי תשא לד, ו-ז.<i> בפרשת שלח</i> – שלח יד, יח.<i> ואביה ירוק</i> – בהעלותך יב, יד.<i> ק\"ו לשכינה</i> – ב\"ק כה, א.<i> מדה הראשונה כו' וזהו קו\"ח</i> – ראה זח\"ג רכח, א.<i> שהנוקבא נקראת חומ\"ר</i> – זח\"א קפא, ב ע\"פ זח\"ב קיח, ב.<i> צהבו פניו של רבי</i> – חולין ז, ב.<i> ונחזור כו' והוא בכלי אחד כו'</i> – ע\"ח ש\"ז פ\"א.<i> מ\"ש בע\"ח כו'</i> – ע\"ח ש\"ד ספ\"ג. ראה שם ש\"ו פ\"ו. של\"ד פ\"ג. שמ\"ז פ\"ו.\n----- שולי הגליון -----\n<b>מא</b> ) <i>במדל\"י קטע זה </i>ועוד . . והוא נוקבא <i>בסוגריים. ואח\"כ ד\"ה חדש </i>לזה ומצורע<i>, אבל נראה ש\"לזה\" צ\"ל בסוף קטע זה</i>.\n<b>מב</b> ) <i>נראה שצ\"ל</i> השיבו <i>(הקב\"ה למשה) </i>כמדתו <i>(שהתפלל במדת א\"ל)</i>. <i>במדל\"י נ\"א:</i> והנה משה רבינו ע\"ה עשה המשכה במדת קל וחומר.\n<b>מג</b> ) <i>הסוגריים גם במדל\"י</i>.\n----- הערות וציונים -----\n<i>עולם העקודים שהשכל עקוד כו'</i> – ראה ריש סי' צח.\n<i>משעי\"ר למו שהוא לשון שערות</i> – ראה סי' לח ד\"ה וז\"ש.\n<i>והממוצע שביניהם והמחברם כו'</i> – ראה סי' קמח.\n<i>והוא נוקבא לזה</i> – ראה סי' לח ד\"ה ונמצא.\n<i>ומצורע נקרא כו'</i> – הובא באוה\"ת לאדמו\"ר הצ\"צ פ' בהעלתך ע' תב בתוס' הגהות.\n<i>ובהירות הוי\"ה גדול כו'</i> – ראה סי' עא ד\"ה וז\"ש כי שמש.\n<i>א\"ל שהוא אל\"ף כו' ואח\"כ נמשך כו'</i> – ראה סי' תמה. וראה סי' קנג ובהערות שם.\n<i>והמשכת ו' אל אות כ נעשה ל והיא תמונת ט' הפוכה</i> – ראה סי' קעט-ב ד\"ה וידוע.\n<i>כמדתו קל וחומר כו'</i> – עיין סי' קלז."]]],[400080504,"תמ\n\n<b>עד</b> אברהם לא היה זקנה. רמז על התגלות דיקנא עילאה קדישא, שהתחלתה היא מתיקון א\"ל. והמדה הנזכרת מתיחסת לאברהם הנקרא חסד לאברהם. וגם שם א\"ל הוא חסד, כמ\"ש חסד א\"ל כל היום וגו'.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קפז (קצד). אוה\"א עא, ב.</b>\n<i>עד אברהם כו'</i> – ב\"מ פז, א.<i> התגלות דיקנא עילאה כו'</i> – זח\"ג קלא, א ואילך. ראה מבו\"ש ש\"ג ח\"ב פי\"א.<i> שהתחלתה היא כו'</i> – זח\"ג שם.<i> חסד לאברהם</i> – מיכה ז, כ.<i> שם א\"ל הוא חסד</i> – זח\"ג ל, ב. שם לא, א.<i> חסד א\"ל כל היום</i> – תהלים נב, ג.\n----- הערות וציונים -----\nבאוה\"מ פ' ואתחנן ד\"ה כי מי: שמעתי מפי המגיד זללה\"ה שביאר דברי חז\"ל עד אברהם לא הוה זקנה להיות תכלית הבריאה שתתגלה ותתפרסם התפשטות מדותיו יתברך שהיו כמוסים בעצמותו כי אין מלך בלא עם וגם אם אין ישראל על מי יגלה מדות רחמנות וכדומה שארית המדות, ונודע אברהם אבינו תחילת התגלות מדות החסד בעולם כמו דאיתא לשעבר נקרא אלהי השמים ועכשיו הרגלתי שמך בפי הבריות ונקרא אלהי הארץ, והנה עיקר בחינת התגלותו בהעולמות הוא באמצעות התלבשות י\"ג תיקוני דיקנא אשר ראשית התיקונים מתחיל בכינוי אל כנוי מדות החסד כנאמר חסד אל והוא מדות אברהם שאחז בה, ולזה כיוונו במאמרם עד אברהם היינו בחינתו לא הוי דיקנא, כ\"א מכינוי מדתו והלאה מתחילין התיקונים אל רחום וחנון, וכינוי אל מורה על מדתו מדת החסד. (וכן שם בדרוש לראש השנה ד\"ה והכלל תכלית הכוונה.) ובאורח לחיים פ' חיי שרה ד\"ה ואברהם: שאמר הרב הגדול בוצ\"ק מוה' דוב בער זללה\"ה פי' עד אברהם לא הוי דיקנא כלומר שלא היה בעולם לעורר על ידי מעשיו י\"ג תיקוני דיקנא המתחילין מן אל עד שבא אברהם אבינו והתעורר מדת אל חסד עליון ע\"י השפעתו למטה בברואי עוה\"ז כן התעורר למעלה עכ\"ד ודפח\"ח."]]],[400080505,"תמא\n\n<b>מותר</b> להתגרות ברשעים בעולם הזה שנאמר עוזבי תורה יהללו רשע ושומרי תורה יתגרו בם, ואם לחשך אדם וכו'. ויש לדקדק מה ענין מותר דקאמר. הוי ליה למימר מצוה או חיוב, הואיל דנפקי [לן] מקרא, כמו שאר מצות וחיובי דרבנן דאסמכוהו אקרא, כמו חייב אדם להקביל פני רבו וכיוצא. ועוד קשה על לשון הפסוק, הלוא עוזבי התורה הם הרשעים, והשומרים הם הצדיקים, והוי ליה למימר [רשעים יהללו, וצדיקים וכו'. ועוד, רישא דקרא אמר לשון יחיד, וסיפא דקרא אמר לשון רבים, יתגרו בם, הוה ליה למימר] בתרווייהו חד לישנא.\n<b>וי\"ל</b> כי באמת הכתוב מדבר [בין ברישא בין בסיפא בצדיק]. כי הנה יש ב' גוני צדיקים. יש צדיק שהוא עוסק בתורה ובגמילות חסדים וקיים כל התורה, אך הוא צדיק לעצמו ולא לאחרים להחזירם למוטב. ואעפ\"י שזו היא אחת ממצות התורה, שנאמר הוכח תוכיח וגו', עם כל זה מגודל רכות טבעם ומזגם הטוב אין יכול לומר לזולתו לא עשית כהוגן וכשורה. ויש צדיקים העומדים בפרץ, ומתגרים תמיד בעושי עולה ומוכיחים ומחרפים אותם בתמידות על מעשיהם המכוערים, כמ\"ש ובתקוממיך אתקוטט וגו'. והנה לכת צדיקים הב' הכל שונאים אותם, כמ\"ש רז\"ל האי צורבא מרבנן דרחמי ליה בני מתא וכו'. ומחמת זה שונאים אותם ביותר בהיותם שרואים שכת הראשונה הם צדיקים גמורים ושותקים, מסתמא אינם רשעים כל כך כמו שמחזיקים אותם הכת הב'. ומכח זה מריבים ומתגרים הכת הב' עם הכת הא', מדוע אתם מחשים הלוא אתם צדיקים וקנאים ושלימים, ולמה לא תקנאו קנאת ה'.\n<b>וזהו</b> פירוש יתגרו בם, ר\"ל הכת הב' מתגרים עם הכת הא' לשם שמים, שיעמדו ג\"כ בפרץ עמהם להלחם נגד אויבי ה'. והנה הכת הא' מחמת רכות טבעם אינם רואים חוב לרשעים, ומהפכים בזכותם ומשיבים אולי לא היה כך כאשר [מריבים ו]מרננים עליהם, או זכות אחר, או מזכירים מדות טובות שיש לרשעים הנזכרים. וזהו יהללו רשע, ר\"ל מחמת טבעם מהפכים בזכותם. ועוד אומרים, אי אפשר להעמיד הדת על תילה. ועוד, הנח לישראל מוטב וכו'. ומחמת כל אלו הטענות נמנעים לו מלהוכיחם. אבל עם כל זה, אע\"פ שהם צדיקים, הכתוב קורא אותם עוזבי תור\"ה, הוא לשון הוראה ומוסר. והכת הב' נקראים שומרי תורה. וזהו עוזבי תורה יהללו רשע ושומרי תורה יתגרו בם, (ר\"ל מתגרים בם) ר\"ל מתגרים עם הכת הא' הנקראים עוזבי תורה. נמצא לפי פירוש הנזכר אינו מפורש בקרא שמצוה להתגרות ברשעים. כי מ\"ש יתגרו בם קאי שמתגרים עם הצדיקים הראשונים הנזכרים. ולכך לא אמרו בלשון חיוב או מצוה, כי אינו מפורש בקרא. אך ההיתר ממילא משתמע מדקאמר עוזבי תורה יהללו רשע כנזכר, מחמת התיגרא שנפלה בין ב' כתות הצדיקים. אם כן מוכרח הוא שמותר להתגרות ברשעים כנזכר. <i>מהרב הגאון מורינו נר\"ו.</i>",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לב, א (סי' רנו). אוה\"א עב, א.</b>\n<i>מותר להתגרות כו'</i> – ברכות ז, ב.<i> עוזבי תורה גו'</i> – משלי כח, ד.<i> חייב אדם להקביל כו'</i> – ר\"ה טז, ב.<i> הוכח תוכיח גו'</i> – קדשים יט, יז.<i> ובתקוממיך אתקוטט גו'</i> – תהלים קלט, כא.<i> האי צורבא מרבנן כו'</i> – כתובות קה, ב.<i> להעמיד הדת על תילה</i> – ע\"פ לשון הרמב\"ם הלכות סנהדרין פכ\"א ה\"ה.<i> הנח לישראל כו'</i> – שבת קמח, ב.<i> תור\"ה הוא לשון הוראה</i> – זח\"ג נג, ב.\n----- הערות וציונים -----\n<i>יש ב' גוני צדיקים כו'</i> – להעיר מסי' רנו."]]],[400080506,"תמב\n\n<b>פירוש</b> המשנה השונה ומפסיק ממשנתו ואומר מה נאה אילן זה ומה נאה ניר זה. ומפסיק, פירוש מפסיק את עצמו מהשם יתברך מחמת משנתו, ואומר, בלבו על עצמו, מה נאה אילן זה, ע\"ד האדם עץ השדה, ומה נאה ניר זה, ע\"ד נירו לכם ניר. וזהו פירוש המשנה ההולך בדרך יחידי וכו', ר\"ל שלומד תורה ואפילו הכי הוא יחידי, שאינו דבוק בהש\"י, כי אדרבא בא לו התפארות גדול בשביל לימודו כנזכר, מעלה עליו הכתוב וכו'<sup data-n=\"1\">מד</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, א (סי' רטז). אוה\"א כט, א. כתבי קודש ה, ד.</b>\n<i>השונה ומפסיק כו' מעלה עליו כו'</i> – אבות פ\"ג מ\"ז.<i> האדם עץ השדה</i> – שופטים כ, יט.<i> נירו לכם ניר</i> – ירמיה ד, ג.<i> ההולך בדרך יחידי כו'</i> – אבות פ\"ג מ\"ד.\n----- שולי הגליון -----\n<b>מד</b> ) <i>בלקו\"י בשינויי נוסח וסדר הדברים: </i>המהלך בדרך יחידי. פירוש הולך בדרך הישר, ואפילו הכי הוא יחידי שאינו דבוק בהשי\"ת. ושונה ומפסיק ממשנתו, ר\"ל מפסיק א\"ע מהשי\"ת מחמת משנתו, דהיינו שבאת לו גדלות והתפארות מחמת משנתו, ואומר מה נאה אילן זה, ועל עצמו אומר כן בלבו כמ\"ש כי האדם עץ השדה, ומה נאה ניר זה כמ\"ש נירו לכם ניר, מעלה עליו הכתוב כאלו מתחייב בנפשו.\n----- הערות וציונים -----\nלהעיר מכש\"ט סי' רעח. והשוה לקמן סי' תמג."]]],[400080507,"תמג\n\n<b>הולך</b> ואינו עושה. פי' הולך במדריגות העולמות בכוונת התפילה, ואינו עושה שום פעולה ומופת בתפילתו. [מי מעכב], לפי ששכר (הילוכו) [הליכה] בידו, ר\"ל שמתפאר בזה.\n<b>עושה</b> ואינו הולך, ר\"ל עושה תמיד מצות ועוסק בתורה [ובתפלה], ואינו הולך [ר\"ל שאינו הולך] ממדריגה למדריגה, [דהיינו שאינו מגיע לשום מדריגה, זה] בשביל ששכר מעשה בידו, הוא ג\"כ כנזכר [נ\"א: שבשביל מעשיהו בא לו ההתפארות].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כט, א. כתבי קודש ו, א (וראה שם כג, ג).</b>\n<i>הולך ואינו עושה</i> – אבות פ\"ה מי\"ד.<i> עושה ואינו הולך</i> – שם.\n----- הערות וציונים -----\nראה סי' שלט. כש\"ט סי' רעח. והשוה לעיל סי' תמב ולקמן סי' תמח."]]],[400080508,"תמד\n\n<b>יפה</b> שעה אחת בעוה\"ב. הנה [העולם הזה] מהלך ת\"ק שנה בגשמיות [נ\"א: שבגשמיות צריך לילך ת\"ק שנה], אבל במחשבה [הוא ברגע א'] שהוא למעלה מזמניות. והתענוג ג\"כ שם למעלה מהזמן, מה שבגשמיות אלפיים שנה שם הוא ברגע אחת.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סוף סי' קעט (קפה).</b>\n<i>יפה שעה אחת כו'</i> – אבות פ\"ד מי\"ז.<i> העולם הזה מהלך כו'</i> – תוספות חגיגה יב, א ד\"ה מסוף.\n----- הערות וציונים -----\nראה סי' רמה סד\"ה או יאמר. וסי' שצא ד\"ה וזהו."]]],[400080509,"תמה\n\n<b>א\"ל</b> הוא המשכה מאלופ\"ו של עולם אל ג' קוים שהוא כ\"ל<sup data-n=\"1\">מה</sup>. ואַל בפתח הוא נמשך (מהם בחכמה) [בהם מחכמה], והחכמה מאי\"ן תמצא, לכן [אַ\"ל] פירושו לא, שהוא אין כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קפא (קפז). אוה\"א עב, ב. שמועה טובה סה, ב.</b>\n<i>מאלופ\"ו של עולם</i> – (הא') זח\"ג לא, א.<i> אל ג' קוים</i> – ראה תקו\"ז תס\"ט קד, ב.<i> בפתח . . בחכמה</i> – תקו\"ז ת\"ע קכט רע\"ב.<i> והחכמה מאי\"ן תמצא</i> – איוב כח, יב.\n----- שולי הגליון -----\n<b>מה</b> ) <i>\"שהוא כ\"ל\" ליכא במקבילות. ונראה שצ\"ל</i> שהוא כל'.\n----- הערות וציונים -----\nשייך לחלק פסוקים מלוקטים.\nראה סי' תלט ד\"ה וע\"כ. וראה סי' קנג ובהערות שם.\n<i>בפתח הוא נמשך בהם מחכמה כו'</i> – ראה סי' תלג נקודת פתח . . היא נקודת החכמה."]]],[400080510,"תמו\n\n<b>אסור</b> להגות השם באותיות, לפי שהאויר אינו ראוי שיתלבשו בו אותיות הקדושות אלו, אלא במקדש שהאויר שם מהשכינה כמ\"ש וה' בהיכל קדשו. ומטעם זה אסור להרהר בדברי תורה במקום הטינופת, אם לא לאפרושי מאיסורא בסוד ומלכותו בכל משלה, שמזכיר שם דברי תורה בין הקליפות כדי להכניעם.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קפג (קפט). אוה\"א עב, ב.</b>\n<i>אסור להגות כו'</i> – סנהדרין צ, א.<i> וה' בהיכל קדשו</i> – חבקוק ב, כ.<i> אסור להרהר כו'</i> – שו\"ע או\"ח פה, ב. ראה ברכות כד, ב. שבת מ, ב.<i> אם לא לאפרושי מאיסורא</i> – שבת מ, ב.<i> ומלכותו בכל משלה</i> – תהלים קג, יט.\n----- הערות וציונים -----\n<i>ומטעם זה כו' בסוד ומלכותו בכל משלה כו'</i> – כן הובא בפרדס רמונים שי\"ט פ\"א, וציין שם לשט\"ז פ\"ז ועיין מש\"כ שם על יסוד תקו\"ז תס\"ט קח סע\"ב."]]],[400080511,"תמז\n\n<b>הפורש</b> עצמו מן הציבור. נ\"ל דרך הלצה פירושו. יש אדם שפורש מן השי\"ת בשביל תאוות ממון, ורודף תמיד יום יום לאסוף ממון הרבה, ומחמת זה מבטל תורה ותפלה. וזהו הנקרא כסיל בחושך הולך, ושטות עצמו בידו. כי הנה הוא רוצה לאסוף ממון שצריך להיות סיוע מאתו יתברך, ואיך הוא פורש א\"ע מהשי\"ת. וזהו הפורש מן הצבור, ר\"ל לאסוף ולצבור ממון רב.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א עד, ב.</b>\n<i>הפורש עצמו מן הציבור</i> – ראה אבות פ\"ב מ\"ד. תענית יא, א.<i> כסיל בחושך הולך</i> – קהלת ב, יד."]]],[400080512,"תמח\n\n<b>כל</b> ימי עני רעים. פירוש על פי מ\"ש רז\"ל אין עני אלא מן הדעת. וכך פירושו, כל ימי עני, שהוא בדעת כנזכר, רעים, ר\"ל שאין תפילתו ולימודו נחשבה כלל לפניו יתברך, כי בוודאי הם בלא דחילו ורחימו ולא פרחת לעילא. ופריך והא איכא שבתות וימים טובים, ר\"ל שבוודאי בימים הללו בא לכל אדם התעוררות מלמעלה, ובוודאי מתפלל בהם בכוונה. ותירץ שינוי ווסת, ר\"ל אעפ\"י שמתפלל עתה בכוונה, ורואה א\"ע שמתפלל בכוונה, ומחמת זה באה לו גאוה וגדלות בלבו ורואה א\"ע שעלה עתה במדריגה עליונה, לכן אף עתה הם רעים, לפי ששינוי ווסת הוא תחילת חולי מעים, ר\"ל שאין היצה\"ר מתגרה אלא מתוך אכילה ושתיה, ומחמת זה באה לו הגאות, וד\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לא סע\"ב (סי' רמו). אוה\"א עה, ב. צוה\"ר סי' קלא.</b>\n<i>כל ימי עני רעים</i> – משלי טו, טו.<i> אין עני אלא מן הדעת</i> – נדרים מא, א.<i> בלא דחילו ורחימו לא פרחת לעילא</i> – תקו\"ז ת\"י כה, ב.<i> ופריך והא איכא כו' שינוי ווסת כו'</i> – כתובות קי, ב.<i> שאין היצה\"ר מתגרה אלא כו'</i> – זח\"א (מדה\"נ) קי רע\"א. ראה ספרי עקב פי' מג ושם פי' שיח.\n----- הערות וציונים -----\nזה שייך לרמזי פסוקים מלוקטים.\n<i>שבתות וימים טובים ר\"ל שבוודאי כו'</i> – להעיר מזח\"ג קעט רע\"ב.\n<i>ומחמת זה באה לו גאוה כו'</i> – ראה סי' תמב ותמג ובהערות שם.\n<i>אין יצה\"ר מתגרה כו'</i> – ראה סי' קכא ובהערות שם."]]],[400080513,"תמט\n\n<b>אמרו</b> רז\"ל למה שלח יאשיהו המלך לחולדה הנביאה לדרוש אודות הספר הנמצא ולמה לא שלח אל ירמיהו, ותרצו ז\"ל מפני שהנשים רחמניות הן. ולכאורה אינו מובן כלל. האיך שייך גבי נבואה רחמניות, והלוא הנביא אינו יכול לדבר יותר זולת מה (שאמרו) [שנאמר] לו מפי השי\"ת. <i>ושמעתי בשם מורינו ורבינו דרוש גדול על זה אך אינני זוכר.</i> (<sup data-n=\"1\">מו</sup>ועיין בפרשה עקב תירוץ נכון על זה).\n<b>ועיקר</b> הטעם הוא זה, כי בוודאי היה כח בדברו לשון הנבואה (<sup data-n=\"2\">מז</sup>היה לו יכולת) להפך מרגזנות לרחמנות. והכוונה, כי באמת הנביא לא היה משנה ח\"ו הדיבורים ששמע מפי הקב\"ה, אך הדבר היה תלוי בניגון הנביא באיזה ניגון היה מדבר הנבואה זו לישראל. וידוע כי הניגון (הם) [הוא] טעמים שהם בחכמה. ועיקר הנבואה תלוי בטעמים, והראיה כי רובא דרובא הטעמים של איזה פסוק מהפכים פירוש הפסוק מפשוטו. נמצא כי זה היה תלוי בדיבור הנביא. אם היה מדבר לישראל בטעמים חזקים אז היתה הנבואה כעין רוגזא, ואם היה בטעמים אחרים היו כעין רחמנות. ומה גם כי הנביא היה מעורר בזה רחמנות העליון ע\"י טעמים של רחמים. ולכן שלח לחולדה, לפי שהנשים רחמניות הם, ויכולה להפוך הנבואה ממדת רגזנות לרחמנות. וזהו סוד אדנ\"י אלהים נתן לי לשון לימודים, רצה לומר שהנבואה היא בלשוני, דהיינו על ידי ניגון טעמים.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יח, ב (סי' רלח).</b>\n<i>למה שלח יאשיהו כו'</i> – מגילה יד, ב.<i> ועיין בפרשה עקב</i> – לעיל סי' קסד.<i> טעמים שהם בחכמה</i> – ראה פרדס רמונים שכ\"ט פ\"ה.<i> הטעמים כו' מהפכים פירוש כו'</i> – ראה זח\"א טו, ב ובאוה\"ח שם. וראה תקו\"ז יב, ב.<i> אד' אלקים נתן לי גו'</i> – ישעיה נ, ד.\n----- שולי הגליון -----\n<b>מו</b> ) <i>הבא בסוגריים הוא הערת העורך או המדפיס ס' אור תורה</i>.\n<b>מז</b> ) <i>מה ששמתי בסוגריים אינו בלקו\"י והוא כפל הלשון</i>.\n----- הערות וציונים -----\nעיין סי' קסד ד\"ה ואיתא.\n<i>טעמים שהם בחכמה</i> – להעיר מסי' קמג ד\"ה כתיב, וסי' תכד ד\"ה וכתיב חכמות, שהשתנות ע\"י חכמה.\n<i>הטעמים של איזה פסוק מהפכים כו'</i> – עיין בסוף ההערות לסי' קסד הנעתק ממדל\"י.\n<i>וזהו סוד אד' כו'</i> – מבואר בסי' קסד עיי\"ש."]]],[400080514,"תנ\n\n<b>אין</b> עומדים להתפלל אלא מתוך כובד ראש. פי' אל תתפלל בשביל דבר שחסר לך, כי לא יקובל תפילתך. אלא כאשר תרצה להתפלל תתפלל על הכבידות שיש בראש, כי הדבר שחסר לך החיסרון יש בשכינה כביכול. כי האדם הוא חלק אלוה ממעל, והחיסרון שיש בחלק יש בכ\"ל [נ\"א בכלל. ונ\"א בכולל], והכ\"ל [נ\"א: והכלל. ונ\"א והכולל] מרגיש החיסרון של החלק. אם כן תהיה תפלתך על החיסרון של הכל [נ\"א: הכלל: ונ\"א: הכולל] והבן זה היטב<sup data-n=\"1\">מח</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, ג (סי' רכד). אוה\"א לט, א. צוה\"ר סי' עג.</b>\n<i>אין עומדין כו'</i> – ברכות ל, ב.<i> שיש בראש</i> – (השכינה) ראה זח\"ג קפז, א.<i> הדבר שחסר לך כו' בשכינה</i> – ראה ישעיה סג, ט. סנהדרין מו, א.<i> חלק אלוה ממעל</i> – איוב לא, ב.<i> בכלל</i> – (השכינה) ראה זח\"ג רלט רע\"א. תקוזו\"ח קב סע\"ד ואילך, ושם קיא, ב.\n----- שולי הגליון -----\n<b>מח</b> ) <i>בלקו\"י מוסיף:</i> וזהו ג\"כ פירוש אל תעש תפילתך קבע וגו'.\n----- הערות וציונים -----\nעיין ריש סי' נו ובהערות שם. ולהעיר שבמאור עינים פ' נשא, ובדמ\"א ר\"פ תשא (ושם ר\"פ בחוקותי ובפ' מטות), מובא זה בשם הרה\"מ. ברם בלקו\"א יז, א כתב: יתפלל כי לא יחסר למעלה כמ\"ש מורי ריב\"ש אין עומדין להתפלל אלא מתוך כובד ראש ר\"ל מה שחסר בראש.\n<i>אין עומדין להתפלל</i> – עיין בלקו\"י ז רע\"ג (סי' קכג) ולכך לא אמרו אין מתפללין כו' רק אמרו אין עומדין רמז להנ\"ל שעיקר עמידת התפלה ומגמתו להשפיע בעליונים כנ\"ל. ולהעיר שגם בצפנת פענח פ' שמות פן ז (ז, ג) דייק בלשון הזה.\n<i>אל תתפלל בשביל כו' כי לא יקובל כו'</i> – בלקו\"י שם: כי לא יענה ואדרבה אפשר יהיה קטרוג ומזכירין עונותיו. ועיי\"ש עוד שמבאר עד\"ז מרז\"ל ג' דברים מזכירין עונותיו של אדם (ר\"ה טז, ב ועיי\"ש ברש\"י ותוס' ובהנסמן שם בתוס' בשוה\"ג, וזח\"א רב, ב). ועייג\"כ כש\"ט סי' קעו וסי' רסח ובהערות שם. ולהעיר עוד מענין תפילת יחיד לעומת תפילת רבים כמבואר בזח\"א קסז סע\"ב ושם רלד, א. שערי אורה להרי\"ג שלהי שער ב (בערך חסד תחתון). ורג\"כ כוזרי מ\"ג סוף סי' יז ושם סי' יט. ורג\"כ לעיל סי' תיח ד\"ה בינונים.\n<i>הכבידות שיש בראש כו'</i> – בלקו\"י שם: מתוך כובד השכינה הנקראת ראש כמ\"ש ושמן על ראשך (קהלת ט, ח) ומפרש בזוהר (זח\"ג קפז, א) שקאי על השכינה שהיא למעלה מראשו של אדם וכו'. ובמאור עינים פ' נשא: מתוך כובד של השכינה שנק' ראש, שבכל צרתם לו צר (ישעי' סג, ט. ראה מכילתא מס' דפסחא ספי\"ד, ושם ס\"פ בשלח מס' דעמלק סוף פ\"ב. זח\"ג רג, ב ושם ריט, ב. וראה הנסמן בהערות לסי' נו ד\"ה כל כוונת), וכמו שארז\"ל (סנהדרין מו, א) בזמן שאדם שרוי בצער שכינה מה אומרת קלני מראשי וכו'. ועיין ריש סי' נו.\n<i>כי הדבר שחסר לך החיסרון יש בשכינה כביכול</i> – במאור עינים שם: כי כל הדברים שהם הצטרכות האדם נק' אברי השכינה כביכול, כגון רפואה פרנסה ושאר דברים, כל דבר הוא אבר מהשכינה, ומה שחסר למטה חסר ג\"כ למעלה כביכול וכו'. ועיין מש\"כ בהערות לסי' נו דברי הבעש\"ט המובאים בדמ\"א. ועיי\"ע כש\"ט סי' שצה-א, ובדברי כ\"ק אדמו\"ר זי\"ע הנסמנים שם בהערות.\n<i>אם כן כו' על החיסרון של הכלל</i> – להעיר ממש\"כ בכוזרי שם.\nבלקו\"י שם סיים ענין זה: וכשיענה בתפלתו ויהיה לה' הישועה יקויים ג\"כ סוף הפסוק על עמך ברכתך סלה. ובמדל\"י סי' נג (סו) [שהוא ג\"כ בענין זה, עיי\"ש היטב]: וכשימשיך אור הבורא ית' במחשבתו ודבורו יהיה בקשתו שיתפשט השפע מעולם המחשבה אל עולם הדיבור ויבוא ג\"כ באותו ענין שהוא מדבר שצריך לו ויעשה לו בקשתו, וזהו המצא לנו בבקשתנו שיהיה הוא ית' נמצא באותן הבקשות. ובמאור עינים שם: ואם יעשה כן ממילא יתוקן למטה ג\"כ. ועיי\"ע במדל\"י סי' קמה (קנג) [שהוא ג\"כ בענין זה]: ואם הוא מתפלל כך, אע\"פ שלא נעשית בקשתו בעולם העשיה מ\"מ לאותו החלק נעשה בקשתו בעולמות עליונים, וזהו אל תבקש גדולה לעצמך, שתהא הגדולה לעצמך, כי זה הוא פניה כו' (השוה לעיל ריש סי' תיח.)"]]],[400080515,"תנא\n\n<b>מעשה</b> בגר אחד שבא לפני שמאי וא\"ל גיירני על מנת שתלמדני כל התורה [כולה] כשאני עומד על רגל אחד, דחפו באמת הבנין וכו'. ויש לפרש על פי מ\"ש רז\"ל לא הגלה הקב\"ה את ישראל אלא להוסיף עליהם גרים. כי הצדיק רוצה להיות במדריגה שלו תמיד, כי הוא רוצה להיות תמיד בפני אדוניו לשרתו. אך מפני מה הוא נופל לפעמים ממדריגתו, כדי לברר ניצוצין שנפלו בקליפות. כמשל המלך ששלח את בנו להביא אליו אוצר שנאבד לו, וציוה להביאה [לו] ממדינה אחרת. א\"כ מוכרח הבן להחליף מלבושיו כדי שלא יכירוהו. וכן עשה, והביא לו את האוצר. ואז הוא עובד יותר למלך בזה מקודם שהיה עומד לפני המלך. והם נקראים גרים כידוע. וזהו הפירוש שאמר הגר שילמוד את כל התורה כשהוא עומד על רגל אחד, ר\"ל על מדריגה והעמדה אחת, דחפוהו באמת הבנין, הוא ז' ימי הבנין. כי בכל אחד יש בוקר וערב, הוא בטוב ורע [נ\"א: וטוב ורע]. א\"כ צריך הצדיק לירד ממדריגתו לפעמים בכדי לברר ניצוצות אלו שנפלו בקליפות. והלל אמר לו מה דעלך סני לחברך לא תעביד. פי' אלו לא נפל הצדיק ממדריגה שלו לא היה [לך] עלייה, [ואם כן מה דעלך סני] לחברך נמי לא תעביד.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טז, ד (סי' ריג). אוה\"א עט, א.</b>\n<i>מעשה בגר אחד כו'</i> – שבת לא, א.<i> לא הגלה הקב\"ה כו'</i> – פסחים פז, ב.<i> והם נקראים גרים</i> – (כלו' הניצוצין) ראה מגלה עמוקות פ' ויחי ד\"ה ויחי יעקב (סג, ד).<i> והלל אמר לו מה כו'</i> – שבת לא, א.\n----- הערות וציונים -----\nעיין לעיל סי' קעה.\n<i>מפני מה הוא נופל לפעמים ממדריגתו כו'</i> – ראה סי' רמח ד\"ה והנה כשהצדיק. וראה סי' שלו. עיין צוה\"ר סי' סד. כש\"ט סי' קלו (ועיי\"ש בהערות). ושם סי' שנו. וראה דמ\"א ר\"פ ויצא: סוד גדלות וקטנות כידוע בשם אא\"ז נ\"ע זללה\"ה כי החיות רצוא ושוב וא\"א לעמוד על מדריגה אחת תמיד רק עולה ויורד והירידה הוא צורך עליה ויודע ומרגיש זה שהוא בקטנות ומתפלל אל ה' ע\"ד ובקשתם משם את ה\"א ומצאת, וזהו משם, ממקום שהוא שם כמו שאמר אא\"ז נ\"ע זללה\"ה וכו'.\n<i>מוכרח הבן להחליף מלבושיו כו'</i> – ראה משל הבעש\"ט בענין כסות ולשון שינה המובא בכש\"ט סי' קמד.\n<i>והם [הניצוצין] נקראים גרים כידוע</i> – ראה כש\"ט סי' קנד. ראה קדושת לוי שה\"ש ד\"ה לריח שמניך: למה ברא השם ית' זה שיפול צדיק ממדריגתו . . דבר זה אמר הבעש\"ט ז\"ל ומורי הצדיק מו' דוב בער זצ\"ל שמזה שנופל הצדיק ממדריגתו ומתחזק לחזור ולשוב לאיתנו מזה נבראו נשמות, והוא כמו מי שרוצה להעלות את חבירו מטיט ורפש שצריך גם הוא לירד סמוך להטיט ורפש להעלות אותו, כמו כן מזה נבראו נשמות גרים ממה שהצדיק נופל ממדריגתו ומתחזק א\"ע לעבוד השי\"ת ולחזור ולשוב אל מקומו עכ\"ד.\n<i>הוא ז' ימי הבנין כי בכל אחד יש כו'</i> – עיין צוה\"ר סי' פז ד\"ה דיש.\n<i>א\"כ צריך הצדיק לירד כו'</i> – ראה סי' שו וסי' תפח."]]],[400080516,"תנב\n\n<b>מפני</b> מה ניתנה התורה לישראל מפני שהם עזים. ויש לדקדק, מפני מה יגרעו ישראל משאר ע' אומות שהקשה מפני מה ניתנה התורה לישראל. ועוד [קשה], הלוא חזר הקב\"ה על כל ע' אומות ולא רצו לקבלה. <i>ותירץ הרב מו\"ה יחיאל מיכל נר\"ו</i> דהכי פירושו. מפני מה וכו', ר\"ל הלוא בלאו הכי היה להם לישראל לקיים [את] כל התורה כמו שקיימו אבותיהם, [שמצינו] שקיים אברהם אבינו ע\"ה אפילו עירוב תבשילין, וכמו כל האבות [נ\"א: וכן אדם ונח ושם שהיו קודם מתן תורה מצינו שקיימו כל התורה]. ועוד, הלא מצד השכל חייב אדם לקיים כל התורה, מפני שהתורה היא קיום ובריאות הנשמה [שהן רמ\"ח מצות עשה נגד רמ\"ח אברי הנשמה, ושס\"ה מצות לא תעשה שבתורה הן נגד שס\"ה גידי הנשמה], וכמו שקיום הגוף הוא המאכל וכיוצא (שאר) [בזה]. ובבריאות הגוף לא היה צריך הקב\"ה ליתן תורה והנהגה על זה האיך ומה קיום בריאות הגוף, מפני שהוא מצד השכל. א\"כ גם התורה לא היה מן הצורך ליתן להם, כי היו מקיימין ג\"כ [את התורה] לקיום הנשמה, [כי התורה היא חיות הנשמה].\n<b>ולזה</b> אמר מפני שהם עזים, ר\"ל שחומר הגוף ויצה\"ר הם מסך מבדיל. לכן הוצרך הש\"י לתת להם תורה (בפרוטרוט) [בפרטות], וע\"י לימודה יקיימו כל התורה כ\"א [מהם].\n<b>(</b><sup data-n=\"1\">מט</sup><b>ועוד</b> נ\"ל פשוט מ\"ש שהם עזים, הוא מדת עזות [נ\"א: ר\"ל מדת איש הישראלי הוא עזות], שעומד נגד היצה\"ר המפתהו לדבר עבירה לעבור על דברי תורה, והם עומדים וכובשים את יצרם, כמ\"ש במדרש או יהודי או צלוב. וזה ידוע כי עיקר עבודת הבורא הוא לכבוש היצה\"ר, ואמרו רז\"ל אינו דומה המצווה ועושה (כו') [ששכרו גדול ממי שאינו מצווה ועושה, ואם לא היה נותן להם התורה לא היו מצווים אף שהיו מקיימים]. לכן ניתן להם התורה ואז הם מצווים, ומצוי היצה\"ר להתגרות בם לבטלם, והם עזים כמדתם וכובשים יצרם, ואז שכרם יהיה משלם. מה שאין כן אם לא היה נותן להם התורה, אז אין היצה\"ר מצוי בהם. וגם אם היה נותן התורה לשאר אומות לא היו יכולים לקיימו [בודאי] כי אין בהם מדת עזות הטובה, וד\"ל.)",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טז, ג (סי' רה). אוה\"א פ, ב.</b>\n<i>מפני מה ניתנה כו'</i> – ביצה כה, ב.<i> חזר הקב\"ה על כו'</i> – ע\"ז ב, ב.<i> שקיים אברהם כו'</i> – יומא כח, ב.<i> וכמו כל האבות [וכן אדם ונח כו']</i> – יומא שם. ויק\"ר ב, י. ראה זח\"א קצט, א ובהג' החיד\"א שם.<i> רמ\"ח אברי הנשמה . . שס\"ה גידי הנשמה</i> – זח\"ג רכב, ב. שערי קדושה ח\"א ש\"א. לקו\"ת להאריז\"ל ר\"פ שמות. שעה\"מ, הקדמה.<i> שהתורה הוא קיום ובריאות הנשמה</i> – ראה זח\"ג רכז סע\"א. זו\"ח רות עז, ד.<i> או יהודי או צלוב</i> – שמ\"ר מב, ט.<i> אינו דומה מצווה ועושה כו'</i> – קידושין לא, א.\n----- שולי הגליון -----\n<b>מט</b> ) <i>במקבילות אין סוגריים.</i>\n----- הערות וציונים -----\n<i>ותירץ הרב כו'</i> – עד\"ז איתא ג\"כ בקדושת לוי, לקוטים ד\"ה איתא במדרש בשעה שעלה משה רבינו ע\"ה.\n<i>ועוד נ\"ל פשוט כו'</i> – להעיר ממדת עזות הטובה דאיתא באבות פ\"ה מ\"כ, עיין פי' המהר\"ל שם בס' דרך חיים, ומג\"ע פ' אמור ד\"ה אמור אל הכהנים."]]],[400080517,"תנג\n\n<b>כל</b> העוסק בתורה לשמה זוכה לדברים הרבה. פי' כי כמו ששמה תורה, שהוא לשון מורה דרך אשר ילך בה האדם. זוכה לדברים הרבה, ר\"ל כמו שהתורה היא א\"ס, כי אורייתא וקב\"ה חד הוא, כן זוכה [לדברים הרבה], לדברי עמקיות התורה, תמיד בלי הפסק [כמעין הנובע].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טז, א (סי' רא). אוה\"א פא, א.</b>\n<i>כל העוסק בתורה לשמה כו'</i> – אבות פ\"ו מ\"א.<i> תורה שהוא לשון מורה כו'</i> – זח\"ג נג, ב.<i> אורייתא וקב\"ה חד הוא</i> – זח\"א כד, א. זח\"ב ס סע\"א. שם צ, ב.\n----- הערות וציונים -----\n<i>לדברי עמקיות התורה כו' כמעין הנובע</i> – כדאיתא שם במשנה ומגלין לו רזי תורה ונעשה כמעין המתגבר כו'."]]],[400080518,"תנד\n\n<b>עשה</b> רצונו כרצונך. פירוש שתלך בדרכי ה' ותזכה למשול כביכול ברצון הבורא יתברך, כמ\"ש צדיק מושל ביראת אלהים, ותעשה רצונו כרצונך, דהיינו רצון הבורא כרצונך כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טו, ד (סי' קצז). אוה\"א פא, ב.</b>\n<i>עשה רצונו כרצונך</i> – אבות פ\"ב מ\"ד.<i> צדיק מושל גו'</i> – ש\"ב כג, ג. מו\"ק טז, ב.\n----- הערות וציונים -----\nראה סי' ס סד\"ה והנה נמשיל, ובהערות שם."]]],[400080519,"תנה\n\n<b>ת\"ר</b> שעה ראשונה מאכל לודים שניה מאכל ליסטים שלישית מאכל יורשים רביעית מאכל פועלים חמישית מאכל כל אדם ששית מאכל ת\"ח. ונ\"ל ע\"פ רמז והלצה שרמזו על אכילת אדם, שיש כמה מיני סוגי אכילות שונות זו מזו. המובחר שבכולם הוא אכילת הצדיק, שהוא אוכל לשובע נפשו ומספיק א\"ע במועט. ולא עוד, אלא שכל העולם ניזון בזכותו, כרבי חנינא בן דוסא וכיוצא. והב' שאין כח זכותו כל כך לזון אחרים, רק הוא בעצמו ניזון מפירות מעשיו בעולם הזה. והגרוע מזה הוא מין הג', שגם הוא ניזון בזכות מעשיו, אבל עבודתו גרוע שהוא עובד על מנת לקבל פרס בעוה\"ז. והד' הוא גרוע יותר, שאין לו זכות כלל מפאת עצמו, רק שהוא ניזון בזכות אבותיו. והה' הוא גרוע עוד יותר, שאין לו זכות עצמו ולא זכות אבות, רק הוא ניזון בזכות הצדיקים שבדורו. והוא גרוע מן הראשונים, כי לא די שאין לו זכות במה להתפרנס, אלא שגם בעבורו יוגרע כח שפע הצדיקים שבדורו, כמ\"ש בגמרא דייך דמגינת אכולא כרכא דמחוזא. והסוג הו' הוא גרוע מכולם, שהוא חוטא גדול, ובעבור חטאיו נמנע השפע מכל העולם כמ\"ש זבובי מות [יבאיש] יביע וגו', [פי'] חטא אחד יאבד טובות הרבה, כמו בעלי לשון הרע, כמ\"ש רז\"ל מיעוטן בגזל ורובן בלשון הרע<sup data-n=\"1\">נ</sup>, והוא נרגן מפריד אלוף, אלופו של עולם, ומונע השפע, ורבו הרעות רחמנא ליצלן.\n<b>ואפשר</b> שזהו הרמז שרמזו בברייתא הנזכרת. שע\"ה הא', פי' שע\"ה מלשון הסר\"ה, שסר (מצרכי) [מדרכי] השי\"ת. שע\"ה ראשונה, כלומר סרה הגרוע מכולם, הוא בעלי לשון הרע וכיוצא, שמונע השפע מכל וכל ומאבד טובות הרבה, וגורם צרות רבות בעולם. והוא כמו הלודים שאוכלים בשר אדם. וגם נקראים שעה<sup data-n=\"2\">נא</sup>. הב' הוא הניזון בזכות הצדיקים שבדורו. ואף שאינו מונע השפע, שלא הרשיע כל כך, מ\"מ ממעט שפע הצדיקים. וזהו מאכל לסטים. ג' הוא האוכל בזכות אבותיו, וזהו מאכל יורשים. הד' הוא העובד על מנת לקבל פרס, וזהו מאכל פועלים, ר\"ל שעובדים ע\"מ ליקח שכר פעולתם בעוה\"ז. הה' הוא מאכל כל אדם, ר\"ל הוא מדת אדם בינוני, שהוא צדיק לעצמו ואוכל מפירות מעשיו, ואינו מפרנס לאחרים כי זכותו אין כ\"כ גדול. אבל מאכל ת\"ח הנקראים בנים, המקיימים בזכותם כל העולם, וזהו שעה ששית, ר\"ל שהוא תמיד שעה<sup data-n=\"3\">נב</sup> בה' אלהיו ושמח בחלקו, והוא לשון ששי\"ת. וז\"ש ודורשי ה' לא יחסרו כל טוב, פי' למה דורשי ה' לא יחסרו, כי הכל הוא טוב בעיניו ומספיק את עצמו במועט, ובזכותו ניזון כל העולם כולו כנזכר<sup data-n=\"4\">נג</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א צז, א. [</b><i>שע\"ה הא' פי' כו'</i><b>: במדל\"י סי' רו (רטז) בקיצור ושנויים.]</b>\n<i>ת\"ר שעה ראשונה כו'</i> – שבת י, א.<i> הצדיק . . אוכל לשובע נפשו</i> – ע\"פ משלי יג, כה.<i> שכל העולם כו' כרבי חנינא בן דוסא</i> – ברכות יז, ב.<i> עובד על מנת לקבל פרס</i> – ע\"פ אבות פ\"א מ\"ג.<i> כמ\"ש בגמרא דייך כו'</i> – תענית כב, א.<i> זבובי מוח גו'</i> – קהלת י, א.<i> חטא אחד גו'</i> – קהלת ט, יח.<i> מיעוטן בגזל כו'</i> – ב\"ב קסה, ב.<i> נרגן מפריד אלוף</i> – משלי טז, כח.<i> אלוף אלופו של עולם</i> – זח\"ג טז, ב. שם לא, א.<i> שע\"ה מלשון הסר\"ה</i> – ע\"פ ישעיה ו, י. תהלים לט, יד.<i> הלודים שאוכלים כו'</i> – פרש\"י שבת י, א ד\"ה לודים.<i> תלמידי חכמים הנקראים בנים</i> – ראה ברכות סד סע\"א.<i> ושמח בחלקו</i> – ע\"פ אבות פ\"ב מ\"א.<i> ודורשי ה' גו'</i> – תהלים לד, יא.\n----- שולי הגליון -----\n<b>נ</b> ) <i>לשון הגמרא: רוב בגזל כו' והכל בלשון הרע . . אבק לשון הרע</i>.\n<b>נא</b> ) <i>ליכא באוה\"א, וכונתו צ\"ע. ואולי ע\"פ הנ\"ל שעה מלשון הסרה שסר מדרכי השי\"ת</i>.\n<b>נב</b> ) <i>מלשון וישע ה' אל הבל ואל מנחתו (בראשית ד, ד)</i>.\n<b>נג</b> ) <i>גירסת המדל\"י:</i> תנו רבנן שעה ראשונה מאכל לודים. שעה לשון הפרשה, כמו אל מנחתו לא שעה. ושעה ראשונה פי' סיבה ראשונה שאדם מופרש מהש\"י. מאכל לודים, פירש\"י אוכלי אדם, היינו מי שיש לו מדת לשון הרע, כדאמרינן לישנא תליתאה. שניה <i>(צ\"ל שלישית)</i> מאכל יורשים, שאין עושים מעשים טובים רק סומכין על זכות אבות. שלישית <i>(צ\"ל רביעית)</i> מאכל פועלים, שעובדים על מנת לקבל פרס. רביעית <i>(צ\"ל חמישית)</i> מאכל כל אדם, היינו שאוכלים מאכל של אדם הצדיק הנקרא כל, כההיא דר' חנינא בן דוסא. שכל אלו נעתקים ומופרשים מהש\"י מלעשות עובדות בשלימות. <i>וחסר כאן ביאור שניה מאכל לסטים, וגם לא פירש ששית מאכל ת\"ח</i>.\n----- הערות וציונים -----\n<i>בעלי לשון הרע כו' שאוכלים בשר אדם</i> – במדל\"י (ראה בפנים בשוה\"ג) ציין על זה לערכין טו, ב. ורג\"כ תנחומא מצורע ב ודב\"ר ה, י.\n<i>והוא לשון ששי\"ת</i> – נראה דר\"ל מלשון שוש אשיש."]]],[400080520,"תנו\n\n<b>גדולה</b> תשובה שמגעת עד כסא הכבוד שנאמר שובה ישראל עד ה' אלהיך. ויובן על פי מ\"ש בספר יצירה עולם שנה נפש. פירוש, שיש בכל הנבראים עולם שנה נפש, וגם בהאדם יש עולם שנה נפש ג\"כ. והנה מוכרח שיש ג\"כ באדם ימים, כמ\"ש ואברהם זקן בא בימים. והנה אית תרי גווני יומי, דהיינו יום א' מורה כשהאדם עוסק בעבודת השי\"ת שהוא או\"ר הנקרא יו\"ם, ויום ב' הוא כשעוסק בדברי (השטות) [הרשות] שהם צרכיו. אך מי שהוא צדיק מקיים בכל דרכיך דעהו, ר\"ל שהצדיק עושה חולין שהם דברי הרשות על טהרת הקודש, שכל מעשיו הם לשם שמים, ומעלה הכל אותם אל הקדושה. וזהו ואברהם זקן וגו', זה שקנה חכמה, מפני שבא בימי\"ם, פירוש שעשה ב' הימים קודש, שניהם כאחד קדושים, לכך זכה למדריגה עליונה. ואפשר לומר שזהו רמז הפסוק ימים יוצרו ול\"א אחד בהם. הקרי ל\"ו בו', ר\"ל ימים אשר יוצרו באדם, ומיעוט ימי\"ם שנים. והנה מהב' ימים אין להקב\"ה רק אחד מהם כנזכר. וז\"ש ולי מה יקרו רעיך א\"ל [מה] עצמו ראשיהם, שהוא מדבר ממדת הצדיקים. ולכן ולי מה יקרו רעיך [אל], שעשית ב' הימים שניהם קודש, כמ\"ש והמלך דוד זקן בא בימי\"ם, וכן שאר הצדיקים העושים כך, מה עצמו ראשיהם וגו'. ואפשר שגם זה רמזו בגמרא למאיר ובא קראו יום, ר\"ל שהצדיק מאיר גם את יום הב' וקורא אותו יום ומקדשו.\n<b>ואפשר</b> שז\"ש בגמרא אמרו על שמאי הזקן שכל ימיו היה אוכל לכבוד שבת וכו', אבל הלל הזקן מדה אחרת היתה בו שכל מעשיו היו לשם שמים שנאמר ברוך ה' יום יום. והנה דחקו המפרשים במאי פליגי, וע\"פ הנזכר יובן. כי הנה יש לדקדק למה קורא אותם כאן זקנים, שמאי הזקן והלל הזקן. אבל זה רמזו כי שניהם באים בימים, דהיינו בב' הימים, כמו אברהם ודוד, וזכו למדת הזקנה. אך זהו החילוק שביניהם. שמאי היה מהדר שתהיה אכילתו לשם [מצות] קדושת שבת. כיצד, מצא בהמה נאה אומר זו לשבת ואח\"כ מצא וכו', שאע\"פ שאוכלה בחול כוונתו היה לשם מצוה כאשר מצא אחרת נאה ממנה. נמצא כי גם הוא עבד את הבורא יתברך בב' הימים, כי כל אכילתו היתה לשם מצוה. ומסתמא גם שאר (מצות) עובדות הרשות היה מכניסם לעשותם מדבר הרשות מצוה. לכך נקרא זקן כמדת אברהם. אבל הלל אמר אדרבא שזה יותר טוב להעלות החולין אל טהרת הקודש, ובזה יעשה ב' הימים קודש, אבל מי שינהיג כמו שמאי, שעשה מרשות מצוה, נמצא כי הכל הוא נחשב ליום אחד. וז\"ש שכל מעשיו היו לשם שמים, רצה לומר אפילו דברי הרשות היו לשם שמים להכניסם בקדושה. לכך אמר ברוך ה' יו\"ם יו\"ם, ר\"ל בב' הימים צריך האדם לעובדו ולברכו ולגדל ולקדש שמו הגדול יתברך. וזהו מעלה גדולה ויתירה שמעלה הכל אל הקדושה כנזכר, ופשיטא שזכה למדת הזקנה.\n<b>ונחזור</b> לענין גדולה תשובה וכו' שנאמר שובה וגו'. ויש לדקדק למה דרשו זה על פסוק הנאמר בנביאים, והלוא בתורה נאמר ג\"כ ושבת ע\"ד ה' אלהי\"ך, והוי ליה לדרוש זה על פסוק הנאמר בתורה. וי\"ל על פי מ\"ש רז\"ל צורתו של יעקב אבינו ע\"ה חקוקה בכסא הכבוד, שהוא תפארת ישראל שנאמר ישראל אשר בך אתפאר. והנה אמרו רז\"ל העושה תשובה [מאהבה] זדונות נעשו [לו] כזכיות. ואפשר לומר שזה רמז הפסוק נושא עון ועובר על פשע, ר\"ל מי שעושה תשובה [מאהבה] נמצא שהוא נושא עון, פירוש שהוא מנשא [העון] ומנטל ומגביהו למעלה למעלה שנעשה ממנו זכיות, ממילא גורם ומעורר האהבה עליונה שהוא החסד. וידוע כי מדת הת\"ת הוא מטה כלפי חסד. ובעשותו תשובה מאהבה ונושא העון לזכיות, מעורר מאוד התגברות החסד ואהבה עזה (ותפארת) [והתפארות] גדולה לתפארת ישראל. וכתיב [נ\"א: וזהו] ותפארתו עבור על פשע, נמצא ממילא מעבירין על כל פשעיו.\n<b>ומה</b><sup data-n=\"1\">נד</sup> שזה הדבר גורם דווקא הבעל תשובה ולא הצדיק מעיקרא, הוא משל למלך שהיה לו ב' בנים. האחד הוא בתמידות אצל אביו ולא זז ממנו, והב' לא הקביל פני המלך אביו כי אם לפרקים, פעם אחת בשבוע, ומה גם אחר שנתרחק מאביו הלך שובב, ושכח מכל גדולת אביו ורוממותו וגודל האהבה והגיעגועין שהיה לאביו עליו. ולא שם אל לבו כל זה, ומרד במלך ופורק א\"ע מעול יראת [אביו] המלך ואדנותו, וילך בדרכי לבו, ויתחבר אל אנשים פוחזים וריקים אנשי בליעל וליסטים. ויהי כשמוע המלך, ויחר וירע לו מאוד. והנה היה ביד המלך לשלוח גייס אחריו ולתופסו, ולעונשו ולשלם לו כפרי מעלליו, אך מחמת גודל רחמי האב על הבן הזניח הדבר. רק כאשר בא פעם על זכרונו, המו מעיו עליו ונתעורר רחמנותו, ואומר עליו אוי לזה מאיזה שלוה גלה ונתרחק ממקום חיותו, אוי לבן שעל שלחן אב אינו.\n<b>ויהי</b> היום ונתחרט הבן השובב, ונזכר גודל האהבה שהיתה בינו ובין אביו. ושם אל לבו לשוב אל אביו להתנפל ולהתחנן לו ולהשתטח לפני הדום רגלי אביו ולבקש ממנו, וכך עשה. ובא אל אביו בתחנונים ובפיוסים גדולים וברצוים, לאמור אנכי חטאתי, הסכלתי עשו, ואחר שובי נחמתי וכו'. והנה המלך כאשר ראה אותו מתחנן ומתנפל כך ומבקש ממנו, נתמלא עליו רחמים, ומה גם שהוא היה כמעט מיאש ממנו. וכעת שראה המלך שעזב דרכו הסורר ולבו השובב, וחזר למוטב מחמת אהבת אביו המלך, נתמלא המלך שמחה גדולה ותענוג גדול והתפארות גדולה עד אין קץ. וניתוסף בהמלך רחמים על רחמנותו ואהבה על אהבתו, ויותר מאהבה שאהב את הבן הא' שהיה תמיד אצלו, מפני שהיה מורגל עמו ולא היה האהבה כ\"כ מוחש. ולא כן זה הב' שבא אל המלך, ממנו השמחה והאהבה פתאומיות, וראה זה דבר חדש הוא. ומחמת זה העביר על כל פשעיו ומרדיו, וגידלו המלך וינשאהו מכל בניו.\n<b>וכן</b> הנמשל. כי הרשע העובר עבירות הוא כמו שעבר מאת פני המלך מלכי המלכים הקב\"ה, כי העביר\"ה כמשמעה, ובשובו עושה התפארות גדולה למעלה.\n<b>וז\"ש</b> ע\"ד ה' אלהי\"ך, כי ע\"ד לשון עד\"י וקישוט, פירוש, תשובה מאהבה, כדי שיהיה עד\"י וקישוט והתפארות למדת תפארת ישראל החקוקה צורתו בכסא הכבוד. ולכך דרשו רז\"ל דווקא על הפסוק שבנביאים, מפני שכאן נאמר שובה ישרא\"ל, שהוא רומז על הנזכר, לעשות עדי וקישוט לתפארת ישראל. מה שאין כן בפסוק שבתורה לא כתיב ישראל. וכל זה אם עושה תשובה מאהבה כנזכר. לכך אמר נמי גדולה תשובה, כי ידוע שמדת גדולה נתייחסה למדת חסד שהיא אהבה. ואפשר כי מלת כסא הכבוד רומז אל מ\"ש רז\"ל תשוב\"ה היא אותיות תשו\"ב ה', פי' שהוא משיב ה' אחרונה של שם הוי\"ה למקומה ויהיה השם מלא. והנה אמרו רז\"ל למה נמשלה התפילה לעתר, מפני שמהפכת מדת הדין למדת הרחמים. וידוע כי שם אלהי\"ם הוא דין. והנה הבעל תשובה כשהוא משיב ה' אל הוי\"ה, כביכול שמהפך אות הה' מתיבת אלהי\"ם, שהוא עיקר הדין של אלהי\"ם כמ\"ש בכתבי האר\"י זלה\"ה בכוונת בני אלי\"ם, הוא מהפך אל הוי\"ה שהוא רחמים גמורים. ונמצא [כאשר] תקח אות ה' מאלהי\"ם נשאר אלי\"ם, שמספרו פ\"א שהוא גימטריא כס\"א, ונשאר גם הוא רחמים, וגם כבוד, שגורם שיתמלא השם ויגבר הרחמים בעולם.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רנו (רסד). אוה\"א פד, ב.</b>\n<i>גדולה תשובה כו'</i> – יומא פו, א.<i> שובה ישראל גו'</i> – הושע יד, ב.<i> בספר יצירה</i> – פ\"ג מ\"ה.<i> ואברהם זקן גו'</i> – חיי שרה כד, א.<i> או\"ר הנקרא יו\"ם</i> – בראשית א, ה.<i> בכל דרכיך דעהו</i> – משלי ג, ו.<i> חולין . . על טהרת הקודש</i> – ע\"פ חגיגה יט סע\"ב.<i> שכל מעשיו הם לשם שמים</i> – ע\"פ אבות פ\"ב מי\"ב.<i> זקן . . זה שקנה חכמה</i> – קידושין לב, א.<i> ימים יוצרו גו'</i> – תהלים קלט, טז.<i> ולי מה יקרו גו'</i> – תהלים קלט, יז.<i> והמלך דוד זקן גו'</i> – מ\"א א, א.<i> למאיר ובא קראו יום</i> – פסחים ב, א.<i> אמרו על שמאי הזקן כו' אבל הלל כו'</i> – ביצה טז, א.<i> ברוך ה' יום יום</i> – תהלים סח, כ.<i> כיצד מצא בהמה נאה כו'</i> – ביצה שם.<i> ושבת ע\"ד ה' אלקי\"ך</i> – ואתחנן ד, ל.<i> צורתו של יעקב אבינו ע\"ה כו'</i> – בר\"ר פב, ב. ת\"י בראשית כח, יב. תקו\"ז תכ\"ב סה, ב. חולין צא, ב.<i> שהוא תפארת ישראל</i> – זח\"א קעב, ב.<i> ישראל אשר בך אתפאר</i> – ישעיה מט, ג.<i> העושה תשובה מאהבה כו'</i> – יומא פו, ב.<i> נושא עון ועובר על פשע</i> – מיכה ז, יח.<i> האהבה עליונה שהוא החסד</i> – ראה זח\"ב מב, ב.<i> מדת התפארת הוא מטה כלפי חסד</i> – פרדס רמונים ש\"א רפ\"ב. שם ש\"ח פכ\"א. ש\"ט פ\"ב וספ\"ד. שער מאמרי רשב\"י פ' תרומה בסוף ביאור דף קסו, ב. שם בפי' האדר\"ז בד\"ה ונבאר ענין הרצועות במוחין (רעז, א). לקו\"ת פ' שמות ד\"ה ותקרא שמו משה. שער הפסוקים פ' שמות ד\"ה ויקם.<i> ותפארתו עבר על פשע</i> – משלי יט, יא.<i> ע\"ד לשון עד\"י וקישוט</i> – ראה כי תשא לג, ד.<i> שמדת גדולה נתייחסה למדת חסד</i> – זח\"ג שב, א.<i> תשוב\"ה היא אותיות תשו\"ב ה'</i> – זח\"ג קכב, א.<i> למה נמשלה התפלה לעתר כו'</i> – סוכה יד, א.<i> שם אלקי\"ם הוא דין</i> – ספרי ואתחנן פי' כו. זח\"ג יא, א. שם סה, א.<i> כמ\"ש בכתבי האר\"י זלה\"ה כו'</i> – פע\"ח שער השבת פ\"ח.<i> הוי\"ה שהוא רחמים</i> – ספרי שם. זח\"ג שם.<i> כס\"א . . כבוד</i> – ראה פרדס רמונים שכ\"ג פ\"כ ערך כסא. קהלת יעקב ערך כסא כבוד.\n----- שולי הגליון -----\n<b>נד</b> ) <i>מכאן עד</i> וז\"ש ע\"ד ה'<i> נ\"א במדל\"י (ואין שם המשל המובא כאן):</i> ודבר זה בא על ידי הבעל תשובה יותר מן הצדיק דמעיקרא. כי על ידי הצדיק מעיקרא יש למעלה תענוג תמידי, ועל ידי הבעל תשובה מחמת שהתענוג בא אחר היאוש והוי כמציאת אבידה גדולה, ויש מזה תענוג גדול עד מאוד. ומה גם שהבעל תשובה צריך להתחזק עצמו יותר ויותר בעבודת הבורא, כמ\"ש רז\"ל אל תקרי ויעתר אלא ויחתר מלמד שחתר חתירה כו'. ואם כן הוא עושה התפארות גדולה למעלה.\n----- הערות וציונים -----\n<i>שהצדיק עושה חולין . . על טהרת הקודש</i> – עיין מאור עינים שלהי פ' בשלח ד\"ה ומורי: ומורי היה מרגלא בפומיה לקרות זה חולין שנעשו על טהרת הקודש כי אפילו בדבר הנראה חול יעשה על טהרת הקודש, כי בכל דבר יש תורה, למשל באכילה כמה תורה ודרכים יש בה, וכמה דינים בנטילת ידים, וכן במשא ומתן, ואמר מורי שחיות הדברים ההם הם מהתורה ודינים ההם שיש בהם ואורייתא וקב\"ה חד כי הכל יש לו אחיזה בהתורה אפי' בריה קטנה. ולהעיר שענין זה כבר הובא בד\"ט בשל\"ה (ועיי\"ש בסוף הקדמת פרק בעשרה מאמרות, ושם: קדושת הלב בכל הדרכים לא מבעיא בטהרת הקודש אלא אף חולין נעשין על טה\"ק כענין שכתב הרמב\"ם [הלכות דעות פ\"ג], זה מאמר השמיני כו' [ועיי\"ש בסוף מאמר השמיני]). ועיין לעיל סי' תל ובהערות שם.\n<i>נושא עון פירוש שהוא מנשא העון כו'</i> – ראה סי' קז סד\"ה או ידע, ובהערות שם.\n<i>הוא משל למלך כו'</i> – ראה סי' קצא סד\"ה אשכול, וסי' שלב.\n<i>כי העביר\"ה כמשמעה</i> – ראה סי' מד סד\"ה ובמקום. סי' שסג סד\"ה והנה."]]],[400080521,"תנז\n\n<b>אשריך</b> כלים שנכנסת בטומאה ויצאת בטהרה. והוא תיקון שבירת הכלים.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כא, א. כתבי קודש לא, א [ושם לה, ב].</b>\n<i>אשריך כלים כו'</i> – כלים פ\"ל מ\"ד.\n----- הערות וציונים -----\nבכתבי קודש לה, ב: אשריך כלים . . שנכנסת בטומאה בסוד השבירה ויצאת בטהרה בסוד התיקון.\nבספר אבן הרא\"ש – לקוטי מילי דאגדתא להרה\"ק מוהרא\"ש הכהן מאוסטרהא, תלמיד הרה\"מ ובעה\"מ ס' וצוה הכהן, ירושלים תשכ\"א ע' כט, א: ואמר הוא [הרה\"מ] ז\"ל עפ\"י המבואר בכתבים שהקב\"ה היה בונה עולמות ומחריבן, דהיינו קודם הצמצום היה ההשפעה מהא\"ס ב\"ה להעולמות בשפע ונתבטלו והיה שבירת הכלים, ומהניצוצות הקדושה שנפלו יש אחיזה להחיצונים, ואחר זה היה תיקון והתיקון נעשה ע\"י תו\"מ, ולעתיד שיהיה כל הארץ מלאה דעה ויהיה התיקון שלם לגמרי ואז יתפרדו כל פועלי און ויבולע המות לנצח, וכל זה מבואר בכתבים. והנה דרשו חז\"ל וחושך על פני תהום זה מלאך המות [תנחומא וישב ד] הוא השטן הוא הנחש הוא היצה\"ר [ב\"ב טז, א] והוא שורש לכל הטומאות והחיצוניות ורמוז בתחילת התורה. והתיקון רמוז בסוף התורה דהיינו ולכל היד החזקה אשר עשה משה לעיני כל ישראל דהיינו קבלת התורה. וזהו שאמר אשריך כלים כו', כי וחוש\"ך ע\"ל פנ\"י תהו\"ם ס\"ת כלים (ושם מרומז יניקת החיצונים כי יש להם אחיזה מהסוף כנודע) ובפסוק ולכל היד החזקה נרמז דתיבות מ'שה ל'עיני כ'ל י'שראל ר\"ת כלים (והוא בראש התיבות כי נרמז לעולם התיקון). וז\"ש אשריך כלים שנכנסת בטומאה, דהיינו בפסוק וחושך על פני תהום שרמז על שבירת הכלים אשר מזה יניקת הטומאה, ויצאת בטהרה, שרמוז תיבת כלים בקבלת התורה שהוא התיקון, ודפח\"ח.\nוראה לקו\"א נג, א: אשריך כלים כו' הם המדות, אע\"פ שעומדות בטומאה ביצה\"ר יצאו בטהרה והשקר בטל וכו'. ושם בסוף אותו עמוד: אשריך כלים שנכנסת בטומאה ויצאת בטהרה, פי' כלים היינו מדות ועבודות של אדם, שמתחלה הן אבות הטומאה מפני שנמשך אחר היצה\"ר וקליפות, וכשחוזר לבסוף ועושה עובדות בלי שום טומאת יצה\"ר כלל ומתקן ג\"כ חטאת נעורים הוא יוצא בטהרה ואשרי לו."]]],[400080522,"תנח\n\n<b>איזהו</b> חכם הרואה את הנולד. ר\"ל כמו שהבנאי קודם בנותו את הבנין מחשב מחשבה לדחות המניעות מהמעשה, ואם בהמעשה יש צמצום היה צריך להיות הצמצום במחשבה כדי לגמור הדבר בתיקונו, ע\"ד סוף מעשה במחשבה תחילה. והבנאי אם רוצה לעשות הבנין יש לו תחילה ציור במחשבה גוף הבנין ולא הפסולת, דהיינו הזיזים מהמעצד. ובהמעשה בא ממילא הפסולת, אע\"פ שזה אינה עיקר במחשבה רק הבנין גופא והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כא, א. כתבי קודש לא, א.</b>\n<i>איזהו חכם הרואה את הנולד</i> – תמיד לב, א.<i> סוף מעשה כו'</i> – פזמון לכה דודי. ראה זח\"ג רלח סע\"א. תקו\"ז ו, א.\n----- הערות וציונים -----\nלהעיר מסי' קנב."]]],[400080523,"תנט\n\n<sup data-n=\"1\">נה</sup><b>כיצד</b> מרקדין לפני הכלה. היינו כיצד יכולים [נ\"א: כיצד יש העזה] לרקוד לפני השכינה, כי הלוא מלא כל הארץ כבודו.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כא, ב. כתבי קודש ל, א.</b>\n<i>כיצד מרקדין כו'</i> – כתובות טז, ב.<i> הכלה . . השכינה</i> – זח\"ב ה, ב.\n----- שולי הגליון -----\n<b>נה</b> ) <i>בכתבי קודש:</i> בשם הבע\"ש.\n----- הערות וציונים -----\nראה כש\"ט סי' קעט, והובא בקיצור בצפנת פענח פ' שמות פן ז' (ז, ג) ואח\"כ ממשיך שם: אם יכול לטהר מחשבתו ולברר ניצוצין דרך פרט, ואם לאו עכ\"פ ידע דרך כלל שהש\"י מלא כל הארץ כבודו וכל תנועה ומחשבה הכל ממנו ית' . . בידיעה זו יתפרדו כל פועלי און ובזה יכול לעמוד על עמדו וכו'."]]],[400080524,"תס\n\n<b>ארבעה</b> אבות נזיקין השור והבור המבעה וההבער. השו\"ר לשון הבטה, כמו אשורנו ולא עתה, והוא לשון הסתכלות, וזה הראיה מזיק לבני אדם. והבו\"ר לשון שדה בו\"ר שאינה חרושה וזרועה, והוא שאינו לומד תורה אלא הולך בטל. המבע\"ה הוא שן, ר\"ל האכילה גסה [נ\"א: שאוכל כל דבר]. וההבער זה הכעס, שהוא הרתחת האש.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כב, א. כתבי קודש ל, ג. צוה\"ר סי' קכא.</b>\n<i>ארבעה אבות נזיקין כו'</i> – ב\"ק ב, א.<i> אשורנו גו'</i> – בלק כד, יז.<i> שדה בו\"ר</i> – ב\"מ קד, א ופרש\"י שם.<i> המבע\"ה הוא שן</i> – ב\"ק ב, ב ופרש\"י שם.\n----- הערות וציונים -----\nהובא בתפארת עוזיאל, הוויות אביי ורבא, בשנויים קלים: דד' מיתות גרועין יש שמזיקין לאדם, השור הוא ההסתכלות בדברים שאינם ראוים להסתכל, והבור הוא פנוי – יש אדם הולך בטל ופנוי מתורה ומצוות ומחשבות קדושות, והמבעה הוא השן כדאיתא בגמרא והיינו המותרות אכילה, וההבער הוא האש של כעס.\n<i>ארבעה אבות נזיקין</i> – להעיר מזח\"ב קיח, א עיי\"ש.\n<i>וזה הראיה מזיק לבני אדם</i> – עיין צוה\"ר סי' ה. ועיי\"ע שם סי' נ ובהערות שם. ועיין זבים פ\"ב מ\"ב ומש\"כ על זה באגרות קודש כ\"ק אדמו\"ר זי\"ע ח\"כ סוף ע' פב (ובלקו\"ש ח\"ז ע' 314).\n<i>והבו\"ר כו' שאינו לומד כו'</i> – להעיר מלשון אבות פ\"ב מ\"ה אין בור ירא חטא. וראה ריש סי' תסב. ועיין צוה\"ר סי' כט.\n<i>המבע\"ה כו'</i> – להעיר מברכות לב, א מלי כריסי זיני בישי כו', ועוד עד\"ז. וראה לעיל סוף סי' תמח. מדבר קדמות להחיד\"א מערכת א אות נח – נט.\n<i>וההבער כו'</i> – ראה ביאורי הזוהר לאדמו\"ר הצ\"צ ע' קפב. אוה\"ת פ' בשלח ע' תנד."]]],[400080525,"תסא\n\n<b>מפני</b> מה יש צדיק וטוב לו וצדיק ורע לו. פי' מפני מה יש צדיק שצריך עבודה גדולה לשבור רוע מדותיו, ויש צדיק שאינו צריך עבודה גדולה. ומשני צדיק בן צדיק, [פי'] יש להבן כמה טבעים שוה אל האב<sup data-n=\"1\">נו</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כב, ב. כתבי קודש ל, ג. שמועה טובה סה, ב.</b>\n<i>מפני מה יש צדיק כו'</i> – ברכות ז, א.<i> יש להבן כמה טבעים כו'</i> – ראה עדיות פ\"ב מ\"ט. וראה ספר החינוך סי' תצח.\n----- שולי הגליון -----\n<b>נו</b> ) <i>בכתבי קודש:</i> טבעו נמשך מאב. אף שיש לו בחירה, עם כל זה בכמה טבעות (שיש) [שוה] לאב וד\"ל."]]],[400080526,"תסב\n\n<b>רבי</b> אומר איזהו דרך ישרה שיבור לו האדם וכו'. פירוש איזה דרך ישרה, מאיזה מדות ימנע עצמו ממנו, שיבו\"ר, לשון ריקות<sup data-n=\"1\">נז</sup>. ועל זה אמר כל שהיא תפארת לעושיה, ר\"ל שעושה המצוה בסתר ואין אדם יודע ממנה, אבל אם הוא סובר במחשבתו שעובד את השם ואצלו הוא התפארות, וכ\"ש שתפארת לו מן האדם, ר\"ל שעושה המצות לקבל התפארות מן האדם, ר\"ל שיאמרו עליו שזה ירא אלהים, מכל זה ימנע את עצמו.\n<b>ואם</b> תעשה זה<sup data-n=\"2\">נח</sup>, אז והוי זהיר במצוה קלה כבחמורה, שאז אין אתה יודע שכרן של מצות, אלא תעשה שיהיה נחת רוח לבורא יתברך בלי שום תשלום גמול מלקבל התפארות. שאם תרצה לקבל התפארות תדקדק במצוה אם היא קלה, שאם היא חמורה תקבל התפארות ותעשה אותה, ואם היא קלה לא תעשה אותה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כב, ב. כתבי קודש ה, ד ושם ל, ד. צוה\"ר סי' קכב.</b>\n<i>רבי אומר איזהו דרך כו' כל שהיא כו'</i> – אבות פ\"ב מ\"א.<i> שיבו\"ר לשון ריקות</i> – ראה ב\"מ קד, א וברש\"י שם.\n----- שולי הגליון -----\n<b>נז</b> ) <i>בכתבי קודש:</i> שיעשה אותה כמו שדה בור וימנע ממנו.\n<b>נח</b> ) <i>מכאן ואילך כמה שנויי סגנון בכתבי קודש</i>.\n----- הערות וציונים -----\n<i>שיבו\"ר לשון ריקות</i> – ראה סי' תס.\n<i>שעושה המצוה בסתר כו'</i> – ראה צוה\"ר סי' סה. ורג\"כ לעיל סי' תיא.\n<i>מכל זה ימנע את עצמו</i> – עיין תוספות פסחים נ, ב ד\"ה וכאן. ועיין מש\"כ בצוה\"ר סי' נה (והוא בלקו\"י סי' ס), ושם סי' קכו (והוא במדל\"י סי' קצ (קצח)).\n<i>תעשה שיהיה נחת רוח לבורא יתברך</i> – עיין צוה\"ר סי' יא, ובהערות שם.\n<i>שאם תרצה כו' תדקדק כו'</i> – ראה במפרשי המשנה כאן."]]],[400080527,"תסג\n\n<b>כל</b> הלומד את בן חבירו תורה מעלה עליו כאלו ילדו. פירוש א\"ב הוא אלף פל\"א העליון, משפיע לבי\"ת, והוא נקודה בהיכליה. וכן אותיות ר\"ב, הרי\"ש, הוא ריש דרגין, משפיע לבי\"ת, לכן הם שוים.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כב, ב. כתבי קודש לג, א.</b>\n<i>כל הלומד כו'</i> – סנהדרין יט, ב.<i> אלף פל\"א</i> – זח\"ג קצג, ב. תקו\"ז ת\"ע קלה, א.<i> והוא נקודה בהיכליה</i> – ראה זח\"א ו, א. שם טו, א. תקו\"ז יב, ב.<i> הרי\"ש הוא ריש דרגין</i> – (חכמה, זח\"א ב סע\"א) ראה תקו\"ז תס\"ט קיא, ב. ושם קטז, א.<i> משפיע לבי\"ת</i> – ראה פרדס רמונים שכ\"ז פ\"ה.\n----- הערות וציונים -----\n<i>אלף פל\"א העליון</i> – ראה זח\"ג לא, א דא חכמתא עילאה. וראה לעיל סי' לג, סי' קג, ועוד, דהאלף הוא חכמה.\n<i>אלף . . משפיע לבי\"ת</i> – אל\"ף אבא (חכמה) זח\"ב קלו סע\"ב, ובי\"ת אמא עלאה (בינה) תקו\"ז תי\"ח לא סע\"ב. וראה סי' שלב ד\"ה ונודע.\n<i>הרי\"ש הוא ריש דרגין</i> – חכמה, כנסמן במ\"מ."]]],[400080528,"תסד\n\n<b>פתח</b> בכד וסיים בחבית. פירוש כי יש ב' מיני כלים, קטנים וגדולים. כי הכלים הם האותיות, ובהמחשבה הם כלים קטנים ובאהבה הם כלים גדולים. והענין הוא, כי האיך יש שייכות לכלי והעובדא עם המחשבה, כי הוא דבר רוחני. אך בכל כלי יש כ\"ב אותיות, נמצא כי יש להמחשבה חיבור עם העובדא ע\"י האותיות ההם, כי גם המחשבה מחשב ע\"י אותיות, והם האותיות של העובדא. ואלו האותיות הם מועטים. אבל באהבה יש ג\"כ אותיות, כי במה הוא אוהב הוא באותיות, והאותיות של העובדא גם כן, והוי כלים גדולים. וזהו פתח בכד, כלים קטנים, וסיים בחביות, באהבה, בכלים גדולים. וזהו ויותר יעקב לבדו, ואמרו רז\"ל שכח פכים קטנים. ור\"ל [ויותר] יעקב לבדו [הוא] בלי מוחין, [וזה אמר שכח] פכים קטנים, היינו כלים קטנים והם המוחין. ועל כן ויקרא שמו ישראל, והם עם המוחין.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כג, ב. כתבי קודש כט רע\"ג. ושם לא, ב (ושם חסר ריש הדרוש). שמועה טובה מח, א.</b>\n<i>פתח בכד כו'</i> – ב\"ק כז סע\"א.<i> הכלים הם האותיות</i> – פרדס רמונים שכ\"ז פ\"ב. ע\"ח ש\"ה פ\"ה. שם ש\"ח פ\"ו. ראה זח\"א טו, ב. תקו\"ז יב, ב.<i> ויותר יעקב לבדו</i> – וישלח לב, כה.<i> שכח פכים קטנים</i> – חולין צא, א.<i> ויקרא [את] שמו ישראל</i> – וישלח לה, י.<i> ישראל . . עם המוחין</i> – ראה ע\"ח של\"ח ספ\"ב. שער הפסוקים וישלח סוף סי' לב.\n----- הערות וציונים -----\n<i>הכלים הם האותיות</i> – ראה סי' קכג רד\"ה והנה ידוע.\n<i>המחשבה מחשב ע\"י אותיות</i> – ראה סי' סא, וסי' קמו.\n<i>יעקב לבדו כו' ישראל והם עם המוחין</i> – ראה ע\"ח של\"ח ספ\"ב. וראה לעיל סי' ס ד\"ה ונקדים, וסי' קכט."]]],[400080529,"תסה-א\n\n<b>סריס</b> אין לו זקן. כי חכמי הרופאים כותבין כי השערות הם ממותרי המוחין. ויש נקבים בראש ונקבים בשערות, ודרך שם יוצאים הרוח והמותרות המוחין. לכך נקרא אור חוזר. ולכן מי שיש לו אהבה לאשה או לאכילה, ולא לדבר רוחני וחיוני וחלק אלו\"ה שבהם אלא לדבר גשמי שבהם, וכן יראה גרוע והתפארות גרוע וכדומה, זה הוי שברי הכלים. ולכן צריך תיקון לסלק האהבה הרע ולהיות לו אהבה לעבודת הבורא יתברך, וללמוד קל וחומר, מה אם אהבתי דבר גרוע מאוד מכל שכן לאהוב את הבורא יתברך. ובזה יש [לו] התקשרות להבורא יתברך, היפך מה שהיה לו התקשרות עם האשה. וזהו סוד סריס, מי שאין לו התקשרות ואינו חוזר ממה שהיה לו התקשרות הגרוע, זה אין לו בחינת זקן. וזהו סוד יוסף מסלסל בשערו היה, ר\"ל יוסף היה לו התקשרות עם הבורא ית', לכן היה לו בחינת מסלסל בשערו. (וז\"ש) [וזה] ניצוצות הקדושה שצריכין אנו להעלות, דהיינו להיות לנו אהבה ויראה והתפארות וכו' להבורא יתברך, וזה מוציא אותם למעלה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כד, א. כתבי קודש לא, ד.</b>\n<i>סריס אין לו זקן</i> – יבמות פ, ב.<i> השערות הם ממותרי המוחין</i> – מבו\"ש ש\"ה ח\"א ספי\"ג. זח\"ג קלד, א. וראה ע\"ח שי\"ג פי\"א.<i> יוסף מסלסל בשערו היה</i> – תנחומא וישב ח.<i> מסלסל . . להעלות</i> – ראה ראב\"ע למשלי ד, ח.\n----- הערות וציונים -----\n<i>ולכן מי שיש לו אהבה כו' ולכן צריך תיקון כו'</i> – ראה סי' רו ובהערות שם.\n<i>וזהו סוד סריס כו'</i> – ראה סי' קיח ד\"ה או רמוז."]]],[400080530,"תסה-ב\n\n<b>צירופי</b> האותיות, פי' כי האותיות הם בשבירה (וד\"ל) [גדולה], וצריכין אנו לצרף וללבן ולהאיר אותם האותיות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כד, א. כתבי קודש לב, א.</b>\n----- הערות וציונים -----\nעיין מש\"כ בביאור ענין זה במאור עינים ר\"פ משפטים, וכן שם בריש פ' נשא.\n<i>האותיות הם בשבירה כו'</i> – ראה סי' צז ד\"ה וז\"ש כי. סי' קטו. וסי' רעז-א."]]],[400080531,"תסו\n\n<b>אלמלא</b> לא שמרו ישראל אלא ב' שבתות מיד היו נגאלין. פי' על דרך מ\"ש רז\"ל ישראל מפרנסים לאביהם שבשמים. פי' כי הקב\"ה מקבל תענוג מעבודתנו שאנו ממליכין אותו עלינו, ע\"ד והאם רובצת על האפרוחים. וע\"ד הגמרא יותר ממה שהעגל רוצה לינק וכו', נמצא כי האם כשמניקה את בנה האם מקבלת תענוג במה שמשפעת לבנה והבן [נ\"א: וכן] המקבל השפע ממנה. [נמצא] האם נוקבא אצל הבן. והבן נוקבא אצל האם במה שמקבל שפע ממנה וד\"ל. נמצא כי יש כאן ב' נוקבין. הקב\"ה כביכול הוי כמו נוקבא בזה התענוג שמשפיע לבניו, ואנו נוקבין אצל האם שמקבלין השפע ממנה. וזהו אלו שמרו ישראל את הב' שבתות, ר\"ל אלו שמרו, בעבודתינו ובתפילתינו, כדי שהקב\"ה יקבל תענוג. וזהו ב' שבתות מי\"ד נגאלו, פי' היו\"ד שישפי\"ע לדל\"ת, היו נגאלין וד\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כד, א. כתבי קודש לב, א.</b>\n<i>אלמלא לא שמרו כו'</i> – שבת קיח, ב.<i> ישראל מפרנסים כו'</i> – זח\"ג ז, ב.<i> והאם רובצת גו'</i> – כי תצא כב, ו.<i> יותר ממה שהעגל כו'</i> – פסחים קיב, א.<i> המקבל . . נוקבא</i> – תקו\"ז תנ\"ה פט סע\"א.<i> היו\"ד שישפי\"ע</i> – (דאיהי בדכורא) זח\"ג רלו, ב.<i> היו\"ד שישפי\"ע לדל\"ת</i> – ראה זח\"א רלב, א.<i> לדל\"ת</i> – (נוקבא) זח\"ב קעח, ב. שם ד, ב.\n----- הערות וציונים -----\n<i>על דרך מ\"ש רז\"ל ישראל מפרנסין כו'</i> – ראה סי' מג, וסי' ס, ובהערות שם. וראה בהערות לסי' מד ד\"ה אש.\n<i>נמצא כי יש כאן ב' נוקבין כו'</i> – עיין סי' מג ד\"ה ובאמת. וסי' רפז.\n<i>מי\"ד נגאלו פי' היו\"ד שישפיע לדל\"ת</i> – ראה סי' מד ד\"ה וזאת, ובהערות שם."]]],[400080532,"תסז\n\n<b>בן</b> ג' שנים הכיר אברהם את בוראו. פי' (ג' שנים) [שנויים], כי ג' אהבות יש זו למעלה מזו. הא' הוא [אהבת ה'] משום שעושה עמו טובות. הב' שעשה כבר עמו טובה מיום הוולדו עד גדולו<sup data-n=\"1\">נט</sup>. והג' בלא טובות גשמיות, אלא [הגדולה שבטובות] מפני שהוא אל גדול ונורא, ובחר בגשמיות לעבוד אותו ולשרתו.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כד, ב. כתבי קודש כט, ג.</b>\n<i>בן ג' שנים כו'</i> – נדרים לב, א.<i> אל גדול ונורא</i> – ע\"פ עקב ז, כא.\n----- שולי הגליון -----\n<b>נט</b> ) <i>בכתבי קודש מוסיף כאן:</i> דהיינו מחיתו כגמול עלי אמו [תהלים קלא, ב], ועיין בחובת הלבבות שער האהבה [שער הבטחון, סוף פתח השער].\n----- הערות וציונים -----\n<i>שנים . . שנויים</i> – ראה סוף סי' כז ובהערות שם."]]],[400080533,"תסח\n\n<b>יהי</b> ביתך בית וועד לחכמים. כי יש ב' בתים. [א'] מה שמקבל קנין עולם בתוכו, כמו בית מושב. והב' הוא אותיות קדושות, שהשכל של אדם מתלבש בתוך אותיות הדיבור. וחכמה הוא הבית הב'.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לב, ב.</b>\n<i>יהי ביתך בית כו'</i> – אבות פ\"א מ\"ד.<i> כמו בית מושב</i> – ע\"פ בהר כה, כט.\n----- הערות וציונים -----\n<i>שהשכל של אדם מתלבש כו'</i> – להעיר מסי' ת."]]],[400080534,"תסט\n\n<b>יהי</b> ביתך פתוח לרוחה. פי' שיהיה במדה שהוא חומד עולה<sup data-n=\"1\">ס</sup> לכל דבר, ואפילו הכי יהיו עניים בני ביתך, רצה לומר שיכבוש אותם, והוא במדריגת צדיק.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לב, ב.</b>\n<i>יהי ביתך פתוח לרוחה</i> – אבות פ\"א מ\"ה.<i> יהיו עניים בני ביתך</i> – שם.\n----- שולי הגליון -----\n<b>ס</b> ) <i>נראה שצ\"ל</i> עליה,<i> ור\"ל מדת החמדה שלו</i>.\n----- הערות וציונים -----\n<i>שיכבוש אותם</i> – להעיר מסי' תטז."]]],[400080535,"תע\n\n<b>נתן</b> עיניו בו ונעשה גל של עצמות. פי' כי כשהצדיק באהבתו ויראתו והתפארותו להקב\"ה, אז יוכל להמשיך עמו כל האנשים אשר הם קדושים בקדושתו גם כן. כי כל מין מדבק במינו, כמו מים במים נעשה אחדות. אבל מי שהוא מינו, אלא שהחומריות מעכב שאין יכול לעלות עמו, אז עיקר החיוני [נ\"א: החיות], שהוא מהקדושה, נמשך עם הצדיק כי הוא ממינו, ושאר לבושים של רשע, שאינם ממינו, נתפרד ונעשה גל של עצמות, כי כבר הוציא הניצוצות ממנו ואין לו חיות. וזהו נתן עיניו בו, לשון בהירתו להעלותו, והלה נמנע.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לב, ב.</b>\n<i>נתן עיניו בו כו'</i> – ברכות נח, א.<i> כל מין מדבק במינו</i> – זח\"א כ, ב. ראה ב\"ק צב, ב. ספר החינוך ססי' שמו. ראה שם סי' תקעו.\n----- הערות וציונים -----\n<i>כשהצדיק כו' יוכל להמשיך עמו כו'</i> – ראה סי' רמח ד\"ה והנה כשהצדיק, ובהערות שם.\n<i>אבל מי כו' שהחומריות מעכב כו'</i> – ענין זה מבואר בערבי נחל פ' בא ד\"ה ונראה שיובן. ורג\"כ קדושת לוי פ' בא ד\"ה נטה ידך."]]],[400080536,"תעא\n\n<b>הצדיקים</b> אומרים מעט ועושים הרבה. פי' כי הדיבור היוצא מהפה הוא דבר מועט, אבל עושים הרבה למעלה בזה הדיבור.\n<b>ע\"י</b><sup data-n=\"1\">סא</sup> רצון הבנאי מתחבר [עצמו] הבנאי עם הבית.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לג, א. כתבי קודש כח, א.</b>\n<i>הצדיקים אומרים מעט כו'</i> – נדרים כא, ב.\n----- שולי הגליון -----\n<b>סא</b> ) <i>גם במקבילות בא זה בהמשך להנ\"ל, </i>(<i>ובכתבי קודש: </i>שע\"י)<i>, ובדוחק יש לקשרם. ואולי צ\"ל ענין באנפא נפשיה</i>.\n----- הערות וציונים -----\nעיין אוה\"מ פ' תשא סד\"ה בפסוק ומשה יקח: והמגיד ע\"ה היה אומר ברוך אומר ועושה, כלומר מי האיש החפץ חיים להיות בגדר ברוך אומר ד\"ת ותפלה ובשעת האמירה עושה פעולה בעולמות כאמור וגם מעורר לבות בני אדם, זה האיש הוא בגדר ברכה לאפוקי הרשעים אומרים הרבה ואפילו מעט אינם עושין רשימה כלל לא למעלה ולא למטה, כיון שבדבור הוי\"ה מאסו מלבנות ולכונן צירוף שם הוי\"ה ב\"ה כו'.\n<i>הדיבור כו' דבר מועט אבל עושה הרבה למעלה כו'</i> – להעיר מסי' קפז."]]],[400080537,"תעב\n\n<b>גדולים</b> צדיקים שמהפכים מדת הדין לרחמים. פי' כי הטבע אין לו שינוי והוא דין, והנס הוא רחמים. וכשאורו של הנס מתחיל להתגלות אז בטל כולו [נ\"א: כולא] במציאות. אבל הצדיק אינו רוצה להטריח את בוראו בנס, אבל יאמר כי הנס הוא דרך הטבע כי ראוי להיות כך. וזהו שמהפכין מדת הדין, ר\"ל הטבע, למדת הרחמים, [ר\"ל] על מדת הרחמים [אומרים] שזה [הוא] מדת הטבע ודו\"ק.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לג, א. כתבי קודש כח, ב. שמועה טובה עה, ב.</b>\n<i>גדולים צדיקים שמהפכים כו'</i> – בר\"ר לג, ג.<i> הצדיק אינו רוצה להטריח כו'</i> – ראה של\"ה תושב\"כ ס\"פ לך לך ע\"פ שבת נג, ב ותענית כד, א.\n----- הערות וציונים -----\n<i>וכשאורו של הנס כו' אז בטל כולו במציאות</i> – ראה סי' תעה. ועיין סי' רעח ובהערות שם."]]],[400080538,"תעג\n\n<b>אין</b> התורה מתקיימת אלא במי שממית עצמו. פי' כי כשאדם מדבר, אז אינו יכול להבין בהבנתו מה. ואם הוא מבין דבר על בוריו, אזי אינו יכול לדבר כראוי, ואז הוי הדיבור מת, ולהיפך הוי הבינה מת כביכול. כי הדבר שאינו מושל מחמת זולתו הוי מת. וזה ידוע כי לכל דבר שבעולם צריך י' מדות, ואם אין הנצחון שמנצח את המניעות ממנו אז אין הדבר נגמר לפועל. וכן להבנה צריך י' מדות, והעיקר הם הנה\"י. ומי נקרא הבינה, כי מה שאני מבין אני שואל מ\"י זאת, ואם אינו מבין לא שייך לשאול מ\"י. לכן מ\"י מרמז על אימא. לכן מי שרוצה ללמוד תורה צריך ללמוד בקול ודיבור, לכן צריך להמית את המ\"י, דהיינו נה\"י דההבנה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לג, ב.</b>\n<i>אין התורה מתקיימת אלא כו'</i> – ברכות סג, ב. זח\"ב קנח, ב.<i> והעיקר הם הנה\"י</i> – ראה ע\"ח ש\"ח פ\"ב.<i> ומי נקרא הבינה</i> – זח\"ב קיז, א. תקו\"ז תי\"ג כח, א.<i> שואל מ\"י זאת</i> – זח\"א א, ב.<i> צריך ללמוד בקול ודיבור</i> – זח\"ג לט סע\"א ואילך. עירובין נג, ב ואילך.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קמא."]]],[400080539,"תעד\n\n<b>כל</b> מקום שאתה מוצא גדולתו של הקב\"ה שם אתה מוצא ענוותנותו. היינו יציאת מצרים וקריעת ים סוף וכדומה, שם אתה מוצא ענוותנותו. דהיינו<sup data-n=\"1\">סב</sup> שהשי\"ת עשה עצמו כמ\"ה ללחום עם פרעה, אע\"פ שהוא גשמי.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לד, א.</b>\n<i>כל מקום שאתה מוצא כו'</i> – מגילה לא, א.\n----- שולי הגליון -----\n<b>סב</b> ) <i>באוה\"א: </i>דהיינו שהשי\"ת כביכול עשה כמה פעולות ללחום עם גשמי."]]],[400080540,"תעה\n\n<b>עושים</b> רצונו של מקום. ר\"ל שעושים ומהפכים הרצון של מקום לטוב. כי על ידי התעוררות דלתתא מביאין הי\"ש באי\"ן, ומהפכין שם באי\"ן, דהיינו כשיבוא פעם שנית בי\"ש יהיה ההיפך כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לד, א</b>\n<i>עושים רצונו של מקום</i> – ברכות לה, ב. ועוד.<i> שעושים ומהפכים כו'</i> – ראה תנחומא בשלח טו.\n----- הערות וציונים -----\nראה סי' קמג ד\"ה כתיב, וסי' תכד ד\"ה וכתיב חכמות, ובהערות שם. רג\"כ סי' רעח."]]],[400080541,"תעו\n\n<b>כל</b> תיבה הצריכה למ\"ד בתחלתה הטיל לה הכתוב ה' בסופה. פי' כי הלמ\"ד והה' הם נקבות, אלא שהלמ\"ד הוא בית ראשון והה' היא בית שני.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לו, א. כתבי קודש כב, ג.</b>\n<i>כל תיבה הצריכה למ\"ד כו'</i> – יבמות יג, ב.<i> הלמ\"ד והה' הם נקבות</i> – (הל' בינה, אימא עילאה) תקו\"ז תנ\"ה פט, א. זח\"ב קנט סע\"א, ואוה\"ח שם. (הה' מלכות, אימא תתאה) זח\"ג (ר\"מ) יז, א. שם לד, א (או נק' בת, זח\"א כז, ב. זח\"ג יא, ב).<i> שהלמ\"ד הוא בית ראשון</i> – (בינה) תקו\"ז תכ\"ב סג, ב. שם תנ\"ה צב, א.<i> והה' היא בית שני</i> – (מלכות) תקו\"ז שם.\n----- הערות וציונים -----"]]],[400080542,"תעז\n\n<b>בת</b> היה לאברהם אבינו ובכל שמה. פי' כי עולם חסד יבנה, וחסד הוא לאברהם. ולזה החסד הוצרך כדי להיטיב לברואיו ולהאציל הנוקבא. וזאת הנוקבא נקראת בכ\"ל, ר\"ל בית של כ\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לז, ב.</b>\n<i>בת היה לאברהם כו'</i> – ב\"ב טז, ב.<i> עולם חסד יבנה</i> – תהלים פט, ג.<i> וחסד הוא לאברהם</i> – מיכה ז, כ. זח\"ב רעו, א. זח\"ג שב, א.<i> להיטיב לברואיו</i> – ראה שערי אורה להרי\"ג שער ז ספירה הרביעית. פרדס רמונים ש\"ב פ\"ו. ע\"ח שער הכללים רפ\"א. שומר אמונים להרי\"א ויכוח ב סי' יג.<i> וזאת הנוקבא נקראת בכל</i> – ראה זח\"ב לו סע\"א. שם לז, א ופה, ב.\n----- הערות וציונים -----\nכבר הובא לעיל סי' כט."]]],[400080543,"תעח\n\n<b>סיג</b> לחכמה שתיקה מעשר סיג לעושר. פי' סיג לחכמה הוא גדר. כשהוא שותק אז הוא לא מטי אל החכמה ואל הבינה, אז הוא מטי למדריגה שלמעלה מן החכמה. א\"כ הוא מקבל ממה שלמעלה ממנו. וכשהוא משפיע אז אינו מקבל, כי איידי דטריד לפלוט לא בלע. וזהו פי' סיג לחכמה שתיקה. כי כשהשכל מסתלק למעלה, א\"כ הוא בא למעלה למעלה לשורשו, אז נתחזק השכל. וזהו מעשר סיג לעושר, כי אין הברכה מצויה בדבר שיש בו מספר. א\"כ כשהוא נותן מעשר אז מביא את המספר למעלה אל הקדושה, ואז בא אל האחדות, ואז יכול הברכה לשרות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מ, א.</b>\n<i>סיג לחכמה שתיקה מעשר כו'</i> – אבות פ\"ג מי\"ג.<i> איידי דטריד כו'</i> – ע\"פ חולין ח, ב.<i> אין הברכה כו'</i> – תענית ח, ב. זח\"ב קפז, ב. שם רכה, א.<i> אם כן כשהוא נותן מעשר כו'</i> – זח\"ב רכה, א.\n----- הערות וציונים -----\n<i>פי' סיג לחכמה כו'</i> – להעיר מצוה\"ר סי' קלג. וראה לעיל סי' שפב. רג\"כ סי' תי ובהערות שם.\n<i>מביא את המספר למעלה כו'</i> – להעיר מסי' כז וכח דאחד (אחדות) הוא למעלה מן המספר.\n<i>אל הקדושה ואז בא אל האחדות</i> – ראה סי' רס ד\"ה כתיב."]]],[400080544,"תעט\n\n<b>העושה</b> תפילתו עגולה סכנה ואינה מצוה. פי' רש\"י<sup data-n=\"1\">סג</sup> כשנופל תחנון סכנה שלא ירצץ מוחו. פי' העושה תפילת\"ו, על שם נפתלת\"י, שמדבק [ומחבר] מחשבתו בבורא ית', וכשעושה (תפילתו) [דביקותו] עגולה, פי' פעמים הוא למעלה ופעמים הוא למטה כדבר עגול, ואינו [מחובר ב]תמידות. סכנה, פי' שכשנופל (תחילה) [תחנון] היא פעמים שמחשבתו יוצאת לחוץ לברר ניצוצות מן הקליפות, ע\"ד עיני ה' צופות רעים וטובים. וכן מצינו שנשבה הארון בין הפלשתים כדי לברר הדיבורים שהיו בגלות ולהביא מנחה לה', על דרך [נ\"א וזהו] וישרנה הפרות, שאמרו שירה, מאי שירה שירו לה' שיר חדש<sup data-n=\"2\">סד</sup>, והוא לשון זכר. אבל שירת הים הוא לשון נקבה, לפי שאינה נצחיות, אבל שירה זו עתיד לאומרה בעת הגאולה [לימות המשיח במהרה בימינו], והוא גאולה נצחיות, לפיכך הוא לשון זכר. והוא נקרא תחנון שאחר שמונה עשרה שמחשבתו יוצא למטה (נ\"א<sup data-n=\"3\">סה</sup> והנוקבא נקראת תחנה אחר י\"ח יוצא מחשבתו למטה), ואז סכנה שלא ירצץ את מוחו, שלא יקלקל את שכלו. וז\"ש (הר\"ן) [האר\"י ז\"ל] הקדוש שצריך האדם (להשמר) [לשמור] את עצמו בשעה שהוא נופל תחנה שהוא בא בעולם העשיה, ודו\"ק.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קצב (רב). אוה\"א מב, ב.</b>\n<i>העושה תפלתו עגולה כו'</i> – מגילה כד, ב.<i> פי' כשנופל תחנון כו'</i> – פי' ר\"ח שם.<i> תפילת\"ו ע\"ש נפתלת\"י</i> – ויצא ל, ח. ובת\"א ופרש\"י שם.<i> שכשנופל תחנון . . לברר ניצוצות</i> – ע\"ח שער הכללים ספ\"א. שם שמ\"ט פ\"ה. פע\"ח שער נפילת אפים פ\"ב.<i> עיני ה' צופות גו'</i> – משלי טו, ג.<i> שנשבה הארון כו'</i> – ש\"א ד, יא. שם פ' ה-ו.<i> וישרנה הפרות</i> – ש\"א ו, יב.<i> שאמרו שירה כו' שירו לה' גו'</i> – ע\"ז כד, ב. זח\"ג רא, א.<i> שירו לה' שיר חדש</i> – תהלים צח.<i> והוא לשון זכר אבל שירת הים כו'</i> – זח\"ג רא, א.<i> שירה זו כו' גאולה נצחיות</i> – מכילתא בשלח מס' דשירה פ\"א. שמ\"ר כג, יא.<i> וז\"ש האריז\"ל הקדוש כו'</i> – פע\"ח שער נפילת אפים פ\"ב.\n----- שולי הגליון -----\n<b>סג</b> ) <i>כ\"כ גם במדל\"י, ובאוה\"א </i>פי' הר\"ן<i>, וצ\"ל</i> פי' רבינו חננאל.\n<b>סד</b> ) <i>במדל\"י ממשיך כאן:</i> ר\"ל שהיה כבר אחר הבירורין כמ\"ש האר\"י ז\"ל.\n<b>סה</b> ) <i>הנ\"א אינו במדל\"י. באוה\"א רק הנ\"א, אבל בשנוי: </i>והנוקבא נק' תחנה, אחר שע\"י יוצא מחשבתו למטה.\n----- הערות וציונים -----\n<i>תפילת\"ו . . שמדבק כו'</i> – ראה סי' רנה ד\"ה ולזה רמזו, ובהערות שם.\n<i>עגולה פי' כו'</i> – ראה לעיל סי' תח.\n<i>[הערה סד בשוה\"ג] כמ\"ש האר\"י ז\"ל</i> – ראה פע\"ח שער השבת פי\"ט."]]],[400080545,"תפ\n\n<b>דע</b> מה למעלה ממך. פי' דע כל מה שלמעלה, הכל הוא ממך.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קצח (רח). צוה\"ר סי' קמב.</b>\n<i>דע מה למעלה ממך</i> – אבות פ\"ב מ\"א.\n----- הערות וציונים -----\nעיין לעיל סי' קלד ד\"ה וזהו על, סי' קסז, סי' ריב, סי' רסד וסי' ש, והמובא שם בהערות."]]],[400080546,"תפא\n\n<b>וסרתם</b> ועבדתם. ר\"ל כאשר האדם סר מן הדביקות ח\"ו, יבוא לידי ועבדתם אלהים אחרים<sup data-n=\"1\">סו</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קצט (רט).</b>\n<i>וסרתם ועבדתם</i> – עקב יא, טז.\n----- שולי הגליון -----\n<b>סו</b> ) <i>בצוה\"ר סי' עו, ואוה\"א כ, א: </i>מר\"י בעש\"ט, כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי. פירוש, כי כאשר האדם מפריד את עצמו מהשי\"ת מיד הוא עובד עבודה זרה, ולא יש דבר ממוצע, וזה וסרתם ועבדתם.\n----- הערות וציונים -----\nשייך לרמזי תורה פ' עקב.\nראה מאור עינים ר\"פ שמות: מרגלא בפומיה דהרב בעש\"ט נשמתו בג\"מ זכותו יעמוד לנו על מ\"ש וסרתם ועבדתם אלהים אחרים, תיכף כשסרתם מאת ה' מיד ועבדתם אלהים אחרים כו'. וכן בדמ\"א פ' תרומה ד\"ה ועשית, ושם פ' קדושים ד\"ה אל תפנו. (ומבואר שם, ובלקוטי שיחות חט\"ו ע' 5-324). וראה כש\"ט סי' קמט. להעיר משבת קמט סע\"א אל תפנו אל מדעתכם, ע\"פ פי' הערוך ערך פן. וראה ספר המצות להרמב\"ם מל\"ת יו\"ד. מו\"נ ח\"ג בהערה בסוף פנ\"א."]]],[400080547,"תפב\n\n<b>הלואי</b> שיהיה מורא שמים עליכם כמורא בשר ודם וכו'. הלוא\"י הוא לשון חיבור ודמיון דבר לדבר, כלומר תדמו מורא שמים למורא בשר ודם. למשל כשישן ובא רבו והקיץ אותו בידו, (מעט) [מיד] הוא נרתע ונזדעזע לפניו, ומכ\"ש כשהשי\"ת מקיצו משנתו שהוא בחצות הלילה כידוע.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ג, ד (סי' פו).</b>\n<i>הלואי שיהיה כו'</i> – ברכות כח, ב.<i> הלוא\"י היא לשון חיבור</i> – ע\"פ ויצא כט, לד.\n----- הערות וציונים -----\n<i>כשהשי\"ת מקיצו . . בחצות הלילה</i> – להעיר מזח\"א צב, ב. זח\"ב רעא רע\"ב. של\"ה, מס' חולין בפרק דרך חיים סד\"ה כתב התשב\"ץ (קכג, ב)."]]],[400080548,"תפג\n\n<b>אמרו</b> רז\"ל אין נושאין נשים במועד לפי שאין מערבין שמחה בשמחה. אפשר לומר שרמזו רז\"ל על פי פשוטו להזהיר את האדם על עניניו בעולם הזה. כי הנה ידוע כי הגוף נקרא נוקבא. והזהירו שלא יהיה עסק האדם במוע\"ד ימי חייו חיי הבל, שהם חרוצים וקצובים לו זמן מועט. בימי מועד הנזכר לא יחזור בהם אחר תענוג הגוף למלאות תאותו תאות גשמיות. וזהו לשון נשיא\"ה<sup data-n=\"1\">סז</sup>, שמנשא ומגדל את הגוף בגבהו ברחבו ובעוביו. לפי שאין מערבין שמחה בשמחה, ר\"ל שמחה והוללות שלתענוגי החומריים בשמחת הרוחני שהיא עבודת הבורא יתברך, וזהו וודאי נקרא עירו\"ב, שמערב טוב ורע. ופשיטא בימי החג שהם נקראים מוע\"ד ממש. ועוד, מועד לשון עד\"י וקישוט, כי ימי מועד ניתנו לכל איש ישראל לעורר במצות חגיגת ושמחת המועד שהם דברים עליונים, ולעשות תכשיטין ועידוים<sup data-n=\"2\">סח</sup> ולגרום תענוג ושמחה אל העולמות העליונים שישפיעו אל התחתונים. וז\"ש ברגלים יראה כל זכורך, שאז יהיה כל אדם במועד לראות וליראות, כל זכורך את פני ה', ר\"ל כל תאוותו ושמחתו יהיה לגדל ולנשא מדריגת הדכורא, שהיא הנשמה וכל העליונים המשפיעים שהם דכורים, ולא שיערב בהם שמחת נשים כנזכר.\n<b>ואם</b> תאמר והלוא כל ימי האדם הוא מוזהר על כך, וא\"כ למה יצאו ימי מועד מן הכלל ואמרו לשון מוע\"ד, דמשתמע ימי מועד ממש. אבל האמת הוא שכל ימי מועד האדם הוא באזהרה זו, רק ביותר צריך לזרז על ימות הרגל, כמ\"ש רז\"ל סיקבא דשתא ריגלא.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לו, ד (סי' רעט).</b>\n<i>אמרו רז\"ל אין כו'</i> – מו\"ק ח, ב.<i> הגוף נקרא נוקבא</i> – זח\"א קפא, ב. שם (ס\"ת) עט רע\"א.<i> לשון עד\"י וקישוט</i> – ע\"פ כי תשא לג, ד.<i> יראה כל זכורך</i> – משפטים כג, יז.<i> מדריגת הדכורא שהיא הנשמה</i> – ראה זח\"א (ס\"ת) עט רע\"א.<i> המשפיעים שהם דכורים</i> – ראה זח\"א רלב, א. פרדס רמונים ש\"ח פ\"ג ושם פ\"ו. נתיבות עולם למהר\"ל, נתיב האמונה פ\"א.<i> סיקבא דשתא ריגלא</i> – קידושין פא, א.\n----- שולי הגליון -----\n<b>סז</b> ) <i>כלומר \"נושאין\" הוא לשון נשיא\"ה</i>.\n<b>סח</b> ) <i>נראה שצ\"ל</i> ועדיים <i>או</i> ועידון.\n----- הערות וציונים -----\n<i>ופשיטא בימי החג כו'</i> – ראה רמב\"ם הלכות יו\"ט פ\"ו הלכות יח-כ, וטוש\"ע או\"ח סי' תקכט.\n<i>מועד לשון עד\"י וקישוט</i> – ראה סי' פו ד\"ה והנה מועד\"ה."]]],[400080549,"תפד\n\n<b>זכור</b> ושמור בדבור אחד נאמרו. איתא בס' הזוהר זכור לדכורא שמור לנוקבא. פי' כי הזכירה היא דבר חדש מה שלא נאמר מקודם, כמו ויזכור אלהים את רחל, שלא נאמר שום אמירה ודיבור מקודם לזה. אבל גבי שרה נאמר וה' פקד את שרה, כי כבר נאמר מקודם שיהיה בן לשרה, שנאמר אבל שרה אשתך וגו', לכך נאמר עתה וה' פק\"ד, ר\"ל פקד הדבר שנאמר מקודם. וכן נאמר זכו\"ר את אשר עשה לך עמלק, ובפעם ב', גבי שאול, נאמר (פקו\"ד) פקדת\"י, כיון שכבר כתוב בתורה הדבר ההוא. נמצא כי הפקידה והשמירה מקבלים מן דבר אחר שנאמר מקודם, לכן נקראים נוקבא. וכן בתפילה שאחר<sup data-n=\"1\">סט</sup> העקידה, ופקדנו בפקודת (הרחמים) [ישועה ורחמים] וכו', כתיב במשנת חסידים בפקודת נוקבא, כוונתו אל הנזכר. והנה נאמר בדברות הראשונות זכו\"ר, ובמשנה תורה שמו\"ר, להזכיר מה שכבר נאמר בדברות הראשונות, והשמירה מקבלת מהזכירה כנזכר.\n<b>כי</b> הנה הכלל הוא, כל מעשה בראשית בקומתן נבראו, ויצאו דכר ונוקבא כחדא, ואח\"כ סידר הקב\"ה ונסר לנוקבא להיות לפניו. וכן כיוצא בזה, עיקרן של הדברים נאמרו הכל בתורה שבכתב, ובתורה שבע\"פ סידר הדברים, כמו גורעין ומוסיפין ודורשין ומסדרין הדברים. כן בוודאי בזכור כלל השמירה, רק במשנה תורה, הנקרא משנה למלך שהיא נוקבא, יצא השמירה לחוץ ונתגלה. וז\"ש בדבור אחד נאמרו, כי בכלל זכור נכלל בוודאי השמור, שהרי מקבלת ממנו. וכן נקראים אהבה ויראה דכר ונוקבא. כי עיקר היראה הוא שירגיש האדם יראת הבורא יתברך. וזהו על כרחך בהשפעת הבורא יתברך, מחמת אהבה שיש להשי\"ת אל האדם ומשפיע לו השפע ורוח טהרה והבהירות שירגיש האדם קדושתו ואימתו יתברך. נמצא כי היראה מקבלת מאהבה. ובודאי באדם הוא להיפך, שמתחילה מקבל היראה, כי בזא\"ת יבוא אל הקודש, ואח\"כ הוא בא למדריגת אהבה. אבל בהשי\"ת הוא להיפך כנזכר.\n<b>ונחזור</b> אל הענין. כי הנה אמרו רז\"ל שמור דלאו לאו ודעשה עשה. נמצא על כרחך האי שמור הוא דבר המקבל משני דברים, ומהיכן שהוא מקבל כן הוא נקרא כמוהו, ואם כן הוא נוקבא. משא\"כ זכור בכל מקום שהוא עשה, מפני שאין צריך לקבל, שהוא דכר בפ\"ע. ועוד, כי שמור הוא לשון שמירה, ואם כן צריך הוא לשמור איזה דבר זולתו, ואם כן הוא מקבל. ואמרו רז\"ל זכרהו על היין. נמצא ע\"כ הזכור הוא מדריגה יותר עליון מיין, כי זכור נאמר בפרשת קדש לי כל בכור. והנה מדריגת היין הוא שממנו בא הדיבור, כמו אגברו חמרא לדרדקי כי היכי דלימרו מילי. וזכור הוא יותר עליון, כי ממחשבה בא עיקר הדיבור (<sup data-n=\"2\">ע</sup>ע\"ד אבא יסד ברתא).\n<b>והנה</b> כתיב וידבר אלהים את כל הדברים האלה לאמור, כמ\"ש בזוהר כללן בדיבור, ואין צריך לומר שמור. ולכן אמרו זכור ושמור בדבור אחד נאמרו, במקום שהוא דיבור אחד, והנוקבא כלולה בו ולא נזכרה, כמו שמש ירח עמד זבולה, ונקרא בשם הזכר. והבן זה היטיב מאוד.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י מ, ב (סי' רפז).</b>\n<i>זכור ושמור כו'</i> – ר\"ה כז רע\"א.<i> זכור לדכורא כו'</i> – זח\"ב צב, א. תקוזו\"ח קכ רע\"א.<i> ויזכור אלקים את רחל</i> – ויצא ל, כב.<i> וה' פקד את שרה</i> – וירא כא, א.<i> אבל שרה אשתך גו'</i> – לך לך יז, יט.<i> פקד הדבר שנאמר מקודם</i> – זח\"א (מדה\"נ) קטו, ב.<i> זכו\"ר את אשר עשה גו'</i> – כי תצא כה, יז.<i> פקדת\"י</i> – ש\"א טו, ב.<i> במשנת חסידים</i> – מס' תפלת העשיה פ\"ב מ\"א.<i> בדברות הראשונות כו'</i> – יתרו כ, ח.<i> ובמשנה תורה כו'</i> – ואתחנן ה, יב.<i> כל מעשה בראשית בקומתן נבראו</i> – ר\"ה יא, א.<i> ויצאו דו\"נ כחדא . . ונסר כו'</i> – זח\"ב רלא, א. ויק\"ר יד, א וש\"נ.<i> גורעין ומוסיפין כו'</i> – יומא מח, א.<i> אהבה ויראה דכר ונוקבא</i> – תקו\"ז ת\"י כה, ב.<i> שמתחילה מקבל היראה כו'</i> – זח\"ב רטז, א.<i> בזא\"ת יבא גו'</i> – אחרי טז, ג. ראה זח\"ג נו רע\"ב.<i> שמור דלאו כו'</i> – מנחות לו, ב.<i> דבר המקבל . . נוקבא</i> – תקו\"ז תנ\"ה פט סע\"א.<i> זכור . . שהוא עשה</i> – ראה זו\"ח יתרו מא, ב.<i> זכרהו על היין</i> – פסחים קו, א.<i> זכור נאמר בפ' קדש כו'</i> – בא יג, ט.<i> אגברין חמרא כו'</i> – סנהדרין לח, א.<i> ממחשבה</i> – (קדש לי גו', חכמה) זח\"ב מג, ב. תקו\"ז תי\"ד ל, א.<i> אבא יסד ברתא</i> – זח\"ג רנו סע\"ב.<i> וידבר אלקים גו'</i> – יתרו כ, א.<i> כמ\"ש בזוהר כללן בדיבור</i> – תקו\"ז תכ\"ב סג סע\"ב. זו\"ח יתרו מא רע\"ב. מכילתא יתרו מס' דבחדש ספ\"ד.<i> שמש ירח עמד זבלה</i> – חבקוק ג, יא.\n----- שולי הגליון -----\n<b>סט</b> ) <i>צ\"ל</i> שלפני.\n<b>ע</b> ) <i>בלקו\"י אין סוגריים.</i>\n----- הערות וציונים -----\nכבר הובא לעיל סי' צט."]]],[400080550,"תפה\n\n<b>אל</b> תהיו כעבדים המשמשין את הרב על מנת לקבל פרס וכו'. יובן על פי משל. הנה האדם המרויח בממונו בתמידות בלי הפסק שעה אחת, זה הוא מרגיש חסרונו תמיד בעת שאינו מרויח, כי הרגלו תמיד להרויח. משא\"כ אדם שאינו מרויח אלא לזמן קצוב מזמן לזמן, זה אינו מרגיש [כל] כך בחסרונו אף על פי שהמעות בטלות אצלו. והנמשל, אדם שהוא תמיד דבוק במחשבתו בעבודת השי\"ת בלי הפסק רגע, וגם עבודתו בלי שום פניה בעולם רק לעשות נחת רוח ליוצרו, וכל מגמתו ועידונו ותענוגו לעסוק בתורת ה' ובעבודתו, ולהסתכל בפנימיות כל דבר שבקדושה בלי הפסק, ובשבחי השי\"ת ובתהילותיו, ובוודאי זה האדם יעשה יחודים גדולים והעלאת העולמות עד אין סוף. עד\"מ אם משבחים איזה אדם ומפארים אותו, יש לו תענוג גדול עד מאוד, ומתרומם בעצמו ומתעלה, כמ\"ש וישא יעקב רגליו, שנתבשר בשורה טובה וכו', וכן האדם מגודל התענוג הוא מתרומם ומתעלה מחמת השבחים והנחת רוח שעשה<sup data-n=\"1\">עא</sup> לו. ואם כך הוא הטבע בגוף החומרי והגשמי, (מכ\"ש) [כל שכן וכל שכן] בדבר רוחני, שהוא מתעלה ומתרומם עד אין סוף ואין קץ מחמת הנחת גדול שעושה אדם הצדיק ועולה מעולם לעולם ומייחדם, ויכול לראות ממש בחוש עין השכל כל האורות העליונים. ופשיטא שהעובד כזה [נ\"א: הזה] מגיע לו גם כן תענוג גדול בכל רגע ורגע בלי הפסק, כי שורש נשמתו דבוק למעלה. נמצא כי זה האדם (ה)מרגיש בחסרונו אם יפסוק אפילו רגע אחד, ומפני שהוא מרגיש לכך אינו מפריד את עצמו אפילו רגע אחד מעבודתו יתברך.\n<b>וזהו</b> המשמש על מנת שלא לקבל פרס, פירוש פר\"ס הוא לשון חתיכה שהוא דבר המוגבל, וכן לקב\"ל הוא לשון גבול, כמו מקבילות הלולאות, רק משמש בלי גבול ושיעור, כי אם בתמידות בלי הפסק. זהו נקרא עובד ה' האמיתי. אבל המשמש על מנת לקבל פרס, כמו זה המרויח מזמן לזמן ואינו מרגיש בחסרונו ובהבלות הזמן, וחס ושלום יפריד מעט מעט מעבודתו. אף על פי שהוא גם כן נקרא עובד את הרב, עם כל זה אין עבודתו אמיתי.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ו, ג (סי' קיט). כתבי קודש כז, ד (</b><i>עד </i><b>ומתרומם עד אין סוף).</b>\n<i>אל תהיו כעבדים כו'</i> – אבות פ\"א מ\"ג.<i> וישא יעקב רגליו</i> – ויצא כט, א.<i> שנתבשר בשורה טובה וכו'</i> – בר\"ר ע, ח.<i> פר\"ס הוא לשון חתיכה</i> – ע\"פ נגעים פי\"ג מ\"ט.<i> מקבילות הלולאות</i> – תרומה כו, ה. שם לו, יב.\n----- שולי הגליון -----\n<b>עא</b> ) <i>נראה שצ\"ל</i> שנעשה לו, <i>או כמו בכתבי קודש</i> שעשו לו.\n----- הערות וציונים -----\n<i>וזהו המשמש כו'</i> – להעיר מסי' רלו.\n<i>על מנת שלא לקבל פרס</i> – כן גם בסי' רעג וראה מש\"כ שם בהערות."]]],[400080551,"תפו\n\n<b>המוכיח</b> לחבירו זוכה להדבק בהקדוש ברוך הוא שנאמר מוכיח רעהו<sup data-n=\"1\">עב</sup> אחרי [חן כו'] ולא עוד אלא שמוציא חן וכו'. א\"ל כי הנה יש ב' מיני צדקות. א' הוא הצדקה הגשמיות, והוא מה שהעשיר משפיע לעני ונותן לו צדקה הגשמיות, שמחיה את נפשו ואת נפש בניו ובני ביתו. ויש צדקה יותר מעולה, והוא המחזיר חבירו למוטב, דהיינו המוכיחו. רק שצריך לזה שני תנאים. א' שיהיה כלי המקבל, דהיינו שיכנסו באזני המקבל תוכחה, לאפוקי מי שאינו שומע לקול המוכיחו ואינו רוצה לקבל ההשפעה. והב' שהמוכיח צריך להיות דוגמת צינור לשפוך ההשפעה אל הכלי, דהיינו שיהיה עשיר בדעת, כמדת הצדיק העליון המשפיע לעני כידוע, ואז יכול להשפיע אל העני בדעת ולהחזירו למוטב. וידוע כי מדת הצדיק הוא מדת יוסף, וכתיב אלה תולדות יעקב יוסף. וז\"ש מוכיח רעהו, דהיינו שיכול להוכיחו ולהחזירו למוטב מחמת שיש לו מדת הצדיק שהוא יוסף כנזכר. והראיה, שזימן לו הקדוש ברוך הוא להוכיח אותו האדם המקבל תוכחה, לכך נקרא רעה\"ו<sup data-n=\"2\">עג</sup>. הגם היותו עני בדעת, עם כל זה דומה הוא מי שרוצה לקבל דברי חבירות, שרוצה לשמוע וללמוד ולקבל כל מה שמוכיחים אותו. ולכן נקרא רעהו להצדיק המוכיחו. נמצא שזה מוכיח (ההמשכה) לאדם ההוא<sup data-n=\"3\">עד</sup> זוכה להיות אחר\"י, כלומר דבוק להשם יתברך, כמו מדת יוסף שהוא תחת מדת יעקב תפארת, וזהו אחרי וד\"ל. ולא עוד, אלא שמוצא חן, שהוא גם כן מדת יוסף. ועיין בפרשת נח<sup data-n=\"4\">עה</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ו, ב (סי' קיז).</b>\n<i>המוכיח לחבירו כו'</i> – תמיד כח, א.<i> כמ\"ש מוכיח גו'</i> – משלי כח, כג.<i> צדקה יותר מעולה והוא המחזיר כו'</i> – זח\"ב קכט, א ובהג' החיד\"א שם.<i> עשיר בדעת . . העני בדעת</i> – ע\"פ נדרים מא, א.<i> שצריך לזה ב' תנאים כו'</i> – ראה ערכין טז, ב (ובדק\"ס שם). ספרא, קדושים פ\"ד. ילק\"ש ח\"א רמז תשפט.<i> מדת הצדיק הוא מדת יוסף</i> – זח\"א נט, ב. זח\"ג כו, א. שם רלו, א ושב, א.<i> אלה תולדות יעקב יוסף</i> – וישב לז, ב.<i> מדת יעקב תפארת</i> – זח\"א קנז, ב. זח\"ב רעו, א.<i> חן שהוא ג\"כ מדת יוסף</i> – ראה וישב לט, ד. פרש\"י ויחי מט, כב.<i> ועיין בפרשת נח</i> – לעיל סי' טו.\n----- שולי הגליון -----\n<b>עב</b> ) <i>לשון הכתוב \"מוכיח אדם\" גו'</i>.\n<b>עג</b> ) <i>כנ\"ל לשון הכתוב \"אדם\", וא\"כ צ\"ל כאן</i> חברו <i>כלשון הגמרא בד\"ה</i>.\n<b>עד</b> ) <i>הלשון כאן אינו מובן. בלקו\"י יש נ\"א, בקיצור מהמבואר כאן:</i> הגם היותו עני בדעת, עם כל זה דומה הוא מי שרוצה לקבל ההמשכה.<i> ונראה שנתערבו כאן ב' הנוסחאות, וצריכים להשמיט כאן מילת</i> ההמשכה,<i> ולהוסיף ה' הידיעה למילת</i> מוכיח.\n<b>עה</b> ) <i>מובן שזה הוספת מסדר הספר או מדפיסו. בלקו\"י:</i> ובמקום אחר מבואר הענין יותר בפרטות.\n----- הערות וציונים -----\n<i>כמדת הצדיק העליון המשפיע לעני</i> – ראה זח\"ב רעו סע\"א. וראה שם קכג, א ובפי' הרמ\"ז שם (הובא בקיצור בנצוצי אורות להחיד\"א שם).\n<i>מדת הצדיק כו' וכתיב אלה תולדות כו'</i> – ראה סי' צה ד\"ה ולבאר.\n<i>שזימן לו הקב\"ה להוכיח אותו כו'</i> – להעיר מירושלמי ביצה פ\"ב ה\"ח מי שיש ספיקה בידו למחות כו'. רמב\"ם הלכות דעות פ\"ו ה\"ז. ובפרט ע\"פ הכלל המובא לעיל סי' קטו. ועיי\"ע לקוטי שיחות ח\"א ע' 262."]]],[400080552,"תפז\n\n<b>זכה</b> נוטל חלקו וחלק חבירו בגן עדן, לא זכה נוטל חלקו וחלק חבירו בגיהנם. וקשה, למה יהיה המדה כך. ועוד, חלק חבירו מאין הוא, והלוא רשע הוא, ורשע לגבי צדיק חבירו קרית ליה. ועוד, למה יתן החלק לזה הצדיק, והלוא הרבה צדיקים יש. ועוד מאין יש לרשע חלק בגן עדן, וגם בסיפא מאין יש לצדיק חלק בגיהנם.\n<b>וי\"ל</b> דאיתא בכתבי האר\"י זלה\"ה שהרשע אם מרבה לחטוא רחמנא ליצלן יכול הוא להחטיא את הצדיק, כי אוי לרשע אוי לשכינו. ואף על פי שאינו יכול להחטיאו בפועל, מביא את הצדיק לידי הרהור עבירה. וכן הצדיק במעשיו הטובים ובעבודתו יכול הוא להעלות את נפש הרשע, ואם לא יכול להעלותו מחמת שנשתרש בחטא, עם כל זה מביאו לידי הרהור תשובה. ולכך אמרו הרשעים מלאים חרטות, זו הרהור תשובה, רק מחמת שנשתרשו בחטאים חוזרים לסורם. ואיתא המקדש את האשה על מנת שאני צדיק [הרי זו מקודשת] וכו' [מפני] שמא הרהר תשובה [בלבו], נמצא אף על פי שהוא רשע גמור נעשה צדיק גמור בהרהור תשובה. וז\"ש זכה, פירוש הצדיק על ידי מעשיו, נוטל חלקו וחלק חבירו, פירוש הרשע שהרהר בתשובה ונעשה צדיק כמוהו באותו רגע. וזהו חבירו דקאמר. וגם תיכף כשהרהר בתשובה נגזר לו ליתן לו חלק בגן עדן, ועכשיו שחזר לסורו ניתן חלקו להצדיק שהביאו לידי הרהור תשובה, ומשלו ניתן לו. לכן היא מדה ומדה שיותן לו ולא לאחר. וכן הוא להיפך. הרשע על ידי חטאיו הביא את הצדיק לידי הרהור עבירה, ונעשה הצדיק חבירו של הרשע, ונגזר עליו להיות לו חלק בגיהנם. ואחר כך חזר הצדיק לתמותו והחזיק בצדקו, נוטל הרשע חלקו בגיהנם שהביאו לידי הרהור עבירה. וכפעלו ישולם לו, וכך היא המדה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ה, ד (סי' קטז).</b>\n<i>זכה נוטל כו'</i> – חגיגה טו, א.<i> דאיתא בכתבי האר\"י זלה\"ה</i> – ראה ספר הגלגולים פ\"ט.<i> אוי לרשע אוי לשכנו</i> – סוכה נו, ב.<i> הרשעים מלאים חרטות</i> – עקידת יצחק פ' אמור שס\"ז שלהי פ\"ז (קכז סע\"א) מספר המדות. ר\"ח שער היראה פ\"ג. ראה נדרים ט, ב.<i> המקדש את האשה על מנת כו'</i> – קידושין מט, ב.<i> וכפעלו ישולם לו</i> – ע\"פ ירמיה כה, יד.\n----- הערות וציונים -----\nראה סי' טו ד\"ה וכבר אמרנו.\nהובא בס' עבודת ישראל, ליקוטים, מסכת חגיגה: זכה צדיק נוטל חלקו וחלק חבירו בגן עדן נתחייב רשע נוטל חלקו וחלק חבירו בגיהנם. וצריך להבין מהות התשלומין מדוע יזכה הצדיק בחלק חבירו, ומדוע ילקה הרשע בחלק חבירו, הלא כתיב כי אתה תשלם לאיש כמעשהו, ולא יותר. אמנם נקדים מאמר מורנו החסיד הקדוש ז\"ל שאמר שהצדיק מוכיח לרשע ורוצה להחזירו בתשובה, אי אפשר שלא יטמא הרשע במחשבתו להצדיק באיזה הרהור קטן באפס מה. וזה הוא מחמת התקשרותם באותה שעה שרוצה הצדיק להחזיר הרשע ולקשר בעצמו, והענין נמשל לאדם המטאטא את הרחוב המלוכלך מזבל, הגם שישמור את בגדיו מאוד לא יחדל מלכלוך וכתם קטן באפס מה והוא מסוג הנמנע. וכן הדבר הזה בדקות ורוחניות וכמ\"ש לעיל פירוש הכתוב טוב מעט לצדיק, מה שהטוב הוא בבחינת מעט להצדיק, הוא מהמון וכו', שהם גורמים להתיש כח הקדושה על ידי רשעתם ומחשבותם עכ\"ל. והנה בוודאי אם הצדיק מתכוון להוכיח את הרשע, בוודאי שאינו נענש על ההרהור שבא לו שנכתם מעונות הרשע, כי כלפי שמיא גליא שאינו רוצה בזה, כי אם הרשע מחטיאו בהתקשרותו, ועתה נדבר מדרך הכסילים והרשעים, הגם ששומע איזה תוכחת מוסר מהצדיק ולבו ימס בקרבו מדברי הצדיק, ובודאי מתחרט על כל פנים באפס מה על עונותיו, כי דברים היוצאים מן הלב נכנסין ללב. ואחר כך חוזר לאיסורו וחטאיו ואולתו לא תסור ממנו. ויש רשעים התוהים על הראשונות ושונא את החכם על תוכחתו, כי נשבר לבו בקרבו רגע מחמת דברים שקשים כגידין ששמע ממנו. ואם כן בודאי הרשע הזה אינו מקבל שכר על הרהור תשובה שהרהר בעת שמעו תוכחת מוסר מהצדיק, כי לא רצה בזה, ובפרט כשתוהא על הראשונות, ואז המשפט כנוגה יצא ששכר הרהור עבירה הנ\"ל שעבר על הצדיק בשעת תוכחתו לרשע על ראש רשע יחול, ובהיפך שכר הרהור תשובה שעשה הרשע בעל כרחו נוטל הצדיק. נמצא פירוש הגמרא שזה שלא זכה נוטל חלקו וחלק חבירו שהוא הצדיק שנעשה חבירו והתקשר עמו בתוכחה כנ\"ל, ועבר על איזה הרהור עבירה. והוא משל הרשע, נמצא ששייך לרשע, אבל זכה, שהוא הצדיק, נוטל חלקו וחלק חבירו שהרהר בתשובה. כי זה חלק הצדיק וקדושתו, וכלפי שמיא גליא.\nומ\"ש שם \"וכמ\"ש לעיל . . טוב מעט לצדיק\" ראה שם פ' שמיני ד\"ה וישא אהרן את ידיו, ושם: מ\"ש מורי ז\"ל בפסוק (תהלים לז, טז) טוב מעט לצדיק מהמון רשעים רבים, פירוש כי על ידי מעשה הרשעים וכתמי פגמי עוונותיהם נטמא הארץ עד שנכנס איזה כתם אפילו בעבודת חכמי דורם שאין להם בהירות כל כך וגדלות המוחין כראוי, וכמו שאמר משה כצאתי את העיר אפרוש כפי אל ה', ופירש\"י מחמת שהעיר היתה מלאה גילולים עי\"ש. וזה פירוש טוב מעט לצדיק, זה שהטוב הוא בבחינת מעט לצדיק, הוא על ידי המון רשעים רבים עכ\"ל החכם ז\"ל.\nועיין עוד במאור עינים ר\"פ נח: דכשהצדיק מוכיח את הדור ואין רוצים לקבל מוסר הוא נוטל מהם את החלק הטוב שלהם, וזהו אמרם ז\"ל זכה נוטל חלקו וחלק חבירו בגן עדן, לאו דווקא בעולם הבא נאמרו הדברים אלא אפילו בעולם הזה שהוא נוטל את החלק הטוב שבתוכם אם מוכיח אותם ואינם רוצים לקבל, ואסבריה מורי לדבר זה כי הדבור מפי הצדיק לאוזן השומע והדיבור הוא דבר רוחני והוא מדריגה עשירית והשמיעה היא גם כן היא דבר רוחני והיא מדריגה עליונה למעלה מהדבור וכשהוא שומע ואינו מקבל מוסר לוקח הצדיק חלק השמיעה שלו שהדבור של הצדיק חוזר אליו עם חלק השמיעה של השומע. (ודבריו הובאו באורח לחיים ר\"פ נח, ועיי\"ש מה שהאריך בזה.)\n<i>דאיתא בכתבי האר\"י זלה\"ה</i> – ראה ספר הגלגולים פ\"ט.\n<i>שהרשע אם מרבה לחטוא כו'</i> – ראה סי' תפט. להעיר משל\"ה שער האותיות סוף אות צ.\n<i>וכן הצדיק במעשיו הטובים כו'</i> – שם. ועיין כש\"ט סי' קיג-ב וסי' ער, ובהערות שם.\n<i>ומביאו לידי הרהור תשובה</i> – ראה סי' טו ד\"ה וכבר אמרנו, וסי' רמח ד\"ה והנה כשהצדיק, ובנסמן בהערות שם."]]],[400080553,"תפח\n\n<b>הבנים</b> יוצאים בקשרים ובני מלכים בזגין וכל אדם אלא שדיברו חכמים בהוה. ויש לפרש דרך רמז על פי מה שאמרו רז\"ל הרבה עשו כרשב\"י ולא עלתה בידם והרבה עשו כרבי ישמעאל וכו'. והנה הצדיקים אשר תורתם אומנתם והוא מוכרח להמציא טרף לביתו, ומוכרח לבטל מלימודו ולחזור בשוקים וברחובות. הנה מה עושה הצדיק הנזכר טרם צאתו לשוק, הוא מתפלל ומתחנן לפניו ית', ומקשר נשמתו במחשבה קדושה שלא ילכד במצודת היצר בצאתו. והנה ידוע כי מי שיש לו נשמה שהיא מן הבינה נקרא בן. ויש אדם שלא זכה אלא לחלק נפש בלבד, שהיא מדת המלכות, וזה נקרא בן מלך.\n<b>וזהו</b> אפשר הרמז במשנה. הבנים, דהיינו אותם שיש להם נשמה, יכולים לצאת בקשרים, ר\"ל שיקשר נשמתו בשורשו הנקרא מחשבה כידוע, ויכול לצאת כנזכר. על דרך משל, מי שרוצה לירד לבור עמוק מאוד מקשר את עצמו מלמעלה. כי מתיירא שלא יוכל לחזור ולעלות מן הבור, לכן מקשר את עצמו מלמעלה בחבל ארוך, ודרך החבל יכול לחזור ולעלות. אבל מי שהוא רק מבני מלכים, דהיינו שאין לו רק נפש, או אפילו רוח, אך עדיין אין לו חלק נשמה, לא יסמוך על קישור מחשבתו מפני שלא השיג עדיין מדריגת מחשבה, ואולי לא יהיה הקשר אמיץ וחזק ויפול בעמקי הבור. ע\"כ זה צריך לצאת בזגין, שהם המשמיעים קול, ר\"ל קול ודיבור בדברי תורה, שהם מדריגת שורשו כידוע, ותגין עליו שלא ילכד חס ושלום. וכל אדם, פירוש זה קאי על הסיפא, וכל אדם לא יסמוך על זה שיקשור מחשבתו, כי אולי עדיין לא השיג למדריגת נשמה. אלא מה שדיברו חכמים הבנים יוצאים בקשרים לא דיברו אלא בהוה, ר\"ל בהוה להם, שהם היו חכמים והשיגו למדריגת חכמה שהוא נשמה לנשמה, ומכל שכן שהיה להם נשמה. אבל כל אדם לא יסמוך על זה, אלא יצא בזגים הנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ה סע\"ב (סי' קיג).</b>\n<i>הבנים יוצאים כו'</i> – שבת סו, ב.<i> הרבה עשו כרשב\"י כו'</i> – ברכות לה, ב.<i> נשמה שהיא מן הבינה כו'</i> – זו\"ח יתרו לא, ג. שם לג, א. תקו\"ז תי\"ג כח, א. וראה זח\"ב צד, ב.<i> נפש . . מדת המלכות</i> – זו\"ח יתרו לג, ב. תקו\"ז תכ\"א מט, א. ראה זח\"ב צד, ב.<i> בן מלך</i> – ראה זח\"א כז, ב.<i> נשמתו בשורשו הנקרא מחשבה</i> – תקו\"ז תכ\"ב סח סע\"ב. זו\"ח יתרו לד, ב.<i> עד\"מ מי שרוצה לירד כו'</i> – ראה זח\"א קיב, ב.<i> החכמה שהוא נשמה לנשמה</i> – ע\"ח ש\"ד פ\"א. שם ש\"ו פ\"ה. שמ\"ב פ\"ב ופ\"ה.\n----- הערות וציונים -----\nהובא בס' באר מים חיים ר\"פ נח: וכזה שמעתי בשם הרב איש אלקים בוצינא דנהורא רבה ויקירא שם קדשו מוהר\"ר דוב בער מגיד מישרים דק\"ק מעזריטש שאמר על משנת חז\"ל הבנים יוצאים בקשרים ובני מלכים בזגים וכל אדם אלא שדיברו חכמים בהוה, פירוש אלו אשר נקראו בנים לקודשא בריך הוא ושכינתיה והם אשר שכחו מחפצי עצמם מכל וכל והתקשרו והתדבקו עצמם בקשר אמיץ וחזק שלא להתאוות לשום דבר בעולם כי אם כברא דאשתדל בהון בתר אבוי ואמיה דרחים לון יתיר מגרמיה ונפשיה וכו' וכל מה דהוי ליה הוה חשיב לון לאין למעבד בהון רעותא דאבא ואמא וכו' כמו שכתב בזוה\"ק [זח\"ג רפא סע\"א], הנה הם יוצאים בקשרים שמותר להם לצאת לשוק לעמוד החוצה כיון שהם קשורים ומקושרים בקשר אמיץ וחזק בה' אלהיהם מותר להם לראות בכל הדברים ולדבר בכל הדברים שבעולם כי לא יפסיקוהו ולא יטרידוהו מדביקתו האמיתית, אדרבה הוא יעלה כל הדברים שבעולם למעלה למעלה. אבל ובני מלכים, מי שהוא מסטרא דמלכותא תתאה באופן שאינו מקושר כל כך, הם מוכרחים לצאת בזגים כלומר כזג המקשקש בקול תורה וקול תפילה וחלילה להם להפסיק מדביקות תורה ותפילה אף רגע אחד. וסיים המשנה וכל אדם, כלומר כל אדם הוא בדרגה זו דרגת בני מלכים, אלא שדיברו חכמים בהוה, כמו שהם היו, ודיברו לפי בחינתם הגדולה והם היו יכולים לראות ולדבר בכל הדברים ולהעלות הכל למרום שבתן, וכאשר מצינו כמה פעמים בגמרא שדיברו מפשוטי הויות העולם וכולם הם סודי סודות רזין עילאין ויקירין כי העלו כל בחינת הדיבורים ההם למקור שורשם אשר נלקחו משם.\nובקשר לזה עיין בהערות לסי' קכג ד\"ה ולא כמו שאר בני אדם. ולהעיר עוד מכש\"ט סי' רמד וסי' שסו, ובהערות שם. ולעיל סי' לו ד\"ה ואפשר (ואילך), וסי' שו, ובהערות שם. והשוה מש\"כ בתוי\"י פ' יתרו נד, א ד\"ה ובזה יבואר ג\"כ פסוק מי יתן טהור מטמא. ושם פ' משפטים נט סע\"ג ד\"ה ובזה יבואר עוד צחות לשון התנא (ועיי\"ש מש\"כ לפני זה בהמשך להמובא בכש\"ט סי' קיג-ב).\n<i>על פי מה שאמרו רז\"ל הרבה עשו כרשב\"י כו'</i> – ראה לקמן סי' תקא-א."]]],[400080554,"תפט\n\n<b>זה</b> הכלל כל שאינו מחויב בדבר אינו מוציא את הרבים ידי חובתן. ויש לדקדק מה שינוי הלשון שאינו מחויב, ולא אמר מי שאינו חייב בדבר. או הוי ליה למימר בסיפא כרישא, אינו מוציא את הרבים ידי חיובן. ויש לתרץ על פי הקדמה כי כאשר הרשע מרבה לחטוא הוא גורם בעוונותיו שיבוא לידי צדיק הרהור מעבירה מעין אותה עבירה שעבר הרשע. וגם זה ידוע שאין הדין מתמתק אלא בשורשו, ומחמת זה יכול הצדיק לגרום להעלות גם נפש הרשע מן החטא. כי הצדיק כשבא לידי ההרהור עבירה, תיכף מתחרט וחוזר בתשובה, ומעלה ומברר את הטוב מתוך הרע, וגם את הרע ממתיק בהעלותו אל שורשו. וזהו שאמרו רז\"ל כל שאינו מחויב בדבר, ר\"ל כל שלא נתחייב בדבר עבירה, דהיינו שלא בא לו הרהור עבירה זו שעשה הרשע, אינו יכול להוציא את הרבים ידי חובתן, דהיינו הרשעים הנזכרים. מפני שלא באה לו הרהור, אינו יודע מעין איזה עבירה עבר הרשע שיהיה יכול למתקו ולהוציא [את] הרשע מחובתו. אבל מי שמחויב בדבר, כלומר שנתחייב בדבר עם הרשע שגרם לו ההרהור כנזכר, יכול להוציאו ידי חובתו. ולכך אמרו שמחוי\"ב, ולא אמרו שחייב, כי לא מחמתו באה לו ההרהור, כי אם על ידי הרשע. אבל גבי הרשעים אמרו ידי חובת\"ן, שהם חייבים בנפשותם, ולא אחרים מחייבין אותם.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ה, ב (סי' קיב).</b>\n<i>זה הכלל כל כו'</i> – ר\"ה כט, א.<i> שאין הדין מתמתק אלא בשורשו</i> – ע\"ח שי\"ג פי\"א. פע\"ח שער השופר פ\"ה.\n----- הערות וציונים -----\n<i>כאשר הרשע מרבה לחטוא כו'</i> – ראה סי' תפז ובהערות שם.\n<i>יכול הצדיק לגרום להעלות כו'</i> – שם.\n<i>הצדיק תיכף מתחרט . . ומעלה ומברר כו'</i> – ראה כש\"ט סי' רמד."]]],[400080555,"תצ\n\n<b>או</b> יש לומר, מי שאינו מחוייב בדבר, פירוש שנתחייב האדם בגלגול ראשון, ובא בגלגול הזה כדי לתקן את המעוות. וכמ\"ש כמה תנאים ואמוראים היו יודעין מאיזה גלגול הוא בא ואיזה דבר הוא צריך לתקן, כמ\"ש תיתי לי דקיימתי מצות ציצית, וזה אמר תיתי לי דלא מסגינא ד' אמות בלא תורה ותפילין, וכיוצא בזה. והנה הצדיק היודע על איזה דבר עבירה נתגלגל, ויודע שבגלגול הראשון היה חוטא ומחטיא את הרבים, והנה הוא צריך לתקן את הדבר ולזכות את הרבים ולהוכיחם להחזירם למוטב שישובו בתשובה שלימה. וז\"ש כל מי שאינו מחויב בדבר כבר, כלומר מגלגול הא', או שהוא באמת<sup data-n=\"1\">עו</sup> מגלגול הא', רק שאינו יודע פרט החטא שנתגלגל עליו, ואינו יודע שהוא מחויב לזכות ולתקן את הרבים, זה אינו מוציא הרבים ידי חובתן, כלומר אינו יודע שיועיל תיקונו שהוא רוצה לתקן ולזכות את הרבים, כי אפשר שנתגלגל בשביל דבר אחר. אבל מי שיודע בשביל איזה חטא הוא נתגלגל, ויודע שהוא מחויב בדבר זה מכבר, הוא יכול להוציא את הרבים מחובתן כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ה, ב (סוף סי' קיב)</b>\n<i>מי שאינו מחוייב בדבר כו'</i> – ר\"ה כט, א.<i> שנתחייב האדם כו' לתקן את המעוות</i> – ראה תקו\"ז ת\"ע קלא, א. שער הגלגולים הקדמה ב. ספר הגלגולים פ' ה-ו.<i> תיתי לי כו'</i> – שבת קיח, ב.\n----- שולי הגליון -----\n<b>עו</b> ) <i>ברור שכאן חסר (וכן בלקו\"י), ואולי צ\"ל</i> באמת מחוייב.\n----- הערות וציונים -----\n<i>כמ\"ש כמה תנאים ואמוראים כו'</i> – ראה שער הגלגולים, הקדמה טז. ספר הגלגולים פ\"ד.\n<i>ומחטיא את הרבים והנה הוא צריך לתקן כו'</i> – ראה מש\"כ בשער הגלגולים, הקדמה יא."]]],[400080556,"תצא\n\n<b>אמר</b> הקדוש ברוך הוא לוו עלי ואני פורע. וקשה למה המדה כך, ולא [נ\"א: ולמה לא] (יזדמן) [יזמין] הקדוש ברוך הוא לעני שיהיה לו על סעודות שבת ולא יצטרך ללות. וי\"ל על פי הלצה, כי ידוע אין הברכה שורה אלא על איזה דבר, אף שהוא מועט מתברך, כמו אסוך שמן דאלישע. אבל אין הברכה שורה על דבר ריקן, אם לא שיעשה הקדוש ברוך הוא נס מפורסם, כי היינו יש מאין. והנה אין [הכל] רוצים להנות ממעשה נסים, כמו שמצינו כמה תנאים ואמוראים. וזה (שכתוב) [שאמר] לוו עלי, כי זה מדבר בעני בעת שביתו ריקן, ואין כל בבית אפילו דבר מועט שתשרה עליו הברכה, בכדי שלא יהיה הנס מפורסם וניכר לו כל כך. ואם ירצה הקב\"ה לעשות לו נס מפורסם, אפשר שלא ירצה להנות. לזה אמר לוו עלי [ואני פורע] וכו', כמ\"ש בגמרא המודר הנאה מחבירו פורע את חובו, אם כן מצינו שפריעת חוב אינו הנאה, אם כן לא יחוש העני וילוה ויענג את השבת. ואף על פי שהקב\"ה יפרע את חובו, אין זה מיקרי הנאה ממעשה נסים כנזכר. (<sup data-n=\"1\">עז</sup>ואף על גב דבגמרא מוקי לה באותו החוב שאין המלוה תובע (אלא) [את] הלוה, שאם ירצה לא ישלם למלוה [כדאיתא שם], גם הכא המלוה לעני כזה מסתמא ג\"כ מלוה לו על מנת שלא לתובעו.)",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ה, א (סי' קיא)</b>\n<i>אמר הקב\"ה לוו עלי כו'</i> – ביצה טו, ב.<i> אין הברכה כו' כמו אסוך כו'</i> – זח\"א פח, א.<i> אסוך שמן דאלישע</i> – מ\"ב ד, ב.<i> אין רוצים ליהנות ממעשה נסים כו'</i> – תענית כד, א (ופרש\"י שם ד\"ה אלא כאחד), ושם ע\"ב.<i> המודר הנאה מחבירו כו'</i> – נדרים לג, א.<i> דבגמרא מוקי לה כו'</i> – שם ע\"ב.\n----- שולי הגליון -----\n<b>עז</b> ) <i>בלקו\"י אין סוגריים.</i>\n----- הערות וציונים -----\n<i>אין הברכה שורה אלא על כו'</i> – ראה סי' שסג ד\"ה והנה (ואילך).\n<i>אין רוצים להנות ממעשה נסים</i> – ראה של\"ה, תושב\"כ ס\"פ לך לך."]]],[400080557,"תצב\n\n<b>אמר</b> דוד שמרה נפשי כי חסיד אני, ולא חסיד אני שכל מלכי מזרח ומערב ישנים עד שלשה שעות ואני חצות לילה אקום, [ועוד] לא חסיד אני שכל מלכי וכו' ואני ידי מלוכלכות בשפיר ובשליא כדי לטהר אשה לבעלה. ויובן על פי מה שכתוב בזוהר כל אשתדלותא דדוד מלכא לחברא אתתא לבעלה [וכו'], והיה ממתיק הדינים ע\"י החסדים. וזהו ידוע כי הדינים נקראים לי\"ל, וכשהוא ממותק נקרא ליל\"ה, כמו נע\"ר ונער\"ה. וזהו שנאמר חצות לילה אקום להודות [לך], פירוש על ידי הודאות ושירים ותשבחות הייתי מושך החסדים וממתיק הדינים, והייתי חוצה הלילה לשנים, ונסתלקו הדינים שהוא לי\"ל, ונשאר רק ה'. ולא שנסתלקו הדינים לגמרי, אלא שנשארו ממותקים, והרי הם כמו שנתעלמו מחמת משיכת החסדים, כי שרגא בטיהרא מאי מהני. ובמה הייתי ממתקם, על ידי שבחות והודאות כנזכר, והייתי ממתקם בשרשם, דהיינו בכ\"ב אתוון שהם ה' מוצאות הפה, והתחלות הה' מוצאות הם ה' אלפי\"ן הידועים. (והם א' מאדנ\"י הממתיק דין מאדנ\"י) שהם חסדים גמורים<sup data-n=\"1\">עח</sup>. וזהו אקו\"ם, שהייתי (קיומא) [מקיימם] על ידי שורשם הה' הנזכר [ה\"ח הנ\"ל<sup data-n=\"2\">עט</sup>]. וזהו בהבראם, בה' בראם. וזהו הכל לפי שחסיד אני, כמו שכתוב בזוהר ולא עם הארץ חסיד לפי שחסר לו היו\"ד שהיא החכמה. אבל בהיות שחסיד אני, מדובק בחכמה, הייתי יכול למתקם בשרשם, שהם ה' אלפין כנזכר שהם בחכמה כנודע.\n<b>ומה</b> שכתוב ולא חסיד אני וכו' שידי מלוכלכות בשפיר ובשליא, פירוש כי הלוא ידוע שיש חיצוניות (ו)בכל התורה והמצות שהוא שומר לפרי, והוא נמשל לשפיר ושליא, שאין הוולד יכול להתהוות אם לא על ידי החיצוניות. כמו שיש חיצוניות אל מצות התשובה, דהיינו שעושה תשובה מיראת עונש, כמו שאמרו רבותינו ז\"ל ע\"פ ופרעה הקריב, שהקריב את ישראל לתשובה. וכי פרעה נתכוון להקריבם לתשובה, אלא היה רק כמו הקליפה שומר לפרי, ואחר כך מצאו ישראל הפרי עצמו ואכלו, ועשו תשובה כהוגן, ומתוך שלא לשמה וכו'. וזהו ידי מלוכלכות, פירוש שהייתי מסתכל בחיצוניות המצות והתורה, ויגעתי ומצאתי להוציא מהם פרי ולטהר אותם מכל החיצוניות. וידוע כי התורה והמצוה נקרא אש\"ה, וזהו [לטהר] אשה לבעלה, להוציא הפנימיות זך ונקי בלי שום סיג. וידוע מהזוהר כי הכל במחשבה אתברירו, שהוא חכמה כנודע, ולכן אמר ולא חסיד אני כנזכר, שהוא בחכמה כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רמב (רנה).</b>\n<i>אמר דוד שמרה נפשי כו'</i> – ברכות ד, א.<i> שמרה נפשי גו'</i> – תהלים פו, ב.<i> חצות לילה אקום</i> – תהלים קיט, סב.<i> כל אשתדלותא דדוד כו'</i> – זח\"ג מ, ב.<i> הדינים נקראים לי\"ל כו' נע\"ר ונער\"ה</i> – זח\"ב לח, ב. פרדס רמונים ש\"ה פ\"ב. פע\"ח שער תיקון חצות פ\"ג.<i> שרגא בטיהרא כו'</i> – חולין ס, ב.<i> ה' אלפי\"ן כו'</i> – ע\"ח שי\"ח פ\"ה.<i> בהבראם</i> – בראשית ב, ד.<i> בה' בראם</i> – מנחות כט, ב.<i> כמש\"כ בזוהר ולא ע\"ה כו'</i> – זח\"ג לג סע\"א ואילך.<i> ולא ע\"ה חסיד</i> – אבות פ\"ב מ\"ה.<i> שיש חיצוניות בכל התורה והמצות</i> – זח\"ג קנב, א. שם קנט, א. ראה שם עב, ב. ועג, א.<i> שומר לפרי</i> – ע\"פ ברכות לו, ב.<i> כמו שאמרו רז\"ל ע\"פ ופרעה הקריב כו'</i> – שמ\"ר כא, ה.<i> ופרעה הקריב</i> – בשלח יד, ה.<i> הקליפה שומר לפרי כו'</i> – ראה זח\"ב קח רע\"ב. חסד לאברהם מעין שביעי נהר כז. של\"ה תול\"א בית ישראל ד\"ה והנה הקליפה (יט, ב).<i> ומתוך שלא לשמה וכו'</i> – פסחים נ, ב.<i> כי התורה . . נק' אש\"ה</i> – יבמות סג, ב.<i> הכל במחשבה אתברירו</i> – זח\"ב רנד סע\"ב. ע\"ח שי\"ח פ\"ה. שם שי\"ט פ\"ט ושל\"ט פ\"א. שער המצות פ' עקב.\n----- שולי הגליון -----\n<b>עח</b> ) <i>במדל\"י נ\"א:</i> והייתי ממתקן בשורש הכ\"ב אותיות שהם ה' מוצאות הפה, הם ה' אלפי\"ן הידועים שהם חסדים גמורים (והם א' דאדנ\"י הממתיק דין דאדנ\"י).\n<b>עט</b> ) <i>ה' חסדים הנזכרים.</i>\n----- הערות וציונים -----\n<i>הדינים נקראים לי\"ל וכשהוא ממותק נקרא ליל\"ה</i> – ראה מדל\"י סו\"ס קיב (קכג).\n<i>וזהו בהבראם בה' בראם</i> – ראה סי' ל ד\"ה ואפשר לומר כי (ואילך), וסי' קעט-ב ד\"ה והנה עשה.\n<i>ופרעה הקריב כו' כמו הקליפה שומר לפרי כו'</i> – עיין כש\"ט סי' שצו.\n<i>במחשבה אתברירו שהוא חכמה</i> – ראה סי' כד ד\"ה אך. ועיין לקו\"י סי' קנה."]]],[400080558,"תצג\n\n<b>איזהו</b> חכם הלומד מכל אדם שנאמר מכל מלמדי השכלתי. ודקדק <i>הרב מהו' מיכל נר\"ו</i> למה לא אמר הלומד מכל מלמד, כלשון הכתוב מכל מלמדי. ותירץ כי התנא בא להוסיף כי לא תורה בלבד יש ללמוד ממלמדיו, אלא אפילו שאר מדות והנהגות טובות, דהיינו איזה הנהגה ישרה או מדה טובה באדם. אפילו מעם הארץ או מרשע יתן בדעתו מנהג זה וילמדנו ממנו. וזהו איזהו חכם, הלומד מכל אדם איזה מדה טובה והנהגה ישרה בעבודת הבורא יתברך.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ד (סי' קה).</b>\n<i>איזהו חכם הלומד כו'</i> – אבות פ\"ד מ\"א.<i> מכל מלמדי השכלתי</i> – תהלים קיט, צט.\n----- הערות וציונים -----\nבכש\"ט הוספות סי' קטו בשם הבעש\"ט. וראה כש\"ט סי' שסג, ושם בהוספות סי' קיד."]]],[400080559,"תצד\n\n<b>אהבה</b> דוחקת הבשר. רצה לומר אהבת השם דוחקת ומזככת את הבשר שהוא הגוף.\n<b>(עוד</b><sup data-n=\"1\">פ</sup> יש לומר שאהבה דוחקת וממתקת את הבשר שהוא דין, כי הבשר בא מסטרא דדינא כידוע.)",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ד (סי' קד).</b>\n<i>אהבה דוחקת הבשר</i> – ב\"מ פד, א.<i> הבשר בא מסטרא דדינא</i> – זח\"ג רנה רע\"ב. ראה שם לג, ב.\n----- שולי הגליון -----\n<b>פ</b> ) <i>בלקו\"י אין סוגריים</i>."]]],[400080560,"תצה\n\n<b>מאשר</b> יקרת בעיני נכבדת וגומר ואתן אדם תחתיך. יובן כפשוטה, על דרך משל למלך שיש לו בן אהוב וחביב ויקר בעיני המלך עד מאוד. והנה שריו ועבדיו רוצים ליתן הימנון למלך בשבח וקילוס והילול והודיה, אך מחמת גודל אימת המלך לא היה להם פתחון פה, כי נורא הוא מאוד. מה עשו, אמרו בלבם הלוא זה ידוע כי עיקר תענוג המלך ושמחתו הוא כבוד בנו חביבו וידידו. לכך תחילת כל השבח התחילו לשבח מעשה בנו לפני המלך. ובזה יגרמו שמחה ותענוג להמלך, ויהיו יכולים אח\"כ לפתוח פיהם בשבחו של המלך. כן כביכול המלאכים אומרים לפניו ברוך ה' אלהי ישראל, וכמ\"ש ואתה קדוש יושב תהלות ישראל. וזהו מאשר יקרת בעיני, רצה לומר מפני שהכל יודעים שאתה יקר ואהוב וחביב בעיני נכבדת.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א עג, א.</b>\n<i>מאשר יקרת גו' ואתן אדם גו'</i> – ישעיה מג, ד.<i> המלאכים אומרים לפניו כו'</i> – תנחומא במדבר יט.<i> ברוך ה' גו'</i> – תהלים מא, יד.<i> ואתה קדוש גו'</i> – תהלים קו, מח.\n----- הערות וציונים -----\nשייך לחלק פסוקים מלוקטים.\n<i>יובן כפשוטה כו'</i> – ראה תנחומא במדבר יט. במ\"ר ד, א."]]],[400080561,"תצו\n\n<b>עוד</b> יש לומר, כי הנה המלך האוהב את בנו מאוד, מחמת גודל אהבתו הוא מסתכל תמיד בפני בנו ומשגיח עליו בעינא פקיחא. והנה המסתכל באיזה דבר, אזי כח הראות הוא מלביש אותו דבר ומסבב אותו כח הראות ההוא. וידוע שלבו\"ש נקרא כבו\"ד, כי הא דרבי יוחנן קרא למאניה מכבדותיה. וזהו מאשר יקר\"ת, רצה לומר מאחר שאתה יקר וחביב לי אני מסתכל בך תמיד, כמו שכתוב עי\"ן יעקב. וזהו בעיני נכבדת, רצה לומר בכח הראות עיני נתלבש\"ת כביכול. [וזהו שנראית דמות אדם בבת עין, על דרך יצרנהו כאישון עינו. וזה ישראל עלה במחשבה.] ולא עוד, אלא כדכתיב צדיק מושל ביראת אלהים וכו', אלמלא כתוב א\"א לאומרו, כמו שכתוב ועל דמות הכסא כמראה אדם [כו'] כביכול ואתן אדם תחתיך, שהוא יתברך גוזר ואתה מבטלו, [על דרך אז תתענג על ה', והמשכיל יבין].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קפה (קצא).</b>\n<i>דרבי יוחנן קרא כו'</i> – שבת קיג, א.<i> מאשר יקרת גו'</i> – ישעיה מג, ד.<i> עי\"ן יעקב</i> – ברכה לג, כח.<i> יצרנהו כאישון עינו</i> – האזינו לב, י.<i> ישראל עלה במחשבה</i> – זח\"א כד, א. בר\"ר א, ד.<i> צדיק מושל גו'</i> – ש\"ב כג, ג.<i> ועל דמות הכסא גו'</i> – יחזקאל א, כו.<i> שהוא ית' גוזר ואתה מבטלו</i> – מו\"ק טז, ב. [<i>אז תתענג על ה'</i> – ישעיה נח, יד].\n----- הערות וציונים -----\nשייך לחלק פסוקים מלוקטים.\n<i>מחמת גודל אהבתו כו'</i> – ראה ריש סי' קל, וסי' שצב. וראה סי' ו ובהערות שם.\n<i>ועל דמות הכסא כו'</i> – להעיר מסי' קלד ובהערות שם.\n<i>על דרך אז תתענג על ה' כו'</i> – ראה זח\"ב פג, א. זח\"ג צד, ב."]]],[400080562,"תצז\n\n<b>הבא</b> לטהר מסייעין אותו. ויש לומר, כי הנה אנו רואים אדם הבא לטהר את עצמו, דהיינו שרוצה להתפלל בכוונה [גדולה] לפניו יתברך ועושה הכנה גדולה לזה, ובעומדו להתפלל בתוך עיקר כוונתו באמצע התפילה באה לו מחשבה זרה. והיכן הוא הסיוע לזה מלמעלה, [הלא הוא הכין את עצמו לטהר מחשבתו ולזכך תפילתו]. אך האמת הוא, כי אדרבא זהו הסיוע שלו, כמבואר בדרושים הקודמים שהשם יתברך שולח זאת [המחשבה] לאדם בכדי להעלותה, על דרך מגלגלין זכות על ידי זכאי, ואין המחשבה ההיא (עיקרית) [מקריות] אלא להעלותה לשורשה. כגון שבאה לו מחשבה זרה מאהבה רעה או מיראה רעה, וכן כיוצא בזה, והוא מדחה המחשבה הרעה ההיא ומדבק את עצמו באהבה או ביראה דלעילא, ומסיים תפילתו בהתלהבות יותר גדולה, ובזה מוציא ניצוצות מהקליפה. וזהו הסיוע שמסייעין אותו.\n<b>וזהו</b> פירוש הפסוק וזרח השמש [ובא השמש], רצה לומר שהאדם עומד להתפלל בהתלהבות וזרח לו השמש, ואחר כך פתאום באמצע התפילה ובא השמש, שאבד ההתלהבות שבאה לו מחשבה זרה. ולמה הוא כך, לזה אמר הטעם אל מקומו שואף, רצה לומר שוא\"ף הוא לשון ניתוק, כמו ש\"ף מדוכתיה. רצה לומר השם יתברך מזמן לו זה כדי שיהיה אדם זה שואף אל מקומו, פירוש שיוציא הניצוצות ויחזירם למקומם לשרשם בקדושה וזהו שאמר שואף זורח הוא שם<sup data-n=\"1\">פא</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רכ (רלב).</b>\n<i>הבא לטהר כו'</i> – שבת קד, א.<i> בדרושים הקודמים</i> – סי' קכג וסי' שסח.<i> מגלגלין זכות ע\"י זכאי</i> – שבת לב, א.<i> וזרח השמש גו'</i> – קהלת א, ה.<i> ואל מקומו שואף</i> – שם.<i> ש\"ף מדוכתיה</i> – חולין מב, ב.\n----- שולי הגליון -----\n<b>פא</b> ) <i>במדל\"י מסיים כאן:</i> וסוד השבירה מרומז בפסוק הכל הבל, ורעות הוא לשון שבירה. <i>וזה הובא לעיל בסוף סי' שעא עיי\"ש</i>.\n----- הערות וציונים -----\n<i>ואין המחשבה ההיא מקריות כו'</i> – ראה סי' קכג ד\"ה והנה ידוע, ובהערות שם. רג\"כ סי' תו."]]],[400080563,"תצח\n\n<b>כל</b> שמעשיו מרובים מחכמתו. רצה לומר שיש לו הרבה מעשים מחמת חכמתו, רצה לומר בשביל שהוא חכם ועושה אפילו דברים גשמיים לכבודו יתברך, חכמתו מתקיימת, ר\"ל מתקיימת עולמות שניתוסף להקדוש ברוך הוא. וכל (שאין) [שחכמתו] וכו', שאין בו חכמה זו, רק שהוא לומד בסתם, אחרי שהוא מבין מה שלומד אין חכמתו מתקיימת. כי אפילו חכמות התורה שהוא לומד, אם הוא בלא דחילו ורחימו, אינו כלום, כמ\"ש בזהר כל מלה בלא דחילו ורחימו לא סלקית.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ב (סי' צה).</b>\n<i>כל שמעשיו מרובים מחכמתו כו'</i> – אבות פ\"ג מ\"י.<i> וכל שחכמתו וכו'</i> – שם.<i> כל מלה בלא דו\"ר כו'</i> – תקו\"ז ת\"י כה, ב. ראה זח\"ג קכא ב.\n----- הערות וציונים -----\n<i>הרבה מעשים כו' בשביל . . אפילו דברים גשמיים כו'</i> – להעיר מסי' שסג ד\"ה והנה."]]],[400080564,"תצט\n\n<b>מי</b> שאין בו דעת אסור לרחם עליו. פי' כי מדת רחמנות באה מן הדעת, כי מכח הדעת יודע לרחם. ולפיכך אין במדת רחמנות שבירה [על דרך יעקב אבינו לא מת], כי הוא בא מכח הדעת, והדעת הוא רק חיים. וזהו דכתיב ובדעת חדרים ימלאו, ואין בו שבירה. ואף<sup data-n=\"1\">פב</sup> על פי שכתוב במדת רחמנות ויחמול על מיטב הצאן, ריחם עליהם, אבל במדת רחמנות עצמו אין בו שבירה כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קצג (רג).</b>\n<i>מי שאין בו דעת כו'</i> – ברכות לג, א.<i> מדת רחמנות באה מן הדעת</i> – ראה זח\"ב קסג, א. זח\"ג רעג, ב.<i> יעקב אבינו לא מת</i> – תענית ה, ב.<i> כי הוא בא מכח הדעת</i> – ראה זח\"ב יד, ב.<i> והדעת הוא רק חיים</i> – ראה זח\"ג קפב, א.<i> ובדעת חדרים ימלאו</i> – משלי כד, ד.<i> ויחמל . . ועל מיטב הצאן</i> – ש\"א טו, ט.\n----- שולי הגליון -----\n<b>פב</b> ) <i>הסיפא ליכא במדל\"י</i>.\n----- הערות וציונים -----\nעיין לעיל סי' שכט. ועיין לקו\"י יג, ד (סי' קנד): סוד יעקב אבינו לא מת, פי' כי בת\"ת לא היה שבירה, הגם שבת\"ת נמי כתיב וימת וימלוך [ראה ע\"ח ש\"ט פ\"ב] התירוץ הוא השבירה שהיה בת\"ת לא היה בת\"ת עצמו רק (בהסתכלות) [בהתכללות] שמתחבר החו\"ג כו' עיי\"ש. וכן במדל\"י סוף סי' רסה (רעג), עיי\"ש."]]],[400080565,"תק\n\n<b>גדולים</b> מעשה הצדיקים ממעשה בראשית.<sup data-n=\"1\">פג</sup> ר\"ל כי מעשה בראשית<sup data-n=\"1\">פג</sup> היה י\"ש מאי\"ן, וצדיקים עושים מיש אין. כי מכל הדברים שעושים, אפילו מגשמיות, דהיינו [נ\"א: כמו] אכילה, מעלים ניצוצות הקדושה מזה האכילה למעלה, וכן מכל דבר. נמצא שעושים מי\"ש אי\"ן, וד\"ל. ואמרו<sup data-n=\"2\">פד</sup> רז\"ל גדול נס האחרון וכו' וד\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' יא (יא). אוה\"א כט, א.</b>\n<i>גדולים מעשה הצדיקים כו'</i> – כתובות ה, א.<i> גדול נס האחרון כו'</i> – תענית כה, א.\n----- שולי הגליון -----\n<b>פג</b> ) <i>במדל\"י לשון הגמרא</i> ממעשה שמים וארץ.\n<b>פד</b> ) <i>הסיפא ליכא במדל\"י.</i>\n<i>----- הערות וציונים -----</i>\nעיין סי' קכ ד\"ה והנה. ובס' יושר דברי אמת פי\"ב: וזה שאמר גדולים מעשה צדיקים יותר ממעשה שמים וארץ, ואמר האלהי ר' דוב בער ז\"ל מפני שבריאת שמים וארץ היה השתלשלות יש מאין ירידה מעליון לתחתון, וצדיקים במעשיהם שמפשיטים א\"ע מגשמיות וחושבים בהשי\"ת תמיד ורואים ומבינים ומדמים באמת שהוא כאילו היה אין כקודם הבריאה, נמצא מחזירים מיש לאין, וזה יותר פלא להעלות מתחתון לעליון כמו שאמרו בגמרא ברחב\"ד גדול הנס האחרון מן הראשון כי מן השמים מיהב יהבי משקל לא שקלי."]]],[400080566,"תקא-א\n\n<b>הרבה</b> עשו כרשב\"י ולא עלתה בידם. הכוונה [היא] שהיו רוצים לעשות [לעצמם] סיגופים כדי שיבואו למדריגת רשב\"י, ולכך לא עלתה בידם. ולא יכוון בעבודתו כן, רק לעשות נחת רוח ליוצרו [ית' לבד], ולא שיבוא למדריגה.",[["","","----- מקורות ומראה מקומות -----\n<b>צוה\"ר סי' מז.</b>\n<i>הרבה עשו כרשב\"י כו'</i> – ברכות לה, ב.\n----- הערות וציונים -----\nראה כש\"ט סי' ד ובהערות שם."]]],[400080567,"תקא-ב\n\n<b>וכשהוא</b> רואה שעבודתו גדולה משל חבירו לא יתגאה ח\"ו, כדאיתא באותיות דר\"ע ואל יאמר בלבו אני גדול מחבירי.",[["","","----- מקורות ומראה מקומות -----\n<b>צוה\"ר סי' מח.</b>\n<i>באותיות דר\"ע ואל יאמר כו'</i> – אותדר\"ע אות ד.\n----- הערות וציונים -----\nראה צוה\"ר סי' יב ובהערות שם. ורג\"כ לעיל סי' שעג."]]],[400080568,"תקב\n\n<b>אל</b> תעש תפילתך קבע, פירוש שלא תתפלל לצורך עסקיך, אלא רחמים ותחנונים לפני המקום, ר\"ל בשביל השכינה הנקראת מקו\"ם. וכן הוא בספר הזהר שהם נקראים כלבים עזי נפש שצווחין הב הב וכו'. וזה שכתוב אחת שאלתי וגומר אותה אבקש, רצה לומר בשביל השכינה כנזכר<sup data-n=\"1\">פה</sup>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' יב (יג). אוה\"א כט, א.</b>\n<i>אל תעש תפלתך קבע</i> – אבות פ\"ב מי\"ג.<i> השכינה הנקראת מקו\"ם</i> – זח\"א כה, א.<i> בספר הזוהר שהם נקראים כו'</i> – תקו\"ז ת\"ו כב, א. ראה תקוזו\"ח קב סע\"ד.<i> כלבים עזי נפש</i> – ישעיה נו, יא.<i> הב הב</i> – משלי ל, טו. ראה זו\"ח אחרי מז סע\"ג.<i> אחת שאלתי גו'</i> – תהלים כז, ד.\n----- שולי הגליון -----\n<b>פה</b> ) <i>במדל\"י בשנויים: </i>אל תעש תפלתך קבע. ר\"ל אל יתפלל אדם על עסקי צרכיו, רק יתפלל תמיד בשביל השכינה שתגאל מגלות. וז\"ש אלא רחמים ותחנונים, ר\"ל שיתפלל תמיד לפני המקום, כלומר עבור השכינה הנקרא מקום כידוע. וכן הזוהר קורא אותן המתפללין בשביל עצמן ולא בשביל השכינה, נקרא כלבים עזי נפש הצועקים ואומרים הב הב. וזה פירוש הפסוק ג\"כ אחת שאלתי מאת ה' אותה אבקש, ר\"ל בשביל השכינה אני מבקש ומתפלל לפניך לתקן הפגם מה שעשו בעונות.\n----- הערות וציונים -----\nעיין סי' נו ובהערות שם. וראה אוה\"מ פ' לך לך ד\"ה ויהי כאשר הקריב: שמעתי מהמגיד זללה\"ה שביאר המשנה וכשאתה מתפלל אל תעש תפלתך קבע אלא רחמים ותחנונים לפני המקום, עבור השכינה שהיא מקומה של עולם להוציא את השכינה מגלות. ושם אסתר ד\"ה ובכל יום ויום: כשמתרמי לפעמים שנכון לבך להתפלל אז אל תעש תפלתך קבע לשאול עבור צרכיותך הגשמיות, אלא רחמים ותחנונים לפני המקום עבור השכינה שהיא מקומה של עולם, וזהו עיקר עבודה שבלב כל עצמו ומגמתו בהשפך שיחו רק עבור צורך גבוה. וכן שם ר\"פ שלח, ופ' בלק ד\"ה כי מראש."]]],[400080569,"תקג\n\n<b>שום</b> תשים עליך מלך. פי' מדת מלכות <span data-k=\"sm\">[העליונה]</span>. ופירשו<sup data-n=\"1\">פו</sup> רז\"ל איך שתהא אימתו עליך, ר\"ל זהו מדת יראה.\nסליק דברי תוכחות על אגדות חז\"ל בדרך מוסר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סוף סי' יא (יב). אוה\"א כט, א.</b>\n<i>שום תשים עליך מלך</i> – שופטים יז, טו.<i> מלכות . . מדת יראה</i> – תקו\"ז ו, א. שם תל\"ג עז רע\"א.<i> שתהא אימתו עליך</i> – סנהדרין כ, ב.\n----- שולי הגליון -----\n<b>פו</b> ) <i>במדל\"י, ועד\"ז באוה\"א, מסיים: </i>ועל זה אמרו רז\"ל שתהא אימתו עליך.\n----- הערות וציונים -----\nשייך לרמזי תורה פ' שופטים.\nעיין סי' תלח ד\"ה ואיתא, ובהערות שם ד\"ה תחילה.\n**********"]]]]});
